deliverables.text:
// SPDX-License-Identifier: Apache-2.0
//! Who governs a delivered path (OW-ADR-0021, SAS §37.5).
//!
//! A pin used to be forever: a resolved Warrant's `deliverables.toml` bound
//! each file's digest, and every later edit — however legitimate, under
//! however new a Warrant — needed a human-signed correction from every
//! Warrant that once delivered it. Under this module a path is governed by
//! the most recently AUTHORIZED Warrant whose recorded declaration set names
//! it. Earlier pins are historical: still recorded, still verifiable at their
//! own resolution, and not drift.
//!
//! Two facts shape the record this reads. Deliverables are not inside the
//! contract digest, so `deliverables.toml` can move after signing — which is
//! why the set is copied into `authorization.toml` at ingest, under the
//! attestation, and read from there and never from the manifest. And
//! `war pins --refresh` rewrites content digests during ordinary work, so the
//! thing an authorizer grants is the set of `(id, target_ref)` PAIRS, not
//! bytes. [`set_digest`] is the digest of exactly that.
//!
//! An authorization recorded before OW-ADR-0021 carries no set and owns
//! nothing. That is fail-closed and deliberate: nobody gains ownership without
//! a fresh human signature over a request that lists the paths.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

use crate::repo::{RepoError, Repository};

/// One `(id, target_ref)` pair as the authorizer saw it. Lives here rather
/// than in `authorize.rs` so `pins`, `correct` and `check` can name it without
/// importing the whole authorization surface.
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
pub struct OwnedDeliverable {
    pub id: String,
    pub target_ref: String,
}

/// The declared set of a Warrant, read from its `deliverables.toml`, sorted
/// by id so two readers agree on the digest.
pub fn declared_set(
    repo: &Repository,
    dir: &camino::Utf8Path,
) -> Result<Vec<OwnedDeliverable>, RepoError> {
    let mut set: Vec<OwnedDeliverable> = repo
        .load_deliverables(dir)?
        .records
        .iter()
        .map(|d| OwnedDeliverable {
            id: d.id.clone(),
            target_ref: d.target_ref.clone(),
        })
        .collect();
    set.sort();
    Ok(set)
}

/// sha256 over the RFC 8785 rendering of `[[id, target_ref], …]`, sorted by
/// id. Documented here rather than registered as a digest domain: it is a
/// fingerprint of a list, not a canonical artifact, and the compiler's domain
/// table is for things a foreign verifier recomputes.
#[must_use]
pub fn set_digest(set: &[OwnedDeliverable]) -> String {
    let mut sorted: Vec<&OwnedDeliverable> = set.iter().collect();
    sorted.sort();
    let pairs: Vec<[&str; 2]> = sorted
        .iter()
        .map(|d| [d.id.as_str(), d.target_ref.as_str()])
        .collect();
    let jcs = serde_jcs::to_string(&pairs).unwrap_or_default();
    format!(
        "sha256:{}",
        openwarrant_compiler::sha256_hex(jcs.as_bytes())
    )
}

/// One Warrant's claim on one path, as its authorization recorded it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Owner {
    pub alias: String,
    pub deliverable_id: String,
    /// The authorization's effective time — the ordering key. §67.2 calls a
    /// locally stamped time provisional; `authorize` refuses a time that
    /// precedes an existing owner of the same path so the order seen is the
    /// order recorded.
    pub authorized_at: String,
    pub resolved: bool,
}

/// Every governed path in the corpus, newest owner first.
#[derive(Debug, Default, Clone)]
pub struct Ownership {
    by_path: BTreeMap<String, Vec<Owner>>,
}

/// Indexes this process has built, by the [`fingerprint`] of their inputs.
static INDEXES: std::sync::OnceLock<
    std::sync::Mutex<std::collections::HashMap<String, Ownership>>,
> = std::sync::OnceLock::new();

/// Every file the index reads, as (path, length, modification time in
/// nanoseconds): each Warrant's top-level records, `atoms/` and
/// `amendments/`; the authority register, allowed signers, responses and
/// batches; the SAS revisions; `openwarrant.toml`. `None` when any of it
/// cannot be read — then nothing is cached and the index is built fresh.
fn fingerprint(repo: &Repository) -> Option<String> {
    fn add(out: &mut Vec<u8>, path: &std::path::Path) -> Option<()> {
        let meta = std::fs::metadata(path).ok()?;
        if meta.is_dir() {
            let mut entries: Vec<_> = std::fs::read_dir(path)
                .ok()?
                .filter_map(Result::ok)
                .map(|e| e.path())
                .filter(|p| p.is_file())
                .collect();
            entries.sort();
            for e in entries {
                add(out, &e)?;
            }
            return Some(());
        }
        let mtime = meta
            .modified()
            .ok()?
            .duration_since(std::time::UNIX_EPOCH)
            .ok()?
            .as_nanos();
        out.extend_from_slice(path.as_os_str().as_encoded_bytes());
        out.extend_from_slice(&meta.len().to_le_bytes());
        out.extend_from_slice(&mtime.to_le_bytes());
        out.push(0);
        Some(())
    }
    let root = repo.root.as_std_path();
    let mut out = Vec::new();
    add(&mut out, &root.join("openwarrant.toml"))?;
    // `docs/authority/standing` (OW-ADR-0029): a covered authorization is
    // believed only while its class file and the class's signed responses
    // are what they were, so the index is keyed by them too.
    for d in [
        "docs/authority",
        "docs/authority/responses",
        "docs/authority/batches",
        "docs/authority/standing",
    ] {
        let p = root.join(d);
        if p.is_dir() {
            add(&mut out, &p)?;
        }
    }
    let sas = repo.sas_revisions_dir();
    if sas.is_dir() {
        add(&mut out, sas.as_std_path())?;
    }
    let mut dirs = repo.warrant_dirs().ok()?;
    dirs.sort();
    for dir in dirs {
        let dir = dir.as_std_path();
        add(&mut out, dir)?;
        for sub in ["atoms", "amendments"] {
            let p = dir.join(sub);
            if p.is_dir() {
                add(&mut out, &p)?;
            }
        }
    }
    Some(openwarrant_compiler::sha256_hex(&out))
}

impl Ownership {
    /// Read every authorized Warrant with a recorded, attested set.
    ///
    /// Skipped, and therefore never owners: records with no `owned` set
    /// (legacy), records whose revision is not authorized, records whose
    /// authorize signature does not verify against the register, Warrants
    /// whose DERIVED currency is `superseded` (OW-ADR-0022: an authorized
    /// successor's `supersedes`, never a field), and Warrants whose resolution
    /// standing is annulled.
    ///
    /// Memoized for the process by [`fingerprint`]: `war compile` built this
    /// index once per pending act it judged — the whole corpus loaded dozens
    /// of times over. Any write to what the index reads moves the
    /// fingerprint, and the next call rebuilds.
    pub fn index(repo: &Repository) -> Result<Self, RepoError> {
        let key = fingerprint(repo);
        if let Some(key) = &key
            && let Some(hit) = INDEXES
                .get_or_init(Default::default)
                .lock()
                .ok()
                .and_then(|m| m.get(key).cloned())
        {
            return Ok(hit);
        }
        let corpus: Vec<crate::repo::Loaded> = repo
            .warrant_dirs()?
            .iter()
            .filter_map(|d| repo.load_warrant(d).ok())
            .collect();
        let built = Self::index_with(repo, &crate::relations::currencies(&corpus))?;
        if let Some(key) = key
            && let Ok(mut m) = INDEXES.get_or_init(Default::default).lock()
        {
            m.insert(key, built.clone());
        }
        Ok(built)
    }

    /// [`Self::index`] over a currency derivation the caller already holds,
    /// so `war check` derives it once for the corpus.
    pub fn index_with(
        repo: &Repository,
        currencies: &crate::relations::Currencies,
    ) -> Result<Self, RepoError> {
        let mut by_path: BTreeMap<String, Vec<Owner>> = BTreeMap::new();
        for dir in repo.warrant_dirs()? {
            let Some(alias) = dir.file_name().map(str::to_owned) else {
                continue;
            };
            let Some(record) = repo.load_authorization(&dir)? else {
                continue;
            };
            if record.owned.is_empty() {
                continue;
            }
            if record.revision.state != openwarrant_core::RevisionState::Authorized {
                continue;
            }
            let Some(auth) = &record.revision.authorization else {
                continue;
            };
            if !crate::authority_check::verify(
                repo,
                crate::authority_check::Act::Authorize,
                &alias,
                &auth.authorizer,
                Some(&record.revision.contract_digest),
            )
            .is_signed()
            {
                continue;
            }
            if matches!(
                currencies.of(&alias),
                crate::relations::Derived::Superseded { .. }
            ) {
                continue;
            }
            let resolution = repo.load_resolution(&dir)?;
            if resolution.as_ref().is_some_and(|r| {
                r.resolution.standing == openwarrant_core::ResolutionStanding::Annulled
            }) {
                continue;
            }
            let resolved = resolution.is_some();
            for d in &record.owned {
                by_path
                    .entry(d.target_ref.clone())
                    .or_default()
                    .push(Owner {
                        alias: alias.clone(),
                        deliverable_id: d.id.clone(),
                        authorized_at: auth.effective_time.clone(),
                        resolved,
                    });
            }
        }
        for owners in by_path.values_mut() {
            owners.sort_by(|a, b| {
                b.authorized_at
                    .cmp(&a.authorized_at)
                    .then_with(|| b.alias.cmp(&a.alias))
            });
        }
        Ok(Self { by_path })
    }

    /// The Warrant that governs `path` now, if any.
    #[must_use]
    pub fn current(&self, path: &str) -> Option<&Owner> {
        self.by_path.get(path).and_then(|v| v.first())
    }

    /// A governing Warrant other than `alias`, authorized later than `alias`
    /// was — the fact that makes `alias`'s pin on `path` historical. A Warrant
    /// with no recorded authorization time (legacy) is treated as authorized at
    /// the beginning of time, so any recorded owner is newer.
    #[must_use]
    pub fn newer_than(
        &self,
        path: &str,
        alias: &str,
        alias_authorized_at: Option<&str>,
    ) -> Option<&Owner> {
        let cur = self.current(path)?;
        if cur.alias == alias {
            return None;
        }
        match alias_authorized_at {
            Some(t) if cur.authorized_at.as_str() <= t => None,
            _ => Some(cur),
        }
    }

    /// OW-ADR-0029 with Q-003 (refuse, as recommended): the owner a Warrant
    /// covered by a standing authorization may NOT take `path` from — an
    /// authorized Warrant other than `alias` that has not resolved. Routine
    /// work never silently takes a file from work in flight; the in-flight
    /// Warrant resolves first, or the routine change is signed on its own.
    /// A resolved owner is not in flight: its pin becomes historical under
    /// OW-ADR-0021 exactly as for a signed Warrant.
    #[must_use]
    pub fn in_flight_owner(&self, path: &str, alias: &str) -> Option<&Owner> {
        self.current(path)
            .filter(|owner| owner.alias != alias && !owner.resolved)
    }

    /// Every owner of `path`, oldest first — the lineage `war pins --history`
    /// renders.
    #[must_use]
    pub fn lineage(&self, path: &str) -> Vec<&Owner> {
        let mut v: Vec<&Owner> = self
            .by_path
            .get(path)
            .map(|o| o.iter().collect())
            .unwrap_or_default();
        v.reverse();
        v
    }

    /// Paths governed by anyone, for tests and the hook.
    pub fn paths(&self) -> impl Iterator<Item = &str> {
        self.by_path.keys().map(String::as_str)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_set_digest_ignores_declaration_order() {
        let a = vec![
            OwnedDeliverable {
                id: "D-002".into(),
                target_ref: "b.rs".into(),
            },
            OwnedDeliverable {
                id: "D-001".into(),
                target_ref: "a.rs".into(),
            },
        ];
        let b = vec![a[1].clone(), a[0].clone()];
        assert_eq!(set_digest(&a), set_digest(&b));
        assert!(set_digest(&a).starts_with("sha256:"));
        assert_eq!(set_digest(&a).len(), 7 + 64);
    }

    #[test]
    fn the_set_digest_moves_when_a_path_is_added() {
        let mut a = vec![OwnedDeliverable {
            id: "D-001".into(),
            target_ref: "a.rs".into(),
        }];
        let before = set_digest(&a);
        a.push(OwnedDeliverable {
            id: "D-002".into(),
            target_ref: "b.rs".into(),
        });
        assert_ne!(before, set_digest(&a));
    }

    fn owner(alias: &str, at: &str) -> Owner {
        Owner {
            alias: alias.into(),
            deliverable_id: "D-001".into(),
            authorized_at: at.into(),
            resolved: false,
        }
    }

    #[test]
    fn the_latest_authorization_governs_and_the_earlier_pin_is_historical() {
        let mut o = Ownership::default();
        o.by_path.insert(
            "x.rs".into(),
            vec![
                owner("OW-WAR-0112", "2026-09-22T10:00:00Z"),
                owner("OW-WAR-0005", "2026-09-01T10:00:00Z"),
            ],
        );
        assert_eq!(o.current("x.rs").unwrap().alias, "OW-WAR-0112");
        assert_eq!(
            o.newer_than("x.rs", "OW-WAR-0005", Some("2026-09-01T10:00:00Z"))
                .unwrap()
                .alias,
            "OW-WAR-0112"
        );
        assert!(
            o.newer_than("x.rs", "OW-WAR-0112", Some("2026-09-22T10:00:00Z"))
                .is_none()
        );
        // A legacy Warrant with no recorded time is older than any owner.
        assert!(o.newer_than("x.rs", "OW-WAR-0001", None).is_some());
        assert_eq!(
            o.lineage("x.rs")
                .iter()
                .map(|w| w.alias.as_str())
                .collect::<Vec<_>>(),
            ["OW-WAR-0005", "OW-WAR-0112"]
        );
    }

    #[test]
    fn a_covered_warrant_may_not_take_a_path_from_work_in_flight() {
        let mut o = Ownership::default();
        o.by_path.insert(
            "x.rs".into(),
            vec![owner("OW-WAR-0200", "2026-09-22T10:00:00Z")],
        );
        assert_eq!(
            o.in_flight_owner("x.rs", "OW-WAR-0201")
                .map(|w| w.alias.as_str()),
            Some("OW-WAR-0200")
        );
        assert!(o.in_flight_owner("x.rs", "OW-WAR-0200").is_none());
        o.by_path.get_mut("x.rs").expect("path")[0].resolved = true;
        assert!(o.in_flight_owner("x.rs", "OW-WAR-0201").is_none());
    }

    #[test]
    fn an_ungoverned_path_has_no_owner() {
        let o = Ownership::default();
        assert!(o.current("nothing").is_none());
        assert!(o.newer_than("nothing", "OW-WAR-0001", None).is_none());
    }
}

// SPDX-License-Identifier: Apache-2.0
//! `war authorize` — the §28.4 authorization seam.
//!
//! # Two halves, and why this command cannot sign anything
//!
//! `war authorize <alias>` EMITS an authorization request. `war authorize
//! <alias> --response <file>` INGESTS what a human returned. Nothing in between
//! decides anything, for the same reason `war verify` is split: §27.2 says an
//! agent SHALL NOT authorize a proposed WAR, and a command that filled in an
//! authorizer would be doing exactly that with extra steps.
//!
//! The split is not merely a convention an agent is asked to respect. Ingestion
//! resolves the named authorizer against the repository's role register, and
//! [`RoleAssignment::may_authorize`] refuses every agent regardless of what the
//! response claims. An agent that wrote itself an authorization response would
//! have the record refused rather than written.
//!
//! # The digest is the point of requirement 1
//!
//! §56.1's first requirement is the *exact* authorized Contract Revision. So the
//! request carries the contract digest computed from the Warrant as it stands,
//! the response must echo that same digest back, and ingestion refuses a
//! mismatch. A signature returned against a digest that has since moved is a
//! signature on a document nobody is holding any more — which is the failure the
//! word "exact" is there to prevent.
//!
//! # What is written, and what is refused
//!
//! An admissible response writes `authorization.toml` (the authorized
//! [`ContractRevision`]) and, when judgments were returned, `judgments.toml`
//! (§42). A refused response writes NOTHING. A rejected authorization must not
//! become a file that later reads as authority, which is the same rule
//! `war verify` applies to refused verdicts.

use std::fs;

use camino::{Utf8Path, Utf8PathBuf};
use openwarrant_compiler::lower;
use openwarrant_core::authority::{ActorRole, AuthorityRegister, RoleAssignment};
use openwarrant_core::contract::{
    ActorKind, Authorization, ContractRevision, Independence, RevisionState,
};
use openwarrant_core::epistemic::Judgment;
use openwarrant_core::rationale::{Assumption, EpistemicStatus};
use serde::{Deserialize, Serialize};

use crate::diagnostic::{Diagnostic, Report};
use crate::repo::{RepoError, Repository};

pub const REQUEST_SCHEMA: &str = "oh.war/authorization-request/v1";
pub const RESPONSE_SCHEMA: &str = "oh.war/authorization-response/v1";
pub const AUTHORIZATION_SCHEMA: &str = "oh.war/authorization/v1";
pub const JUDGMENTS_SCHEMA: &str = "oh.war/judgments/v1";

/// OW-WAR-0137 — the per-Warrant review assignment. The file lives under
/// `openwarrant-core/src/` because it is pure; it is compiled here because
/// core's `lib.rs` is outside this Warrant's declared set.
#[path = "../../openwarrant-core/src/assignment.rs"]
pub mod assignment;

/// What is put to the authorizer.
///
/// Deliberately carries no recommendation and no "suggested meaning": §42 says
/// an approval with no stated meaning is invalid, and pre-filling the meaning
/// would make the authorizer a signatory to text an agent wrote.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct AuthorizationRequest {
    pub schema: String,
    pub warrant: String,
    pub title: String,
    pub assurance_level: String,
    /// The exact revision being put forward (§56.1 requirement 1).
    pub contract_digest: String,
    /// Which of §28.5's seventeen elements that digest actually covers
    /// (OW-ADR-0004). An authorizer is entitled to know they are signing a
    /// partial digest.
    pub contract_coverage: Vec<String>,
    /// §28.3 — who proposed it. Echoed so ingestion can detect
    /// self-authorization rather than trusting the response to admit it.
    pub proposer: String,
    pub obligations: Vec<RequestedObligation>,
    /// Assumptions carrying `accepted_residual_risk` (§36.2). Each needs a
    /// judgment from an actor with authority to accept it (§27.2).
    pub residual_risks: Vec<RequestedResidualRisk>,
    /// Actors the register says may authorize this. Informational — ingestion
    /// re-derives it rather than trusting the response to have used the list.
    pub eligible_authorizers: Vec<String>,
    /// OW-ADR-0021 — every deliverable the Warrant declares, as `(id, path)`.
    /// This is what the signature GRANTS: the paths this Warrant will govern.
    /// Absent from `contract_digest` on purpose (§28.5 coverage is frozen), so
    /// the set gets its own digest, echoed by the response and checked at
    /// ingest.
    #[serde(default)]
    pub deliverables: Vec<crate::ownership::OwnedDeliverable>,
    /// `ownership::set_digest` of `deliverables`.
    #[serde(default)]
    pub deliverable_set_digest: String,
    /// OW-WAR-0137 — who verifies and who resolves, when the Warrant names
    /// anyone. Signed like the deliverable set: listed here, its digest
    /// echoed by the response, a moved file refused at ingest. Absent on an
    /// unassigned Warrant, whose request is unchanged.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub assignment: Option<assignment::Assignment>,
    /// [`assignment::Assignment::digest`] of `assignment`; empty when none.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub assignment_digest: String,
    /// What ingest would refuse about the assignment, by rule, so the signer
    /// is not asked to sign something that will be refused.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub assignment_findings: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RequestedObligation {
    pub id: String,
    pub statement: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RequestedResidualRisk {
    pub assumption_id: String,
    pub statement: String,
    /// §36.2 — a residual risk with no stated consequence is not a risk anyone
    /// can weigh. `rationale.rs` already refuses to validate one.
    pub consequence_if_false: String,
    /// The judgment the assumption points at, empty when it points at none.
    pub judgment_ref: String,
}

/// What the authorizer returns.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct AuthorizationResponse {
    pub schema: String,
    pub warrant: String,
    /// Must equal the request's. See the module docs on requirement 1.
    pub contract_digest: String,
    pub authorizer: String,
    /// §27.4 — the role ACTUALLY exercised, not every role held.
    pub acting_role: String,
    /// §28.4 — what authorizing meant here.
    pub meaning: String,
    pub effective_time: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub policy_basis: Option<String>,
    pub independence: Independence,
    /// §42 judgments made at the same moment, including residual-risk
    /// acceptances. Optional: a Warrant may need none.
    #[serde(default)]
    pub judgment: Vec<Judgment>,
    /// How the signature was given: `tty` when confirmed on a terminal by
    /// `war sign`; absent for a hand-written response. Provenance, not
    /// authority — ingestion trusts the register, never this field.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub signed_via: Option<String>,
    /// OW-ADR-0021 — the set digest the signer saw. Must equal the manifest's
    /// set at ingest or the response is refused; absent on a hand-written
    /// response, in which case the set is recorded unsigned and said so.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub deliverable_set_digest: Option<String>,
    /// OW-WAR-0137 — the assignment digest the signer saw. Required when the
    /// Warrant has an `assignment.toml`: an assignment nobody signed is
    /// refused, never recorded unsigned.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub assignment_digest: Option<String>,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// The persisted authorization record.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct AuthorizationRecord {
    pub schema: String,
    pub warrant: String,
    pub revision: ContractRevision,
    /// §14 — the SAS revision the authorized contract was compiled against.
    /// Fixed here so that a LATER SAS revision does not move this Warrant's
    /// contract digest out from under its signature: an authorized contract
    /// keeps its Basis until an amendment re-authorizes it. Absent only on
    /// records written before this field existed; those read as the latest.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sas_revision: Option<String>,
    /// OW-ADR-0021 — the digest of `owned` as the authorizer signed it, or
    /// as ingest recorded it from the manifest when the response carried none.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub deliverable_set_digest: Option<String>,
    /// OW-ADR-0021 — the paths this authorization governs. Copied here at
    /// ingest because `deliverables.toml` can move afterwards and this record
    /// cannot: `authorization.toml` is an attestation subject. Empty on every
    /// record made before this field existed, and an empty set owns nothing.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub owned: Vec<crate::ownership::OwnedDeliverable>,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// The persisted judgment set.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct JudgmentRecord {
    pub schema: String,
    pub warrant: String,
    #[serde(default)]
    pub judgment: Vec<Judgment>,
}

/// Build the request for one Warrant.
pub fn request(repo: &Repository, alias: &str) -> Result<AuthorizationRequest, RepoError> {
    let dir = repo.warrant_dir(alias)?;
    let one = repo.load_warrant(&dir)?;
    let (Some(basis), Some(validated)) = (&one.basis, &one.validated) else {
        return Err(RepoError::Message(format!(
            "{alias}: the manifest did not validate, so there is no contract to authorize"
        )));
    };

    let ir = lower(basis, validated)
        .map_err(|e| RepoError::Message(format!("{alias}: could not compile contract: {e}")))?;
    let contract_digest = ir
        .contract_digest()
        .map_err(|e| RepoError::Message(format!("{alias}: could not digest contract: {e}")))?;

    let obligations = obligations_of(basis)
        .into_iter()
        .map(|o| RequestedObligation {
            id: o.id,
            statement: o.statement,
        })
        .collect();

    let register = repo.load_authority_register()?;
    let assumptions = repo.load_rationale(&dir)?.unwrap_or_default();
    let deliverables = crate::ownership::declared_set(repo, &dir)?;
    let deliverable_set_digest = crate::ownership::set_digest(&deliverables);
    let (assignment, assignment_findings) = match load_assignment(&dir) {
        None => (None, vec![]),
        Some(Err(why)) => (None, vec![format!("assignment.malformed: {why}")]),
        Some(Ok(a)) => {
            let findings = assignment::validate(&a, &register, &repo.performer())
                .iter()
                .map(ToString::to_string)
                .collect();
            (Some(a), findings)
        }
    };
    let assignment_digest = assignment
        .as_ref()
        .map(assignment::Assignment::digest)
        .unwrap_or_default();

    Ok(AuthorizationRequest {
        schema: REQUEST_SCHEMA.to_owned(),
        warrant: alias.to_owned(),
        title: validated.raw.title.clone(),
        assurance_level: validated.assurance_level.to_string(),
        contract_digest,
        contract_coverage: ir
            .contract_coverage
            .covered()
            .map(ToString::to_string)
            .collect(),
        proposer: repo.performer(),
        obligations,
        residual_risks: residual_risks_in(&assumptions),
        // Filtered by `may_authorize`, not by `holds`. Holding the authorizer
        // role is necessary and not sufficient — an agent holding it is still
        // refused by §27.2, as is a human who proposed this Warrant. Listing
        // either here would tell the reader to route the request to somebody
        // whose signature ingestion is guaranteed to reject.
        eligible_authorizers: register
            .holders(ActorRole::Authorizer)
            .filter(|a| a.may_authorize(&repo.performer()).is_ok())
            .map(|a| a.actor.clone())
            .collect(),
        deliverables,
        deliverable_set_digest,
        assignment,
        assignment_digest,
        assignment_findings,
    })
}

/// The Warrant's `assignment.toml`: `None` when absent, `Some(Err)` when it
/// exists and does not parse (or cannot be read — fail closed, never absent).
#[must_use]
pub fn load_assignment(dir: &camino::Utf8Path) -> Option<Result<assignment::Assignment, String>> {
    let path = dir.join(assignment::FILE);
    match fs::read_to_string(&path) {
        Ok(text) => Some(assignment::Assignment::parse(&text)),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
        Err(e) => Some(Err(format!("could not read {path}: {e}"))),
    }
}

/// The assignment digest the recorded authorization signed.
///
/// `None` when no authorization is recorded; `Some(None)` when one is and it
/// signed no assignment. `authorization.toml`'s schema is in the published
/// pack and this Warrant does not move it, so the digest is read from where
/// the act already put it:
///
/// 1. the authorization response under `docs/authority/responses/` at the
///    recorded contract digest — the bytes the human signed. When one exists,
///    its echo (or its lack of one) is the answer whatever the journal says:
///    deleting `assignment.toml` and the journal field together still meets
///    the signed echo, so a removal cannot widen who may act;
/// 2. otherwise the journal event that recorded the authorization at that
///    digest, the payload ingest wrote.
///
/// Whether that response's signature verifies is `authority_check`'s
/// question, asked wherever the authorization is relied on; editing the
/// response to change its echo breaks the signature and stops the Warrant.
pub fn recorded_assignment_digest(
    repo: &Repository,
    dir: &camino::Utf8Path,
) -> Result<Option<Option<String>>, RepoError> {
    let Some(record) = repo.load_authorization(dir)? else {
        return Ok(None);
    };
    if record.revision.authorization.is_none() {
        return Ok(None);
    }
    if let Some(echo) =
        signed_response_echo(repo, &record.warrant, &record.revision.contract_digest)
    {
        return Ok(Some(echo));
    }
    let journal = crate::journal_cmd::load(dir)?;
    let digest = journal
        .events
        .iter()
        .rev()
        .filter(|e| {
            e.event_type == crate::journal_cmd::AUTHORIZATION_RECORDED
                || e.event_type == crate::journal_cmd::AUTHORIZATION_SIGNATURE_RECORDED
        })
        .filter_map(|e| serde_json::from_str::<serde_json::Value>(&e.payload).ok())
        .find(|p| p["contract_digest"].as_str() == Some(record.revision.contract_digest.as_str()))
        .and_then(|p| p["assignment_digest"].as_str().map(str::to_owned));
    Ok(Some(digest))
}

/// The `assignment_digest` echoed by this Warrant's authorization response
/// over `contract`: `Some(Some(d))` when it echoes `d`, `Some(None)` when it
/// echoes none, `None` when no such response is on disk. Looks at the current
/// response and at the one `war sign` retires when a later revision is signed
/// (`<alias>.<digest[..8]>.response.toml`), and believes only a file whose
/// schema and contract digest are this act's.
fn signed_response_echo(repo: &Repository, alias: &str, contract: &str) -> Option<Option<String>> {
    let current =
        crate::authority_check::response_path(repo, crate::authority_check::Act::Authorize, alias);
    let retired = contract
        .get(..8)
        .map(|tag| current.with_file_name(format!("{alias}.{tag}.response.toml")));
    [Some(current), retired]
        .into_iter()
        .flatten()
        .filter_map(|path| fs::read_to_string(path).ok())
        .filter_map(|text| toml::from_str::<AuthorizationResponse>(&text).ok())
        .find(|r| {
            r.schema == RESPONSE_SCHEMA && r.warrant == alias && r.contract_digest == contract
        })
        .map(|r| r.assignment_digest)
}

/// Where this Warrant's assignment stands against its authorization. Every
/// act an assignment governs asks this, and an `Err` from
/// [`assignment::Standing::for_act`] means nobody may take the act.
pub fn assignment_standing(
    repo: &Repository,
    dir: &camino::Utf8Path,
) -> Result<assignment::Standing, RepoError> {
    let recorded = recorded_assignment_digest(repo, dir)?;
    Ok(assignment::standing(
        load_assignment(dir),
        recorded.as_ref().map(Option::as_deref),
    ))
}

/// Obligations declared across a Warrant's assurance atoms.
fn obligations_of(
    basis: &openwarrant_compiler::CompilationBasis,
) -> Vec<openwarrant_core::Obligation> {
    basis
        .atoms
        .iter()
        .filter(|a| a.role == "assurance")
        .filter_map(|a| {
            openwarrant_core::obligation::parse(&String::from_utf8_lossy(&a.bytes)).ok()
        })
        .flat_map(|set| set.obligations)
        .collect()
}

/// The assumptions carrying `accepted_residual_risk` (§36.2).
///
/// Takes the declared assumptions rather than reading them, so the caller
/// decides what an ABSENT `rationale.toml` means. That distinction is the whole
/// reason this is not a one-liner: a Warrant that declared no assumptions and a
/// Warrant that was never asked both produce an empty list here, and only the
/// caller knows which it is holding.
#[must_use]
pub fn residual_risks_in(assumptions: &[Assumption]) -> Vec<RequestedResidualRisk> {
    assumptions
        .iter()
        .filter(|a| a.epistemic_status == EpistemicStatus::AcceptedResidualRisk)
        .map(|a| RequestedResidualRisk {
            assumption_id: a.id.clone(),
            statement: a.statement.clone(),
            consequence_if_false: a.consequence_if_false.clone(),
            judgment_ref: a.judgment_ref.clone(),
        })
        .collect()
}

/// Why a response was refused before anything was written.
#[derive(Debug, PartialEq, Eq)]
pub enum Refusal {
    /// `effective_time` is not an RFC 3339 UTC timestamp.
    EffectiveTime {
        found: String,
        why: String,
    },
    UnknownSchema {
        found: String,
    },
    WrongWarrant {
        named: String,
        ingesting: String,
    },
    /// The signature is against a contract revision that is no longer the one
    /// on disk (§56.1 requirement 1).
    StaleDigest {
        signed: String,
        current: String,
    },
    /// The named authorizer holds no role assignment at all.
    UnknownActor {
        actor: String,
    },
    /// The register refused the act — agent, self-authorization, or a role the
    /// actor does not hold.
    NotPermitted {
        detail: String,
    },
    /// OW-ADR-0021 — the response signs a deliverable set the manifest no
    /// longer has.
    StaleDeliverables {
        signed: String,
        current: String,
    },
    /// OW-ADR-0021 — the response is dated before an existing owner of a path
    /// it declares.
    TimeBeforeOwner {
        path: String,
        owner: String,
        owner_time: String,
        this_time: String,
    },
}

impl std::fmt::Display for Refusal {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::UnknownSchema { found } => write!(
                f,
                "unknown response schema {found:?}; expected {RESPONSE_SCHEMA:?}"
            ),
            Self::WrongWarrant { named, ingesting } => write!(
                f,
                "response names {named:?} but is being ingested for {ingesting}"
            ),
            Self::EffectiveTime { found, why } => write!(
                f,
                "effective_time {found:?} is not an RFC 3339 UTC timestamp ({why}); a record \
                 dated \"soon\" cannot be ordered against any other"
            ),
            Self::StaleDigest { signed, current } => write!(
                f,
                "the response authorizes contract {signed} but the Warrant now compiles \
                 to {current}. §56.1 requires the EXACT authorized revision, so this \
                 signature covers a document that no longer exists. Re-issue the request \
                 and have it signed again"
            ),
            Self::UnknownActor { actor } => write!(
                f,
                "{actor:?} holds no role assignment in docs/authority/roles.toml, so \
                 there is no authority to exercise. Authority comes from a record a \
                 human wrote, never from a name supplied in the response itself"
            ),
            Self::NotPermitted { detail } => f.write_str(detail),
            Self::StaleDeliverables { signed, current } => write!(
                f,
                "the declared deliverable set moved after the request was drafted: the \
                 response signs set {signed} and the manifest is now {current}. What was \
                 drafted is what is signed (OW-ADR-0021) — re-draft and re-sign"
            ),
            Self::TimeBeforeOwner {
                path,
                owner,
                owner_time,
                this_time,
            } => write!(
                f,
                "effective_time {this_time} precedes {owner_time}, when {owner} was authorized \
                 for {path}. Ownership is ordered by authorization time (OW-ADR-0021), so an \
                 authorization dated before an existing owner would take the path away from it \
                 silently — set effective_time to now"
            ),
        }
    }
}

/// Check the signed deliverable set against the manifest, writing nothing.
///
/// `Ok(true)` when the response signed the set and it matches; `Ok(false)`
/// when the response carried no set (a hand-written or pre-ADR response), in
/// which case the caller records the current set and says it was unsigned.
pub fn validate_deliverables(
    response: &AuthorizationResponse,
    current_set_digest: &str,
) -> Result<bool, Refusal> {
    match response.deliverable_set_digest.as_deref() {
        None => Ok(false),
        Some(signed) if signed == current_set_digest => Ok(true),
        Some(signed) => Err(Refusal::StaleDeliverables {
            signed: signed.to_owned(),
            current: current_set_digest.to_owned(),
        }),
    }
}

/// Check the response envelope and the authorizer's standing, writing nothing.
///
/// Separated from [`ingest`] so every refusal is testable without a repository
/// on disk — including the two that matter most, an agent signing and a
/// signature against a stale digest.
pub fn validate_response(
    response: &AuthorizationResponse,
    ingesting: &str,
    current_digest: &str,
    proposer: &str,
    register: &AuthorityRegister,
) -> Result<(), Refusal> {
    if response.schema != RESPONSE_SCHEMA {
        return Err(Refusal::UnknownSchema {
            found: response.schema.clone(),
        });
    }
    if response.warrant != ingesting {
        return Err(Refusal::WrongWarrant {
            named: response.warrant.clone(),
            ingesting: ingesting.to_owned(),
        });
    }
    if let Err(e) = openwarrant_core::timestamp::validate_rfc3339_utc(&response.effective_time) {
        return Err(Refusal::EffectiveTime {
            found: response.effective_time.clone(),
            why: e.to_string(),
        });
    }
    if response.contract_digest != current_digest {
        return Err(Refusal::StaleDigest {
            signed: response.contract_digest.clone(),
            current: current_digest.to_owned(),
        });
    }
    let assignment = register
        .actor(&response.authorizer)
        .ok_or_else(|| Refusal::UnknownActor {
            actor: response.authorizer.clone(),
        })?;
    assignment
        .may_authorize(proposer)
        .map_err(|e| Refusal::NotPermitted {
            detail: e.to_string(),
        })?;
    Ok(())
}

/// Whether a judgment's actor may make it (§42, §27.2).
///
/// A residual-risk acceptance needs `risk_acceptor`; anything else needs
/// `judge`. Both are refused to agents by [`RoleAssignment`], so a judgment an
/// agent "made" cannot be recorded here even if the response asserts it.
fn judgment_is_permitted(judgment: &Judgment, register: &AuthorityRegister) -> Result<(), String> {
    judgment.validate().map_err(|e| e.to_string())?;
    let assignment: &RoleAssignment = register.actor(&judgment.actor).ok_or_else(|| {
        format!(
            "{:?} holds no role assignment, so it cannot make a judgment (§42)",
            judgment.actor
        )
    })?;
    // Agent-hood is checked BEFORE the role, and the order is deliberate. It is
    // the stronger statement: granting an agent the judge role would not make it
    // eligible, so reporting "does not hold the judge role" first would suggest
    // a fix that does not work.
    //
    // §27.1 lets an agent RECOMMEND a judgment. Recording one as MADE is a
    // different act, and that distinction is the whole of §42.
    if assignment.actor_kind == ActorKind::Agent {
        return Err(format!(
            "{:?} is an agent. §27.1 permits recommending a judgment, not making one — \
             record it as a recommendation. Granting the judge role would not change \
             this",
            judgment.actor
        ));
    }
    if judgment.kind == "residual_risk_acceptance" {
        assignment
            .may_accept_residual_risk()
            .map_err(|e| e.to_string())
    } else if assignment.holds(ActorRole::Judge) {
        Ok(())
    } else {
        Err(format!(
            "{:?} does not hold the judge role (§27.4)",
            judgment.actor
        ))
    }
}

/// Ingest a signed authorization response, writing records only if it is
/// admissible.
///
/// Whether this response supplies a signature a prior record lacked is decided
/// HERE rather than by the caller, and the response being ingested is excluded
/// from that question. `war sign` writes and signs the response before calling
/// this, so a naive "is this record signed?" sees the signature it is about to
/// ingest and answers yes — which refused 57 re-signatures in one run of
/// `war sign --all --ssh-sign` on 2026-09-19. Excluding the one file under
/// consideration makes both callers (this command and `war sign`) correct
/// without either having to know about the other.
pub fn ingest(
    repo: &Repository,
    alias: &str,
    response_path: &Utf8PathBuf,
) -> Result<Report, RepoError> {
    ingest_with(repo, alias, response_path, crate::sign::IngestMode::Record)
}

/// [`ingest`], or the same judgment with the write withheld.
///
/// Every refusal above the record write runs in both modes, so a
/// `DryRun` report names exactly what the real ingest would refuse. The one
/// difference is at the write: `DryRun` reports `authorize.would-record` and
/// returns; nothing under the Warrant directory is touched and no journal
/// line is appended.
pub fn ingest_with(
    repo: &Repository,
    alias: &str,
    response_path: &Utf8PathBuf,
    mode: crate::sign::IngestMode,
) -> Result<Report, RepoError> {
    let dir = repo.warrant_dir(alias)?;
    // OW-WAR-0121: what the two records this act may write ARE, read before
    // anything else is. The writes at the end refuse if either moved in the
    // meantime — the span includes an ssh-agent dialog — and a symlink in a
    // record's place is refused here, before its target is read as a record.
    let authorization_path = dir.join("authorization.toml");
    let judgments_path = dir.join("judgments.toml");
    let prestates = crate::compile::atomic::prestate(&authorization_path)
        .and_then(|a| crate::compile::atomic::prestate(&judgments_path).map(|j| (a, j)));
    let (authorization_before, judgments_before) = match prestates {
        Ok(p) => p,
        Err(refused) => {
            let mut report = Report::default();
            report.push(refused.diagnostic());
            return Ok(report);
        }
    };
    let one = repo.load_warrant(&dir)?;
    let mut report = Report::default();

    let (Some(basis), Some(validated)) = (&one.basis, &one.validated) else {
        report.push(Diagnostic::error(
            "authorize.not-compilable",
            dir.to_string(),
            format!("{alias}: the manifest did not validate, so there is no contract to authorize"),
        ));
        return Ok(report);
    };
    let ir = lower(basis, validated)
        .map_err(|e| RepoError::Message(format!("{alias}: could not compile contract: {e}")))?;
    let current_digest = ir
        .contract_digest()
        .map_err(|e| RepoError::Message(format!("{alias}: could not digest contract: {e}")))?;

    let text = fs::read_to_string(response_path).map_err(|source| RepoError::Io {
        context: format!("could not read {response_path}"),
        source,
    })?;
    let response: AuthorizationResponse = match toml::from_str(&text) {
        Ok(r) => r,
        Err(e) => {
            report.push(Diagnostic::error(
                "authorize.response-malformed",
                response_path.to_string(),
                e.to_string(),
            ));
            return Ok(report);
        }
    };

    let register = repo.load_authority_register()?;
    let proposer = repo.performer();

    if let Err(refusal) = validate_response(&response, alias, &current_digest, &proposer, &register)
    {
        let rule = match refusal {
            Refusal::UnknownSchema { .. } => "authorize.response-schema",
            Refusal::WrongWarrant { .. } => "authorize.response-warrant",
            Refusal::StaleDigest { .. } => "authorize.stale-digest",
            Refusal::EffectiveTime { .. } => "authorize.effective-time",
            Refusal::UnknownActor { .. } => "authorize.unknown-actor",
            Refusal::NotPermitted { .. } => "authorize.not-permitted",
            Refusal::StaleDeliverables { .. } => "authorize.stale-deliverables",
            Refusal::TimeBeforeOwner { .. } => "authorize.time-before-owner",
        };
        report.push(Diagnostic::error(
            rule,
            response_path.to_string(),
            refusal.to_string(),
        ));
        return Ok(report);
    }

    // OW-ADR-0021: what the signer saw is what is recorded. The set is read
    // from the manifest NOW and compared to what the response signed; a moved
    // set is refused before anything else is considered.
    let owned = crate::ownership::declared_set(repo, &dir)?;
    let current_set_digest = crate::ownership::set_digest(&owned);
    let set_signed = match validate_deliverables(&response, &current_set_digest) {
        Ok(signed) => signed,
        Err(refusal) => {
            report.push(Diagnostic::error(
                "authorize.stale-deliverables",
                response_path.to_string(),
                refusal.to_string(),
            ));
            return Ok(report);
        }
    };
    // OW-WAR-0137: the assignment is what the signer saw, and it names only
    // actors the register already permits. Checked before any signature is
    // looked at and before anything is written; every refusal names its rule.
    if let Some(refusal) = assignment_refusal(&response, &dir, &register, &proposer) {
        report.push(Diagnostic::error(
            refusal.rule,
            response_path.to_string(),
            refusal.message,
        ));
        return Ok(report);
    }
    let assignment_digest = load_assignment(&dir)
        .and_then(Result::ok)
        .map(|a| a.digest());
    if !set_signed && !owned.is_empty() {
        report.push(Diagnostic::warn(
            "authorize.deliverables-unsigned",
            response_path.to_string(),
            format!(
                "{alias}: the response carries no deliverable_set_digest, so the {} declared \
                 path(s) are recorded from the manifest at ingest and the signature does not \
                 cover them. A response drafted by `war sign` signs the set",
                owned.len()
            ),
        ));
    }
    // Ownership is ordered by effective time; a signature dated before an
    // existing owner of one of these paths would silently take it away.
    if !owned.is_empty() {
        let ownership = crate::ownership::Ownership::index(repo)?;
        for d in &owned {
            if let Some(cur) = ownership.current(&d.target_ref)
                && cur.alias != alias
                && response.effective_time.as_str() < cur.authorized_at.as_str()
            {
                let refusal = Refusal::TimeBeforeOwner {
                    path: d.target_ref.clone(),
                    owner: cur.alias.clone(),
                    owner_time: cur.authorized_at.clone(),
                    this_time: response.effective_time.clone(),
                };
                report.push(Diagnostic::error(
                    "authorize.time-before-owner",
                    response_path.to_string(),
                    refusal.to_string(),
                ));
                return Ok(report);
            }
        }
    }

    // Every judgment is checked BEFORE anything is written. A response that
    // authorizes correctly but carries one inadmissible judgment must not leave
    // a valid authorization next to a silently dropped judgment — that would
    // read, later, as a Warrant whose judgments were simply never needed.
    let mut judgment_failures = Vec::new();
    for j in &response.judgment {
        if let Err(detail) = judgment_is_permitted(j, &register) {
            judgment_failures.push(format!("{}: {detail}", j.id));
        }
    }
    if !judgment_failures.is_empty() {
        for detail in judgment_failures {
            report.push(Diagnostic::error(
                "authorize.judgment-not-permitted",
                response_path.to_string(),
                detail,
            ));
        }
        return Ok(report);
    }

    // OW-WAR-0130 (§67.4), before the first write: the same signed act,
    // already recorded for the contract as it stands by the same person, is
    // an equivalent retry. It replays — nothing is written, the act exits 0 —
    // where it used to meet `authorize.already-authorized` or, for a record
    // that was file-only, rewrite it. The same key journalled by another
    // actor is a conflicting reuse and is refused with nothing written.
    let actor = format!("person://{}", response.authorizer);
    let payload = format!(
        "{{\"contract_digest\":\"{}\",\"acting_role\":\"{}\",\"channel\":\"{}\",\"deliverable_set_digest\":\"{}\",\"set_signed\":{}{}}}",
        response.contract_digest,
        response.acting_role,
        response.signed_via.as_deref().unwrap_or("file"),
        current_set_digest,
        set_signed,
        // OW-WAR-0137: present only on an assigned Warrant, so every other
        // payload — and every replay key already journalled — is unchanged.
        assignment_digest
            .as_deref()
            .map(|d| format!(",\"assignment_digest\":\"{d}\""))
            .unwrap_or_default()
    );
    let on_file = repo.load_authorization(&dir)?.is_some_and(|prev| {
        prev.revision.contract_digest == current_digest
            && prev
                .revision
                .authorization
                .as_ref()
                .is_some_and(|a| a.authorizer == response.authorizer)
    });
    if on_file {
        for event_type in [
            crate::journal_cmd::AUTHORIZATION_RECORDED,
            crate::journal_cmd::AUTHORIZATION_SIGNATURE_RECORDED,
        ] {
            match crate::journal_cmd::already_recorded(&dir, event_type, &payload, &actor)? {
                crate::journal_cmd::Prior::Fresh => {}
                crate::journal_cmd::Prior::Conflict { recorded_by } => {
                    report.push(crate::journal_cmd::conflict(
                        repo.relative(&dir.join(crate::journal_cmd::FILE)),
                        event_type,
                        &recorded_by,
                        &actor,
                    ));
                    return Ok(report);
                }
                crate::journal_cmd::Prior::Equivalent { occurred_at } => {
                    report.push(Diagnostic::pass(
                        "authorize.replayed",
                        format!(
                            "{alias}: contract {current_digest} is already authorized by {} \
                             acting as {}, journalled at {occurred_at} → {}; an equivalent \
                             retry replays and writes nothing",
                            response.authorizer,
                            response.acting_role,
                            repo.relative(&authorization_path)
                        ),
                    ));
                    return Ok(report);
                }
            }
        }
    }

    let authorization = Authorization {
        authorizer: response.authorizer.clone(),
        // Unreachable after `validate_response`, which refuses `UnknownActor`
        // before this point. Kept rather than unwrapped so a future edit that
        // reorders the guard degrades to the most restricted kind instead of
        // panicking — `Human` is the fallback because an agent reaching here
        // would already have been refused for being one.
        actor_kind: register
            .actor(&response.authorizer)
            .map_or(ActorKind::Human, |a| a.actor_kind),
        acting_role: response.acting_role.clone(),
        meaning: response.meaning.clone(),
        effective_time: response.effective_time.clone(),
        policy_basis: response.policy_basis.clone(),
        independence: response.independence,
    };

    // A first authorization is revision 1. A later one, at a moved digest, is
    // §28's amendment: revision N+1 whose predecessor is the authorized digest
    // — and §31 says every revision after authorization SHALL carry an
    // amendment record, so one must exist under `amendments/` before the
    // signature is accepted. Re-signing the SAME digest is refused: an
    // authorized revision is immutable (§28.3), and there is nothing to add.
    let existing = repo.load_authorization(&dir)?;
    // OW-WAR-0137: an assignment that moved since the recorded authorization
    // changes who reviews, which is §31 material like a moved deliverable set:
    // it falls through to the amendment branch rather than reading as
    // "already authorized".
    let assignment_moved = recorded_assignment_digest(repo, &dir)?
        .is_some_and(|recorded| recorded != assignment_digest);
    // An existing record at this digest with no verified signature is not an
    // authorized revision — it is an unsigned draft that happens to sit in the
    // authorization's place. Accepting a signature for it adds the one thing it
    // lacks and changes nothing else, so §28.3's immutability has nothing to
    // protect here. This is how 57 file-only records became signable without a
    // corpus-wide exception, and it is narrow on purpose: same digest, same
    // revision number, and only while the record is unsigned.
    let unsigned_at_this_digest = existing.as_ref().is_some_and(|prev| {
        prev.revision.contract_digest == current_digest
            && prev.revision.authorization.as_ref().is_none_or(|auth| {
                !crate::authority_check::verify_excluding(
                    repo,
                    crate::authority_check::Act::Authorize,
                    alias,
                    &auth.authorizer,
                    Some(&prev.revision.contract_digest),
                    Some(response_path.as_path()),
                )
                .is_signed()
            })
    });
    let revision = match existing {
        Some(prev)
            if prev.revision.contract_digest == current_digest && unsigned_at_this_digest =>
        {
            report.push(Diagnostic::warn(
                "authorize.signature-supplied",
                response_path.to_string(),
                format!(
                    "{alias}: revision {} was recorded without a verified signature; this \
                     signature supplies it. The revision number does not move, because the \
                     contract did not",
                    prev.revision.revision
                ),
            ));
            // Same contract, same revision number, now carrying a signature.
            // Built through the state machine so the record's shape is the one
            // every reader expects, then numbered back to the revision it is.
            let mut signed =
                ContractRevision::draft(current_digest.clone(), ir.contract_coverage.clone())
                    .propose(proposer)
                    .and_then(|proposed| proposed.authorize(authorization))
                    .map_err(|e| RepoError::Message(format!("{alias}: {e}")))?;
            signed.revision = prev.revision.revision;
            signed
        }
        // Same contract digest AND same (or never-recorded) set: nothing to
        // add. A moved set at the same contract digest is §31 material — it
        // widens what the Warrant governs — and falls through to the amendment
        // branch below, which demands AM-nnn and produces revision N+1.
        Some(prev)
            if prev.revision.contract_digest == current_digest
                && prev
                    .deliverable_set_digest
                    .as_deref()
                    .is_none_or(|d| d == current_set_digest)
                && !assignment_moved =>
        {
            report.push(Diagnostic::error(
                "authorize.already-authorized",
                response_path.to_string(),
                format!(
                    "{alias}: revision {} is already authorized at this digest; an authorized \
                     revision is immutable (§28.3)",
                    prev.revision.revision
                ),
            ));
            return Ok(report);
        }
        Some(prev) => {
            // Revision N+1 needs N amendment records: one per revision after
            // the first. Counting, rather than "any file exists", is what stops
            // the record written for revision 2 from carrying revision 3 through
            // (found by review). The count is of `.yaml` files under amendments/;
            // each is separately validated by `war check` as a §31 record.
            let amendments = dir
                .join("amendments")
                .read_dir_utf8()
                .map(|it| {
                    it.flatten()
                        .filter(|e| e.path().as_str().ends_with(".yaml"))
                        .count()
                })
                .unwrap_or(0);
            let needed = prev.revision.revision as usize;
            if amendments < needed {
                report.push(Diagnostic::error(
                    "authorize.no-amendment",
                    response_path.to_string(),
                    format!(
                        "{alias}: the contract moved from {} to {} after revision {} was authorized. \
                         §31: every revision after authorization carries an amendment record — \
                         revision {} needs {needed} under amendments/ and {amendments} exist. \
                         Write AM-{:03} (`war amend {alias}` mints its file, AM-<n>-<hash>) before re-signing",
                        prev.revision.contract_digest,
                        current_digest,
                        prev.revision.revision,
                        prev.revision.revision + 1,
                        needed
                    ),
                ));
                return Ok(report);
            }
            prev.revision
                .amend(current_digest.clone(), ir.contract_coverage.clone())
                .and_then(|draft| draft.propose(proposer))
                .and_then(|proposed| proposed.authorize(authorization))
                .map_err(|e| RepoError::Message(format!("{alias}: {e}")))?
        }
        None => ContractRevision::draft(current_digest.clone(), ir.contract_coverage.clone())
            .propose(proposer)
            .and_then(|proposed| proposed.authorize(authorization))
            .map_err(|e| RepoError::Message(format!("{alias}: {e}")))?,
    };

    let record = AuthorizationRecord {
        schema: AUTHORIZATION_SCHEMA.to_owned(),
        warrant: alias.to_owned(),
        revision,
        sas_revision: basis.sas.as_ref().map(|p| p.version.clone()),
        deliverable_set_digest: Some(current_set_digest.clone()),
        owned,
    };
    if mode == crate::sign::IngestMode::DryRun {
        report.push(Diagnostic::pass(
            "authorize.would-record",
            format!(
                "{alias}: revision {} at contract {current_digest} would be recorded, granting \
                 {} path(s) under set {current_set_digest}. Not written",
                record.revision.revision,
                record.owned.len()
            ),
        ));
        return Ok(report);
    }
    // OW-WAR-0144: a revision after authorization replaces this file, and
    // every attestation over the revision it replaces names these bytes.
    // Keep them beside it, as a retired response is kept (§34.4: supersede,
    // never erase), where `attest --verify` finds them by digest.
    if let Some(refused) = retain_superseded(&authorization_path) {
        report.push(refused);
        return Ok(report);
    }
    if let Err(refused) = write_toml(&authorization_path, &record, &authorization_before)? {
        report.push(refused.diagnostic());
        return Ok(report);
    }
    if let Some(v) = &one.validated {
        crate::journal_cmd::record(
            &dir,
            &v.uuid.to_string(),
            if unsigned_at_this_digest {
                crate::journal_cmd::AUTHORIZATION_SIGNATURE_RECORDED
            } else {
                crate::journal_cmd::AUTHORIZATION_RECORDED
            },
            &actor,
            &payload,
        )?;
    }
    report.push(Diagnostic::pass(
        "authorize.recorded",
        format!(
            "{alias}: contract {current_digest} authorized by {} acting as {} → {}",
            response.authorizer,
            response.acting_role,
            dir.join("authorization.toml")
        ),
    ));

    if !response.judgment.is_empty() {
        let judgments = JudgmentRecord {
            schema: JUDGMENTS_SCHEMA.to_owned(),
            warrant: alias.to_owned(),
            judgment: response.judgment.clone(),
        };
        if let Err(refused) = write_toml(&judgments_path, &judgments, &judgments_before)? {
            report.push(refused.diagnostic());
            return Ok(report);
        }
        report.push(Diagnostic::pass(
            "authorize.judgments-recorded",
            format!(
                "{alias}: {} judgment(s) recorded → {}",
                response.judgment.len(),
                dir.join("judgments.toml")
            ),
        ));
    }

    Ok(report)
}

/// OW-WAR-0137 — the assignment check at authorization ingest, writing
/// nothing. `None` when the response may proceed.
fn assignment_refusal(
    response: &AuthorizationResponse,
    dir: &camino::Utf8Path,
    register: &AuthorityRegister,
    performer: &str,
) -> Option<assignment::Finding> {
    let current = match load_assignment(dir) {
        None => None,
        Some(Err(why)) => {
            return Some(assignment::Finding {
                rule: "assignment.malformed",
                message: format!("{}: {why}", assignment::FILE),
            });
        }
        Some(Ok(a)) => Some(a),
    };
    let current_digest = current.as_ref().map(assignment::Assignment::digest);
    match (
        response.assignment_digest.as_deref(),
        current_digest.as_deref(),
    ) {
        (None, None) => return None,
        (Some(signed), Some(now)) if signed == now => {}
        (None, Some(now)) => {
            return Some(assignment::Finding {
                rule: "authorize.assignment-unsigned",
                message: format!(
                    "the Warrant assigns who reviews it ({now}) and the response echoes no \
                     assignment_digest. An assignment takes effect only as the authorizer \
                     signed it — draft the response with `war sign`, which echoes it"
                ),
            });
        }
        (Some(signed), now) => {
            return Some(assignment::Finding {
                rule: "authorize.stale-assignment",
                message: format!(
                    "the response signs assignment {signed} and {} is now {}. What was \
                     drafted is what is signed — re-draft and re-sign",
                    assignment::FILE,
                    now.unwrap_or("absent")
                ),
            });
        }
    }
    let a = current?;
    assignment::validate(&a, register, performer)
        .into_iter()
        .next()
}

/// Render and write one record through the §86 path, against the prestate
/// read when the act began. The outer error is a record that would not
/// render; the inner one is a write the storage layer refused by name, which
/// the caller reports as a diagnostic rather than an I/O failure.
fn write_toml<T: Serialize>(
    path: &camino::Utf8Path,
    value: &T,
    before: &crate::compile::atomic::Prestate,
) -> Result<Result<(), crate::compile::atomic::Refused>, RepoError> {
    let rendered = toml::to_string_pretty(value).map_err(|e| RepoError::Message(e.to_string()))?;
    Ok(crate::compile::atomic::write_if(path, rendered, before))
}

/// Whether a persisted authorization covers the contract as it stands now.
///
/// §56.1 requirement 1 in one function. Both halves matter: an authorization in
/// any state other than `Authorized` is a proposal, and one whose digest has
/// moved covers a revision that no longer exists.
#[must_use]
pub fn authorizes_current_contract(record: &AuthorizationRecord, current_digest: &str) -> bool {
    record.revision.state == RevisionState::Authorized
        && record.revision.contract_digest == current_digest
        && record.revision.authorization.is_some()
}

/// Copy an existing `authorization.toml` to `authorization.<digest8>.toml`
/// beside it before it is replaced. An identical copy already there is left
/// alone; a different file under that name refuses the act before anything
/// is written (`authorize.retire-collision`), never overwritten.
fn retain_superseded(path: &Utf8Path) -> Option<Diagnostic> {
    let Ok(bytes) = fs::read(path) else {
        return None; // nothing authorized yet: nothing to keep
    };
    let digest = openwarrant_compiler::sha256_hex(&bytes);
    let kept = path.with_file_name(format!("authorization.{}.toml", &digest[..8]));
    match fs::read(&kept) {
        Ok(existing) if existing == bytes => None,
        Ok(_) => Some(Diagnostic::error(
            "authorize.retire-collision",
            kept.to_string(),
            format!(
                "{kept} exists with other bytes than the authorization it would keep \
                 (sha256:{digest}); nothing is overwritten and nothing is recorded"
            ),
        )),
        Err(_) => crate::compile::atomic::write(&kept, &bytes)
            .err()
            .map(|refused| refused.diagnostic()),
    }
}

