            owned: vec![],
            schema: AUTHORIZATION_SCHEMA.to_owned(),
            warrant: "OW-WAR-0014".to_owned(),
            revision: ContractRevision::draft(

// SPDX-License-Identifier: Apache-2.0
//! `war sign` — the human's half of every seam, as one command at a terminal.
//!
//! # Why this exists
//!
//! Every authority act in this repository is a two-half seam: an agent emits a
//! request, a human ingests a signed response. That shape is right (§27.2) and
//! it was, in practice, three steps: emit the request to a file, hand-write a
//! response with six fields and one `[[judgment]]` block per residual risk,
//! then ingest it. Nobody hand-writes fifty-seven of those. What happened
//! instead is that an agent drafted every response and the human said "sign
//! it" — which is a signature in name only, and the friction of the three
//! steps was the only thing stopping the agent from running the third too.
//!
//! `war sign` collapses the human's part to one screen and one keystroke,
//! and replaces friction with a control that is actually a control:
//!
//! - **It refuses without a terminal.** An agent's shell has no TTY, so the
//!   command cannot be run from inside one. This is a speed bump against an
//!   agent completing the loop by accident or by "helpfulness", not a
//!   cryptographic guarantee; a pseudo-terminal defeats it.
//! - **`--ssh-sign` is the stronger form, and the one that works from inside
//!   an agent session.** Measured: Claude Code's `!` prefix runs in the agent's
//!   own shell and has no TTY, so the terminal path refuses it — correctly, and
//!   uselessly for a human sitting in that session. `--ssh-sign` signs the
//!   response file's bytes with `ssh-keygen -Y sign` under namespace
//!   `oh.war/response`, verifies at once against a human-written
//!   `docs/authority/allowed_signers`, and refuses if it does not verify. No
//!   prompt, no TTY: the human act is the ssh agent's confirmation dialog,
//!   which exists only if the key was loaded with `ssh-add -c`. Without `-c`
//!   the AI agent's shell can reach the same socket and sign as the human, and
//!   `war` cannot tell the two apart. That is the one thing the operator must
//!   get right, and the docs say so where the key is configured. A security
//!   key (`sk-`) is the exception (OW-WAR-0138): its signature carries the
//!   authenticator's presence flag, `war` reads it after verification and
//!   records it, and `[policy] require_user_presence` refuses any signature
//!   that does not show it. `docs/AUTHENTICATION.md` is the contract.
//! - **It shows what is being signed, not the TOML.** Title, revision, what
//!   changed (for an amendment), obligations, every residual risk with its
//!   consequence, the digest. Those are the things the signer is accepting.
//!   Everything else in a response is boilerplate.
//! - **The drafted wording is a template, and says so.** `authorize.rs` is
//!   right that pre-filling the meaning would make the signer a signatory to
//!   text an agent wrote. This is the other case: text a deterministic tool
//!   rendered from the record's own facts, shown to the signer on a terminal
//!   before they confirm, and recorded as `signed_via = "tty"`. That is more
//!   honest than the paragraph-per-response practice it replaces.
//! - **It reuses every existing refusal.** On `y` it writes the response to
//!   `docs/authority/responses/` and calls the same ingest that a hand-written
//!   response goes through. Agent-by-kind, stale digest, self-authorization,
//!   missing amendment, unsupported outcome: nothing here bypasses them.
//!
//! There is deliberately no `--yes`. A flag that skipped the prompt would be
//! the first thing an agent reached for.
//!
//! # What this could not touch, and why
//!
//! `signed_via = "tty"` is a field on the authorization response only.
//! `resolution_cmd.rs`, `sas.rs` and `conformance/plant.sh` are pinned
//! deliverables of resolved Warrants (0059, 0058, 0063); editing them raises
//! `deliverable.digest-drift`, and the act that would let them move for a
//! reason is OW-WAR-0064, not yet authorized. So a resolution or SAS
//! acceptance signed here carries its provenance in the `meaning` text, and
//! the no-terminal refusal is proved by a unit test rather than a §92 plant.
//! Both move into their proper places when 0064 lands.

use std::io::{IsTerminal, Write};

use camino::{Utf8Path, Utf8PathBuf};
use openwarrant_core::{
    Independence, JudgmentAuthority, correction::Correction, epistemic::Judgment,
    resolution::CommonOutcome, sas::SasRevisionState,
};

use crate::{
    authorize::{self, AuthorizationRequest, AuthorizationResponse},
    diagnostic::{Diagnostic, Report},
    repo::{RepoError, Repository},
    resolution_cmd::{self, ResolutionRequest, ResolutionResponse},
    sas::{self, AcceptRequest, AcceptResponse},
};

/// How the signature reached the record. Written into the response and the
/// journal so a later reader can tell a terminal confirmation from a
/// hand-written file — or, later, from an ssh signature.
pub const CHANNEL_TTY: &str = "tty";
/// Signed with `ssh-keygen -Y sign`; the `.sig` sidecar beside the response
/// verifies against `docs/authority/allowed_signers`.
pub const CHANNEL_SSH: &str = "ssh";
/// The `-n` namespace every signature is made and verified under. A signature
/// made for another purpose with the same key does not verify here.
pub const SSH_NAMESPACE: &str = "oh.war/response";

/// One act awaiting a human.
#[derive(Debug)]
pub enum Pending {
    Authorize {
        alias: String,
        request: AuthorizationRequest,
        /// Present when this would be revision N+1 under an amendment.
        amendment: Option<AmendmentSummary>,
        revision: u32,
    },
    Resolve {
        alias: String,
        request: ResolutionRequest,
        profile: String,
        /// Present when a resolution is already recorded for this contract and
        /// carries no verified signature. The act is then not a decision to
        /// resolve — that decision is history — but the signature that decision
        /// was recorded without, so the outcome comes from the record rather
        /// than from §38.6 or a flag.
        recorded: Option<RecordedOutcome>,
        /// OW-WAR-0137 — `None` when no assignment narrows this act. `Ok`
        /// carries the narrowing already applied to `request.eligible_resolvers`;
        /// `Err` names why nobody may resolve (the list is then empty).
        assignment: Option<Result<authorize::assignment::Narrowed, authorize::assignment::Finding>>,
    },
    Accept {
        version: String,
        request: AcceptRequest,
    },
    /// OW-ADR-0023 — a proposed roadmap revision awaits one signature.
    AcceptRoadmap {
        revision: u32,
        request: crate::roadmap_cmd::AcceptRequest,
    },
    /// OW-ADR-0029 — a proposed class of routine work awaits the one
    /// signature that makes it a standing authorization.
    AcceptStanding {
        request: crate::standing_cmd::AcceptRequest,
    },
    /// OW-ADR-0029 — a signed class, offered for revocation only under
    /// `--revoke`; never part of a sweep.
    RevokeStanding {
        request: crate::standing_cmd::RevokeRequest,
    },
    /// OW-WAR-0064 — a resolved Warrant's delivered artifact has moved and a
    /// human must say why, or restore it.
    Correct {
        alias: String,
        deliverable_id: String,
        request: crate::correct::CorrectionRequest,
        /// Present when the correction is already recorded and carries no
        /// verified signature: the act then repeats the record, so the reason
        /// and the kind come from it and `--kind` is not asked for again.
        recorded: Option<RecordedCorrection>,
    },
    /// OW-WAR-0136 Q-001 (a) — a Gate Definition version invalidated. Never
    /// found by [`pending`]: nothing in the records asks for it. It exists when
    /// a human names the gate and the grounds (`war sign <gate>@<version>
    /// --grounds …`).
    Invalidate {
        gate: String,
        request: crate::invalidation::InvalidationRequest,
    },
}

/// The outcome an existing resolution recorded, so a signature supplied for it
/// says what the record says and not something new.
#[derive(Debug, Clone)]
pub struct RecordedOutcome {
    pub common: CommonOutcome,
    pub profile: String,
}

/// The correction a record already holds, so a signature supplied for it says
/// exactly what was recorded.
#[derive(Debug, Clone)]
pub struct RecordedCorrection {
    pub superseded_digest: String,
    pub new_digest: String,
    pub reason: String,
    pub kind: openwarrant_core::correction::CorrectionKind,
}

/// What an amendment says it changed, read for display only. Validation of the
/// amendment itself belongs to `authorize::ingest`, which counts and checks
/// the records; this reads the human-facing lines so the signer sees them.
#[derive(Debug, Clone, Default)]
pub struct AmendmentSummary {
    pub id: String,
    pub reason: String,
    pub changes: Vec<(String, String, String)>,
}

/// Whether an ingest records or only judges.
///
/// `DryRun` runs every refusal an ingest would run — schema, digest, register,
/// role, amendment count, deliverable set, judgment admissibility — against a
/// drafted, UNSIGNED response, and stops at the point the real path would
/// write. It writes no record, appends no journal line, and reaches no key.
/// The report names the exact rule the real ingest would refuse with, or
/// `<act>.would-record`, so an agent can learn "this will be refused because
/// X" without spending a human's dialog to find out.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IngestMode {
    Record,
    DryRun,
}

/// What the signer chose, beyond `y`.
#[derive(Debug, Clone)]
pub struct Options {
    /// Sign as this actor. Required when the register lists more than one
    /// eligible human.
    pub actor: Option<String>,
    /// Appended to the templated meaning, verbatim.
    pub meaning: Option<String>,
    /// A resolution outcome when §38.6 does not permit `satisfied`.
    pub outcome: Option<CommonOutcome>,
    /// §101.3 — required when the SAS revision is architecture-changing.
    pub adr_ref: Option<String>,
    pub independence: Independence,
    /// Open `$EDITOR` on the drafted response before the prompt.
    pub edit: bool,
    /// Sign every pending act, prompting once each.
    pub all: bool,
    /// Render the screen and stop: no prompt, no terminal needed, nothing
    /// written. For reading what a signature would say from anywhere.
    pub show: bool,
    /// Draft the response and run the act's ingest in [`IngestMode::DryRun`]:
    /// every refusal, no write, no key. The draft lives in a temp directory
    /// for the duration of the check and is removed; nothing lands under
    /// `docs/authority/responses/`. For an agent to troubleshoot an act before
    /// asking a human to sign it.
    pub dry_run: bool,
    /// Sign the response file with the actor's ssh key via `ssh-keygen -Y
    /// sign`, verified at once against `docs/authority/allowed_signers`. No
    /// terminal needed: the human act is the agent's confirmation dialog
    /// (`ssh-add -c`), which no shell can answer.
    pub ssh_sign: bool,
    /// Verify an existing response's `.sig` sidecar and stop. Writes nothing.
    pub verify: bool,
    /// For a correction: what kind of change it admits (OW-WAR-0064).
    pub kind: Option<openwarrant_core::correction::CorrectionKind>,
    /// OW-ADR-0029: the acts offered are revocations of signed classes, not
    /// the pending queue. A sweep never revokes.
    pub revoke: bool,
}

impl Default for Options {
    /// `separate_role` is the honest default for a sole-owner repository:
    /// §27.4 says role separation by one person is not organizational
    /// independence, and `None` would claim the signer did the work.
    fn default() -> Self {
        Self {
            dry_run: false,
            actor: None,
            meaning: None,
            outcome: None,
            adr_ref: None,
            independence: Independence::SeparateRole,
            edit: false,
            all: false,
            show: false,
            ssh_sign: false,
            verify: false,
            kind: None,
            revoke: false,
        }
    }
}

impl Options {
    /// Which channel a signature made under these options records.
    fn channel(&self) -> &'static str {
        if self.ssh_sign {
            CHANNEL_SSH
        } else {
            CHANNEL_TTY
        }
    }
}

/// The version string written into every drafted meaning, so a record says
/// which template produced it.
fn tool_version() -> String {
    format!("war sign {}", env!("CARGO_PKG_VERSION"))
}

/// Everything awaiting a signature, in alias order, SAS revisions last.
/// The index in `cell`, built from `repo` the first time it is asked for.
fn ownership_of<'a>(
    cell: &'a std::cell::OnceCell<crate::ownership::Ownership>,
    repo: &Repository,
) -> Result<&'a crate::ownership::Ownership, RepoError> {
    if let Some(index) = cell.get() {
        return Ok(index);
    }
    let index = crate::ownership::Ownership::index(repo)?;
    Ok(cell.get_or_init(|| index))
}

pub fn pending(repo: &Repository) -> Result<Vec<Pending>, RepoError> {
    // Loaded once, up front, and NOT swallowed. Every per-Warrant request
    // below reads the register, and their errors are skipped so one broken
    // Warrant does not hide the rest — which meant a broken register (a
    // duplicate key in roles.toml, found the first time it was hand-edited)
    // read as "nothing awaits a signature". A trust root that will not parse
    // is the loudest thing this command can say, not the quietest.
    repo.load_authority_register().map_err(|e| {
        RepoError::Message(format!("docs/authority/roles.toml will not load; nothing can be signed or listed until it does: {e}"))
    })?;
    let mut out = Vec::new();
    // The ownership index, built on the first correction request and shared
    // by the rest (`correct::request_with`).
    let ownership = std::cell::OnceCell::new();
    let mut dirs = repo.warrant_dirs()?;
    dirs.sort();
    for dir in dirs {
        let Some(alias) = dir.file_name().map(str::to_owned) else {
            continue;
        };
        let Ok(one) = repo.load_warrant(&dir) else {
            continue;
        };
        if one.validated.is_none() || one.basis.is_none() {
            continue;
        }
        let Ok(request) = authorize::request(repo, &alias) else {
            continue;
        };
        let authorization = repo.load_authorization(&dir)?;
        // Authorized means SIGNED and current, not merely recorded and current.
        // A record whose digest matches but whose signature does not verify is
        // pending again — that is how 57 file-only authorizations became acts
        // the owner can clear in one pass, rather than a corpus-wide exception.
        let authorized_current = authorization.as_ref().is_some_and(|a| {
            authorize::authorizes_current_contract(a, &request.contract_digest)
                && a.revision.authorization.as_ref().is_some_and(|auth| {
                    crate::authority_check::verify(
                        repo,
                        crate::authority_check::Act::Authorize,
                        &alias,
                        &auth.authorizer,
                        Some(&a.revision.contract_digest),
                    )
                    .is_signed()
                })
        });
        if !authorized_current {
            let revision = authorization.as_ref().map_or(1, |a| {
                if a.revision.contract_digest == request.contract_digest {
                    // Same bytes, missing signature: sign THIS revision. A bump
                    // here would claim the contract changed, and it did not.
                    a.revision.revision
                } else {
                    a.revision.revision + 1
                }
            });
            let amendment = if revision > 1 {
                read_latest_amendment(&dir)
            } else {
                None
            };
            out.push(Pending::Authorize {
                alias,
                request,
                amendment,
                revision,
            });
            continue;
        }
        if let Some(existing) = repo.load_resolution(&dir)? {
            // A recorded resolution with no verified signature is the same
            // situation as an unsigned authorization: the record exists, the
            // human act behind it was never proved, and the remedy is one
            // signature over the resolution as recorded. Offered only at the
            // digest the resolution itself binds — a resolution of a contract
            // that has since moved is stale, and `war check` says so rather
            // than inviting a signature that would launder the drift.
            let signed = crate::authority_check::verify(
                repo,
                crate::authority_check::Act::Resolve,
                &alias,
                existing
                    .resolution
                    .resolved_by_ref
                    .trim_start_matches("person://"),
                Some(&existing.resolution.contract_digest),
            )
            .is_signed();
            if !signed
                && let Ok(mut request) = resolution_cmd::request(repo, &alias)
                && request.contract_digest == existing.resolution.contract_digest
            {
                let assignment = narrow_resolvers(repo, &dir, &mut request.eligible_resolvers)?;
                let profile = one
                    .validated
                    .as_ref()
                    .map(|v| v.raw.profile.clone())
                    .unwrap_or_default();
                out.push(Pending::Resolve {
                    alias: alias.clone(),
                    request,
                    profile,
                    recorded: Some(RecordedOutcome {
                        common: existing.resolution.common_outcome,
                        profile: existing.resolution.profile_outcome.clone(),
                    }),
                    assignment,
                });
            }
            // The only other act a resolved Warrant admits is a correction, and
            // only when a content-addressed deliverable no longer matches its
            // chain head.
            let deliverables = repo.load_deliverables(&dir)?;
            // A recorded correction with no verified signature is the third
            // shape of the same problem: the record moved a delivered file past
            // the wall and nothing proves a human said so. Only the chain head
            // is offered — an earlier link's signature would have to live at the
            // same path as the head's, and overwriting one signature to place
            // another is not a repair.
            //
            // This comes BEFORE the drift rows and suppresses them for the same
            // deliverable. Offering both in one sweep had the first act record a
            // correction the second then found nothing to correct
            // (`correction.no-drift`), or had the second collide with the
            // signature the first had just placed (`sign.response-exists`) —
            // five errors in one batch, both of them the same double offer. The
            // head's missing signature is history and settles first; a new
            // drift is new work and waits for the next sweep, which is one more
            // `war sign --all` away.
            let mut supplied: std::collections::BTreeSet<String> =
                std::collections::BTreeSet::new();
            if let Ok(set) = repo.load_corrections(&dir) {
                let mut heads: std::collections::BTreeMap<String, &Correction> =
                    std::collections::BTreeMap::new();
                for c in set.records.iter().map(|(_, r)| &r.correction) {
                    heads
                        .entry(c.deliverable_id.clone())
                        .and_modify(|cur| {
                            if c.sequence > cur.sequence {
                                *cur = c;
                            }
                        })
                        .or_insert(c);
                }
                for (deliverable_id, c) in heads {
                    let subject = format!("{alias}.{deliverable_id}");
                    if crate::authority_check::verify(
                        repo,
                        crate::authority_check::Act::Correct,
                        &subject,
                        c.authorized_by_ref.trim_start_matches("person://"),
                        Some(&c.new_digest),
                    )
                    .is_signed()
                    {
                        continue;
                    }
                    if let Ok(index) = ownership_of(&ownership, repo)
                        && let Ok(request) =
                            crate::correct::request_with(repo, &alias, &deliverable_id, index)
                    {
                        supplied.insert(deliverable_id.clone());
                        out.push(Pending::Correct {
                            alias: alias.clone(),
                            deliverable_id,
                            request,
                            recorded: Some(RecordedCorrection {
                                superseded_digest: c.superseded_digest.clone(),
                                new_digest: c.new_digest.clone(),
                                reason: c.reason.clone(),
                                kind: c.kind,
                            }),
                        });
                    }
                }
            }
            for d in deliverables
                .records
                .iter()
                .filter(|d| d.content_addressed && !supplied.contains(&d.id))
            {
                if let Ok(index) = ownership_of(&ownership, repo)
                    && let Ok(request) = crate::correct::request_with(repo, &alias, &d.id, index)
                    && request.drift
                {
                    out.push(Pending::Correct {
                        alias: alias.clone(),
                        deliverable_id: d.id.clone(),
                        request,
                        recorded: None,
                    });
                }
            }
            continue;
        }
        let Ok(mut request) = resolution_cmd::request(repo, &alias) else {
            continue;
        };
        if request.requirements_met {
            let assignment = narrow_resolvers(repo, &dir, &mut request.eligible_resolvers)?;
            let profile = one
                .validated
                .as_ref()
                .map(|v| v.raw.profile.clone())
                .unwrap_or_default();
            out.push(Pending::Resolve {
                alias,
                request,
                profile,
                recorded: None,
                assignment,
            });
        }
    }
    let revisions = repo.load_sas_revisions()?;
    // Only the normative revision is offered for a signature it lacks. A
    // superseded revision governs nothing, and inviting a signature on it in
    // 2026 for an acceptance made in 2025 would date the act wrongly.
    let pin = crate::sas::pin_of(&revisions).map(|p| p.version.clone());
    for rev in revisions {
        let unsigned_pin = rev.state == SasRevisionState::Accepted
            && pin.as_deref() == Some(rev.version.as_str())
            && rev.acceptance.as_ref().is_some_and(|a| {
                !crate::authority_check::verify(
                    repo,
                    crate::authority_check::Act::Accept,
                    &format!("SAS-{}", rev.version),
                    &a.accepted_by,
                    Some(&rev.sha256),
                )
                .is_signed()
            });
        if rev.state == SasRevisionState::Proposed || unsigned_pin {
            let request = sas::accept_request(repo, &rev.version)?;
            out.push(Pending::Accept {
                version: rev.version,
                request,
            });
        }
    }
    if let Some(request) = crate::roadmap_cmd::pending_request(repo)? {
        out.push(Pending::AcceptRoadmap {
            revision: request.revision,
            request,
        });
    }
    for request in crate::standing_cmd::pending_acceptances(repo)? {
        out.push(Pending::AcceptStanding { request });
    }
    Ok(out)
}

/// The acts `war sign` offers under these options: the pending queue, or —
/// under `--revoke` — a revocation for every signed, unrevoked class and
/// nothing else, so a revocation is always named and never swept.
pub fn pending_for(repo: &Repository, opts: &Options) -> Result<Vec<Pending>, RepoError> {
    if opts.revoke {
        return Ok(crate::standing_cmd::revocable(repo)?
            .into_iter()
            .map(|request| Pending::RevokeStanding { request })
            .collect());
    }
    pending(repo)
}

/// OW-WAR-0137 — narrow a resolve act's eligible list by the Warrant's
/// assignment, in place. The list only ever shrinks: it is filtered by
/// [`authorize::assignment::narrow`], or emptied when the assignment is not
/// the one the authorizer signed. Nobody is ever pushed onto it.
fn narrow_resolvers(
    repo: &Repository,
    dir: &Utf8Path,
    eligible: &mut Vec<String>,
) -> Result<
    Option<Result<authorize::assignment::Narrowed, authorize::assignment::Finding>>,
    RepoError,
> {
    use authorize::assignment::{Act, narrow};
    let standing = authorize::assignment_standing(repo, dir)?;
    Ok(match standing.for_act(Act::Resolve) {
        Ok(None) => None,
        Ok(Some(assigned)) => {
            let n = narrow(eligible, assigned);
            eligible.clone_from(&n.eligible);
            Some(Ok(n))
        }
        Err(finding) => {
            eligible.clear();
            Some(Err(finding))
        }
    })
}

/// Who signs `p`: [`choose_actor`] over the narrowed list, with the reason a
/// signer was refused named by rule — `sign.not-assigned` for an eligible
/// actor the assignment leaves out, `assignment.role-revoked` when every
/// assigned actor has since lost the role, the standing's own rule when the
/// assignment is not what the authorizer signed, `sign.who` otherwise.
pub(crate) fn who(p: &Pending, opts: &Options) -> Result<String, (&'static str, String)> {
    let assignment = match p {
        Pending::Resolve { assignment, .. } => assignment.as_ref(),
        _ => None,
    };
    // OW-ADR-0029: a class act names WHY a register holder may not sign it —
    // an agent by kind, the performer as SelfAct — rather than only that
    // the name is not on the eligible list.
    let refused_signers = match p {
        Pending::AcceptStanding { request } => Some(&request.refused_signers),
        Pending::RevokeStanding { request } => Some(&request.refused_signers),
        _ => None,
    };
    if let (Some(list), Some(a)) = (refused_signers, &opts.actor)
        && let Some((_, why)) = list.iter().find(|(who, _)| who == a)
    {
        return Err(("standing.not-permitted", format!("{a}: {why}")));
    }
    match assignment {
        None => choose_actor(eligible(p), opts).map_err(|why| ("sign.who", why)),
        Some(Err(finding)) => Err((finding.rule, finding.message.clone())),
        Some(Ok(n)) => {
            if let Some(a) = &opts.actor
                && !n.eligible.contains(a)
                && n.before.contains(a)
            {
                return Err((
                    "sign.not-assigned",
                    format!(
                        "{a} holds the role and is not assigned to {}; the assignment the \
                         authorizer signed names {}. An assignment narrows who may sign",
                        role(p),
                        assigned_names(n)
                    ),
                ));
            }
            if n.eligible.is_empty() && !n.revoked.is_empty() {
                return Err((
                    "assignment.role-revoked",
                    format!(
                        "the assigned {} ({}) no longer hold(s) the role in \
                         docs/authority/roles.toml, so nobody may sign. Nobody else is \
                         substituted: restore the role, or amend the assignment and \
                         re-authorize",
                        role(p),
                        n.revoked.join(", ")
                    ),
                ));
            }
            choose_actor(&n.eligible, opts).map_err(|why| ("sign.who", why))
        }
    }
}

fn assigned_names(n: &authorize::assignment::Narrowed) -> String {
    let mut all: Vec<&str> = n
        .eligible
        .iter()
        .chain(n.revoked.iter())
        .map(String::as_str)
        .collect();
    all.sort_unstable();
    all.join(", ")
}

/// Whether `p` is assigned to `actor` by name (not merely open to them).
fn assigned_to(p: &Pending, actor: &str) -> bool {
    matches!(p, Pending::Resolve { assignment: Some(Ok(n)), .. } if n.eligible.iter().any(|e| e == actor))
}

/// OW-WAR-0137 — one person's queue: the acts `actor` may sign now, acts
/// assigned to them by name first. Built from [`pending`], so it can only
/// ever be a subset of what the register and the assignments allow.
pub fn queue(repo: &Repository, actor: &str) -> Result<Vec<Pending>, RepoError> {
    let mut mine: Vec<Pending> = pending(repo)?
        .into_iter()
        .filter(|p| eligible(p).iter().any(|e| e == actor))
        .collect();
    // Stable: within each group, the order `pending` gives.
    mine.sort_by_key(|p| !assigned_to(p, actor));
    Ok(mine)
}

/// `war sign --list --json`: one entry per pending act, the same list the
/// text shows. `assigned` names who an assignment chose (empty when none);
/// `blocked_by` is the rule that lets nobody sign; under `--as`,
/// `assigned_to_actor` says whether the act is theirs by name.
#[must_use]
pub fn list_json(list: &[Pending], actor: Option<&str>) -> serde_json::Value {
    let acts: Vec<serde_json::Value> = list
        .iter()
        .map(|p| {
            let (target, act) = match p {
                Pending::Authorize { alias, .. } => (alias.clone(), "authorize"),
                Pending::Resolve { alias, .. } => (alias.clone(), "resolve"),
                Pending::Accept { version, .. } => (format!("SAS-{version}"), "accept"),
                Pending::AcceptRoadmap { revision, .. } => {
                    (crate::roadmap_cmd::subject(*revision), "accept_roadmap")
                }
                Pending::AcceptStanding { .. } | Pending::RevokeStanding { .. } => {
                    (target_of(p), act_name(p))
                }
                Pending::Correct {
                    alias,
                    deliverable_id,
                    ..
                } => (format!("{alias}/{deliverable_id}"), "correct"),
                Pending::Invalidate { gate, .. } => (gate.clone(), "invalidate"),
            };
            let (assigned, blocked_by) = match p {
                Pending::Resolve {
                    assignment: Some(Ok(n)),
                    ..
                } => (n.eligible.iter().chain(&n.revoked).cloned().collect(), None),
                Pending::Resolve {
                    assignment: Some(Err(f)),
                    ..
                } => (Vec::new(), Some(f.rule)),
                _ => (Vec::<String>::new(), None),
            };
            let mut v = serde_json::json!({
                "target": target,
                "act": act,
                "role": role(p),
                "eligible": eligible(p),
                "assigned": assigned,
                "blocked_by": blocked_by,
                "line": line(p),
            });
            if let Some(a) = actor {
                v["assigned_to_actor"] = serde_json::Value::Bool(assigned_to(p, a));
            }
            v
        })
        .collect();
    serde_json::json!({ "actor": actor, "acts": acts })
}

/// `war sign --list`, for everyone or for one actor.
pub fn list_for(repo: &Repository, actor: Option<&str>) -> Result<Vec<Pending>, RepoError> {
    match actor {
        Some(a) => queue(repo, a),
        None => pending(repo),
    }
}

/// The most recent `amendments/AM-*.yaml`, read line-wise for its `reason`
/// and `semantic_diff` entries.
fn read_latest_amendment(dir: &Utf8Path) -> Option<AmendmentSummary> {
    read_amendments(dir).pop()
}

/// Every amendment under `amendments/`, oldest first (slice D1 reads all),
/// in `crate::amendment_id`'s order: ordinal, then `effective_time`, then
/// name — so `AM-004-1f3a` and `AM-004-c07e` from two branches both show,
/// and `AM-1000` follows `AM-999`. `.yaml` only, as before.
pub(crate) fn read_amendments(dir: &Utf8Path) -> Vec<AmendmentSummary> {
    crate::amendment_id::files(dir)
        .into_iter()
        .filter(|f| f.path.extension() == Some("yaml"))
        .filter_map(|f| read_amendment(&f.path))
        .collect()
}

fn read_amendment(path: &Utf8Path) -> Option<AmendmentSummary> {
    let text = std::fs::read_to_string(path).ok()?;
    let mut summary = AmendmentSummary {
        id: path.file_stem().unwrap_or_default().to_owned(),
        ..Default::default()
    };
    let unquote = |s: &str| s.trim().trim_matches('"').to_owned();
    let (mut element, mut before) = (None::<String>, None::<String>);
    for line in text.lines() {
        let t = line.trim_start();
        if let Some(v) = t.strip_prefix("reason:") {
            summary.reason = unquote(v);
        } else if let Some(v) = t.strip_prefix("- element:") {
            element = Some(unquote(v));
        } else if let Some(v) = t.strip_prefix("before:") {
            before = Some(unquote(v));
        } else if let Some(v) = t.strip_prefix("after:")
            && let (Some(e), Some(b)) = (element.take(), before.take())
        {
            summary.changes.push((e, b, unquote(v)));
        }
    }
    Some(summary)
}

/// `war sign` with no target: the list. Needs no terminal; it writes nothing.
pub fn list(repo: &Repository) -> Result<Vec<Pending>, RepoError> {
    pending(repo)
}

/// Render one pending act as a line for the list.
#[must_use]
pub fn line(p: &Pending) -> String {
    let base = line_of(p);
    match p {
        Pending::Resolve {
            assignment: Some(Ok(n)),
            ..
        } => format!("{base}  [assigned: {}]", assigned_names(n)),
        Pending::Resolve {
            assignment: Some(Err(f)),
            ..
        } => format!("{base}  [{}]", f.rule),
        _ => base,
    }
}

fn line_of(p: &Pending) -> String {
    match p {
        Pending::Authorize {
            alias,
            request,
            amendment,
            revision,
        } => format!(
            "{alias}  rev {revision}  authorize  {}{}",
            request.title,
            amendment
                .as_ref()
                .map(|a| format!("  [{}]", a.id))
                .unwrap_or_default()
        ),
        Pending::Resolve {
            alias,
            request,
            recorded: Some(rec),
            ..
        } => format!(
            "{alias}  resolve  signature only, recorded {}  {}",
            rec.common, request.title
        ),
        Pending::Resolve { alias, request, .. } => format!(
            "{alias}  resolve  would resolve {}  {}",
            if request.would_resolve_satisfied == Some(true) {
                "SATISFIED"
            } else {
                "not satisfied"
            },
            request.title
        ),
        Pending::AcceptRoadmap { revision, request } => format!(
            "roadmap  rev {revision}  accept  {} phase(s): {}",
            request.phase_count,
            request.diff.summary()
        ),
        Pending::Accept { version, request } => format!(
            "SAS {version}  accept  {} requirement(s){}",
            request.requirement_count,
            if request.adr_required {
                "  (architecture-changing: --adr required)"
            } else {
                ""
            }
        ),
        Pending::AcceptStanding { request } => format!(
            "{}  accept  standing authorization, {} glob(s){}",
            target_of(p),
            request.class.as_ref().map_or(0, |c| c.paths.len()),
            if request.refusals.is_empty() {
                String::new()
            } else {
                format!("  [REFUSED: {}]", request.refusals.len())
            }
        ),
        Pending::RevokeStanding { request } => format!(
            "{}  revoke  standing authorization, {} Warrant(s) covered so far",
            target_of(p),
            request.covered.len()
        ),
        Pending::Correct {
            alias,
            deliverable_id,
            request,
            ..
        } => format!(
            "{alias}/{deliverable_id}  correct  {} drifted (correction {})  {}",
            request.target_ref, request.next_sequence, request.title
        ),
        Pending::Invalidate { gate, request } => format!(
            "{gate}  invalidate  would dispute {} resolution(s)",
            request.disputes.len()
        ),
    }
}

/// The screen the signer sees. Facts from the record; nothing recommended.
/// Wrap at a width, on spaces: the screen is read by a person at a terminal.
fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut out = Vec::new();
    let mut line = String::new();
    for word in text.split_whitespace() {
        if !line.is_empty() && line.len() + 1 + word.len() > width {
            out.push(std::mem::take(&mut line));
        }
        if !line.is_empty() {
            line.push(' ');
        }
        line.push_str(word);
    }
    if !line.is_empty() {
        out.push(line);
    }
    out
}

fn screen(p: &Pending, actor: &str, role: &str, reason: Option<&str>) -> String {
    let mut s = String::new();
    match p {
        Pending::Authorize {
            alias,
            request,
            amendment,
            revision,
        } => {
            s.push_str(&format!(
                "┌ {alias} · authorize revision {revision} · {}\n│ {}\n",
                request.assurance_level, request.title
            ));
            if let Some(a) = amendment {
                s.push_str(&format!(
                    "│ amendment {}: {}\n",
                    a.id,
                    first_sentence(&a.reason)
                ));
                for (e, b, af) in &a.changes {
                    s.push_str(&format!("│   {e}\n│     before: {b}\n│     after:  {af}\n"));
                }
            }
            s.push_str(&format!(
                "│ {} obligation(s)  ·  {} residual risk(s)\n",
                request.obligations.len(),
                request.residual_risks.len()
            ));
            for r in &request.residual_risks {
                s.push_str(&format!(
                    "│   {}  {}\n│       if false: {}\n",
                    r.assumption_id, r.statement, r.consequence_if_false
                ));
            }
            s.push_str(&format!(
                "│ contract sha256:{}  ·  covers {}\n",
                &request.contract_digest[..16],
                request.contract_coverage.join(", ")
            ));
            // OW-ADR-0021: the signature grants ownership of these paths.
            // Listed in full — a signer who cannot see what they grant is
            // signing a digest, and a digest hides a path as well as it
            // protects one.
            if request.deliverables.is_empty() {
                s.push_str("│ grants ownership of: nothing declared\n");
            } else {
                s.push_str(&format!(
                    "│ grants ownership of {} path(s)  ·  set {}\n",
                    request.deliverables.len(),
                    request
                        .deliverable_set_digest
                        .strip_prefix("sha256:")
                        .map_or("", |d| &d[..12])
                ));
                for d in &request.deliverables {
                    s.push_str(&format!("│   {}  {}\n", d.id, d.target_ref));
                }
            }
            // OW-WAR-0137: who reviews is part of what is signed.
            if let Some(a) = &request.assignment {
                s.push_str(&format!(
                    "│ assigns review  ·  {}\n",
                    request
                        .assignment_digest
                        .strip_prefix("sha256:")
                        .map_or("", |d| &d[..12])
                ));
                for (act, who) in [("verify", &a.verify), ("resolve", &a.resolve)] {
                    if !who.is_empty() {
                        s.push_str(&format!("│   {act}: {}\n", who.join(", ")));
                    }
                }
            }
            for f in &request.assignment_findings {
                s.push_str(&format!("│   REFUSED {f}\n"));
            }
        }
        Pending::Resolve { alias, request, .. } => {
            s.push_str(&format!(
                "┌ {alias} · resolve · revision {}\n│ {}\n",
                request.contract_revision, request.title
            ));
            s.push_str(&format!(
                "│ thirteen requirements: {}  ·  §38.6 would resolve satisfied: {}\n",
                if request.requirements_met {
                    "all met"
                } else {
                    "UNMET"
                },
                request
                    .would_resolve_satisfied
                    .map_or("n/a".to_owned(), |b| b.to_string())
            ));
            s.push_str(&format!(
                "│ established {}  ·  unestablished {}\n",
                request.established.len(),
                request.unestablished.len()
            ));
            for u in &request.unestablished {
                s.push_str(&format!("│   unestablished: {u}\n"));
            }
            s.push_str(&format!(
                "│ permitted outcomes: {}\n│ contract sha256:{}\n",
                request.permitted_outcomes.join(", "),
                &request.contract_digest[..16]
            ));
        }
        Pending::AcceptRoadmap { revision, request } => {
            s.push_str(&format!(
                "┌ roadmap revision {revision} · accept · sha256:{}\n│ predecessor {}  ·  {} phase(s)\n│ {}\n",
                &request.sha256[..16],
                request.predecessor.map_or("none".to_owned(), |p| p.to_string()),
                request.phase_count,
                request.diff.summary()
            ));
            if let Some(n) = &request.note {
                s.push_str(&format!("│ the proposer says: {n}\n"));
            }
        }
        Pending::Accept { version, request } => {
            s.push_str(&format!(
                "┌ SAS {version} · accept · sha256:{}\n│ predecessor {}  ·  {} requirement(s)  ·  architecture-changing: {}\n",
                &request.sha256[..16],
                request.predecessor.as_deref().unwrap_or("none"),
                request.requirement_count,
                request.architecture_changing
            ));
            s.push_str(&format!(
                "│ §106 diff: +{} −{} ~{}\n",
                request.diff.added.len(),
                request.diff.removed.len(),
                request.diff.retitled.len()
            ));
        }
        Pending::AcceptStanding { request } => {
            s.push_str(&format!(
                "┌ {} · accept a STANDING AUTHORIZATION · sha256:{}\n│ {}\n",
                request.reference,
                &request.sha256[..16],
                request.file
            ));
            if let Some(c) = &request.class {
                for (i, line) in wrap(&c.meaning, 70).into_iter().enumerate() {
                    s.push_str(&format!(
                        "│ {}{line}\n",
                        if i == 0 { "meaning: " } else { "         " }
                    ));
                }
                s.push_str(&format!(
                    "│ {} at {} · gates: {}\n│ per stage ≤ {} tokens, ≤ {} s · ≤ {} stage(s), ≤ {} deliverable(s)\n│ expires {} · covers at most {} Warrant(s)\n",
                    c.profile,
                    c.assurance,
                    c.gates.join(", "),
                    c.budget.budget_tokens,
                    c.budget.wall_time_seconds,
                    c.budget.max_stages,
                    c.budget.max_deliverables,
                    c.expires_at,
                    c.max_warrants
                ));
            }
            // What the signature grants, glob by glob, with what each
            // matches today: a signer who cannot see a class's reach is
            // signing a digest.
            s.push_str("│ Covers:\n");
            for (glob, matched) in &request.covers {
                s.push_str(&format!("│   {glob}  ({} file(s) today)\n", matched.len()));
                for m in matched {
                    s.push_str(&format!("│     {m}\n"));
                }
            }
            for r in &request.refusals {
                s.push_str(&format!("│   REFUSED {r}\n"));
            }
            s.push_str(
                "│ each Warrant inside it is authorized in your name with no further act; each is still resolved by you\n",
            );
        }
        Pending::RevokeStanding { request } => {
            s.push_str(&format!(
                "┌ {} · REVOKE a standing authorization · sha256:{}\n│ it covers nothing new after this; {} record(s) made under it stand (§31)\n",
                request.reference,
                &request.sha256[..16],
                request.covered.len()
            ));
            for a in &request.covered {
                s.push_str(&format!("│   {a}\n"));
            }
        }
        Pending::Correct {
            alias,
            deliverable_id,
            request,
            ..
        } => {
            s.push_str(&format!(
                "┌ {alias} · correct {deliverable_id} · correction {} of a RESOLVED Warrant\n│ {}\n│ {}\n",
                request.next_sequence, request.title, request.target_ref
            ));
            s.push_str(&format!(
                "│ recorded   {}\n│ supersedes {}{}\n│ now        {}\n",
                request.recorded_digest,
                request.chain_head,
                if request.prior_corrections > 0 {
                    format!(
                        "  (after {} prior correction(s))",
                        request.prior_corrections
                    )
                } else {
                    String::new()
                },
                request.current_digest
            ));
            if let Some(reason) = reason {
                // What the record will say, wrapped, before the prompt. A
                // signature over text the signer never read is the defect this
                // whole seam exists to prevent.
                for (i, line) in wrap(reason, 72).into_iter().enumerate() {
                    s.push_str(&format!(
                        "│ {}{line}\n",
                        if i == 0 { "reason: " } else { "        " }
                    ));
                }
            }
            s.push_str(
                "│ the pin in deliverables.toml is not edited; the superseded digest stays on record\n",
            );
        }
        Pending::Invalidate { gate, request } => {
            s.push_str(&format!(
                "┌ {gate} · invalidate · {}\n│ definition {}  ·  {}\n",
                request.lifecycle, request.definition_file, request.definition_digest
            ));
            for (i, line) in wrap(&request.grounds, 72).into_iter().enumerate() {
                s.push_str(&format!(
                    "│ {}{line}\n",
                    if i == 0 { "grounds: " } else { "         " }
                ));
            }
            s.push_str(&format!(
                "│ disputes {} resolution(s), leaves {} standing\n",
                request.disputes.len(),
                request.unaffected.len()
            ));
            for d in &request.disputes {
                s.push_str(&format!(
                    "│   {}  resolved by {}  via {}\n",
                    d.warrant,
                    d.resolved_by,
                    d.via.join("; ")
                ));
            }
            s.push_str(
                "│ no resolution.toml and not the definition file is edited; standing is read from the disputes\n",
            );
        }
    }
    s.push_str(&format!("└ Sign as {actor} ({role})? [y/N] "));
    s
}

fn first_sentence(s: &str) -> String {
    let end = s.find(". ").map_or(s.len(), |i| i + 1);
    s[..end].to_owned()
}

/// The templated meaning. Says what it is.
fn provenance() -> String {
    format!(
        "Presented on a terminal by `{}` and confirmed by the signer; the decision \
         is the signer's and the template is the tool's.",
        tool_version()
    )
}

/// What a correction's reason says when the signer does not type one.
///
/// A signature should cost a keystroke, not an essay, and the reason a
/// delivered artifact moved is already on record: the commits that touched the
/// file since the Warrant resolved, each with its own message. So the tool
/// drafts from those and `--meaning` appends the signer's words when they have
/// any to add. The judgement stays theirs: `--kind` is still required, because
/// whether a change alters behaviour or adds a refusal is not a fact the tree
/// carries.
fn drafted_correction_reason(repo: &Repository, alias: &str, target_ref: &str) -> String {
    let since = repo
        .warrant_dir(alias)
        .ok()
        .and_then(|d| repo.load_resolution(&d).ok().flatten())
        .map(|r| r.resolution.effective_at.clone());
    let mut args: Vec<String> = vec![
        "log".to_owned(),
        "--format=%s".to_owned(),
        "--max-count=6".to_owned(),
    ];
    if let Some(when) = &since {
        args.push(format!("--since={when}"));
    }
    args.push("--".to_owned());
    args.push(target_ref.to_owned());
    let subjects: Vec<String> = std::process::Command::new("git")
        .args(&args)
        .current_dir(&repo.root)
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| {
            String::from_utf8_lossy(&o.stdout)
                .lines()
                .map(str::trim)
                .filter(|l| !l.is_empty())
                .map(str::to_owned)
                .collect()
        })
        .unwrap_or_default();
    let when = since.as_deref().map_or_else(
        || "it resolved".to_owned(),
        |w| format!("its resolution at {w}"),
    );
    if subjects.is_empty() {
        return format!(
            "{target_ref} moved after {when}; the repository records no commit touching it since, so the bytes changed without a commit message to cite."
        );
    }
    let shown: Vec<String> = subjects
        .iter()
        .take(3)
        .map(|s| format!("\"{s}\""))
        .collect();
    format!(
        "{target_ref} moved after {when}: {} commit(s) touched it, {}{}. Each states its own          change; this correction records that the delivered bytes moved with them.",
        subjects.len(),
        shown.join("; "),
        if subjects.len() > shown.len() {
            format!(" and {} more", subjects.len() - shown.len())
        } else {
            String::new()
        }
    )
}

/// The reason a correction will record: the signer's words when they typed
/// any, else the draft from the record. `None` for every other act, whose
/// meaning is templated inside `draft`.
pub(crate) fn reason_for(repo: &Repository, p: &Pending, opts: &Options) -> Option<String> {
    if let Some(m) = opts.meaning.as_deref().filter(|m| !m.trim().is_empty()) {
        return Some(m.to_owned());
    }
    match p {
        Pending::Correct { alias, request, .. } => {
            Some(drafted_correction_reason(repo, alias, &request.target_ref))
        }
        _ => None,
    }
}

/// Draft the response for one pending act. Pure: no I/O, so it is testable.
pub fn draft(p: &Pending, actor: &str, opts: &Options, now: &str) -> Result<Drafted, String> {
    let extra = opts
        .meaning
        .as_deref()
        .map(|m| format!(" {m}"))
        .unwrap_or_default();
    match p {
        Pending::Authorize { alias, request, .. } => {
            let judgment = request
                .residual_risks
                .iter()
                .enumerate()
                .map(|(i, r)| Judgment {
                    id: format!("J-{:03}", i + 1),
                    kind: "residual_risk_acceptance".to_owned(),
                    statement: r.statement.clone(),
                    actor: actor.to_owned(),
                    acting_role: "risk_acceptor".to_owned(),
                    meaning: format!(
                        "Accepting residual risk {} for {alias}: if the assumption is false, \
                         the consequence is: {} {}",
                        r.assumption_id,
                        r.consequence_if_false,
                        provenance()
                    ),
                    basis_refs: vec![format!("assumption://{}", r.assumption_id)],
                    authority: JudgmentAuthority::Authorized,
                    limitations: vec![],
                })
                .collect::<Vec<_>>();
            let response = AuthorizationResponse {
                schema: authorize::RESPONSE_SCHEMA.to_owned(),
                warrant: alias.clone(),
                contract_digest: request.contract_digest.clone(),
                authorizer: actor.to_owned(),
                acting_role: "authorizer".to_owned(),
                meaning: format!(
                    "Authorizing {alias} ({}) at this contract digest means the signer accepts \
                     its intent, scope and {} obligation(s) as the work to be done and judged, \
                     and accepts each of the {} residual risk(s) recorded below with its stated \
                     consequence. It does not resolve the Warrant; resolution still requires \
                     the §56.1 evidence.{extra} {}",
                    request.title,
                    request.obligations.len(),
                    judgment.len(),
                    provenance()
                ),
                effective_time: now.to_owned(),
                policy_basis: None,
                independence: opts.independence,
                judgment,
                signed_via: Some(opts.channel().to_owned()),
                deliverable_set_digest: Some(request.deliverable_set_digest.clone()),
                // OW-WAR-0137: echoed only when the Warrant assigns anyone, so
                // the signature covers who reviews exactly as it was listed.
                assignment_digest: (!request.assignment_digest.is_empty())
                    .then(|| request.assignment_digest.clone()),
            };
            Ok(Drafted::Authorize(response))
        }
        Pending::Resolve {
            alias,
            request,
            profile,
            recorded,
            ..
        } => {
            // A signature supplied for a recorded resolution repeats that
            // record's outcome. Re-deciding it here would let a signature say
            // something the resolution never said.
            let outcome = match recorded {
                Some(rec) => rec.common,
                None => match (request.would_resolve_satisfied, opts.outcome) {
                    (_, Some(o)) => o,
                    (Some(true), None) => CommonOutcome::Satisfied,
                    _ => {
                        return Err(format!(
                            "{alias}: §38.6 does not permit `satisfied` ({} obligation(s) \
                             unestablished); pass --outcome not_satisfied|cancelled|blocked",
                            request.unestablished.len()
                        ));
