// SPDX-License-Identifier: Apache-2.0
//! `war pins` — every file some Warrant's `deliverables.toml` pins, with the
//! Warrant's state, so an agent (or a hook) can refuse the edit BEFORE it
//! drifts a resolved record.
//!
//! `war check` diagnoses drift after the fact. By then the edit is made, the
//! digest has moved, and for a resolved Warrant the only way forward is a
//! correction signed by a human (OW-WAR-0064). A list of what is pinned, asked
//! before editing, turns that into "open a new Warrant instead" — which is what
//! the rule wanted all along. The Claude Code plugin's PreToolUse hook reads
//! this with `--json --resolved-only`.

use serde::Serialize;

use crate::repo::{RepoError, Repository};

pub const SCHEMA: &str = "oh.war/pins/v1";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum PinState {
    /// A resolution binds the manifest: only a correction can move this file.
    Resolved,
    /// Authorized, not resolved: regenerate the record after editing.
    Authorized,
    /// Draft: the record is free to change with the file.
    Draft,
}

#[derive(Debug, Clone, Serialize)]
pub struct Pin {
    pub path: String,
    pub warrant: String,
    pub deliverable_id: String,
    pub state: PinState,
    pub content_addressed: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub content_digest: Option<String>,
    /// Corrections on file for this deliverable (OW-WAR-0064).
    pub corrections: u32,
    /// OW-ADR-0021 — a resolved pin that a LATER authorized Warrant's recorded
    /// set governs. Still recorded, still verifiable at its own resolution, and
    /// not drift. The hook lets an edit through when this is true.
    pub historical: bool,
    /// `<alias>/<D-id>` of the Warrant that governs this path now, when it is
    /// not this pin's own Warrant.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub governed_by: Option<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct Pins {
    pub schema: &'static str,
    pub pins: Vec<Pin>,
}

/// Every pin in the corpus, sorted by path then Warrant.
pub fn list(repo: &Repository, resolved_only: bool) -> Result<Pins, RepoError> {
    let mut pins = Vec::new();
    let ownership = crate::ownership::Ownership::index(repo)?;
    for dir in repo.warrant_dirs()? {
        let Some(alias) = dir.file_name().map(str::to_owned) else {
            continue;
        };
        let deliverables = repo.load_deliverables(&dir)?;
        if deliverables.records.is_empty() {
            continue;
        }
        let authorization = repo.load_authorization(&dir)?;
        let state = if repo.load_resolution(&dir)?.is_some() {
            PinState::Resolved
        } else if authorization.is_some() {
            PinState::Authorized
        } else {
            PinState::Draft
        };
        let authorized_at = authorization
            .as_ref()
            .and_then(|a| a.revision.authorization.as_ref())
            .map(|a| a.effective_time.clone());
        if resolved_only && state != PinState::Resolved {
            continue;
        }
        let corrections = repo.load_corrections(&dir)?;
        for d in &deliverables.records {
            let newer = ownership.newer_than(&d.target_ref, &alias, authorized_at.as_deref());
            pins.push(Pin {
                path: d.target_ref.clone(),
                warrant: alias.clone(),
                deliverable_id: d.id.clone(),
                state,
                content_addressed: d.content_addressed,
                content_digest: d.provenance.as_ref().map(|p| p.content_digest.clone()),
                corrections: u32::try_from(corrections.for_deliverable(&d.id).len())
                    .unwrap_or(u32::MAX),
                historical: state == PinState::Resolved && newer.is_some(),
                governed_by: newer.map(|o| format!("{}/{}", o.alias, o.deliverable_id)),
            });
        }
    }
    pins.sort_by(|a, b| a.path.cmp(&b.path).then(a.warrant.cmp(&b.warrant)));
    Ok(Pins {
        schema: SCHEMA,
        pins,
    })
}

/// One line per pin, for humans.
#[must_use]
pub fn render(p: &Pins) -> String {
    let mut s = String::new();
    for pin in &p.pins {
        s.push_str(&format!(
            "{:<10} {:<12} {:<6} {}{}{}\n",
            match (pin.state, pin.historical) {
                (PinState::Resolved, true) => "historical",
                (PinState::Resolved, false) => "resolved",
                (PinState::Authorized, _) => "authorized",
                (PinState::Draft, _) => "draft",
            },
            pin.warrant,
            pin.deliverable_id,
            pin.path,
            if pin.corrections > 0 {
                format!("  (corrected {}×)", pin.corrections)
            } else {
                String::new()
            },
            match &pin.governed_by {
                Some(g) => format!("  → governed by {g}"),
                None => String::new(),
            }
        ));
    }
    if s.is_empty() {
        s.push_str("no deliverables are pinned\n");
    }
    s
}

/// `war pins --candidate <rev>` — each pin, and beside every resolved
/// Warrant's pins whether the candidate is still the one a human accepted
/// (OW-WAR-0134): `unchanged`, `moved` with the in-scope paths
/// (`acceptance.candidate-moved`), or `UNKNOWN` with the reason. The finding
/// is about the candidate; nothing here writes a resolution.
///
/// The report is the verdict: an in-scope move is an error and an UNKNOWN
/// blocks, so either exits non-zero. `base`, when given, sets aside every
/// Warrant already resolved there — merged earlier, not a candidate now —
/// which is how CI asks only about the acceptances a pull request carries.
pub fn candidate(
    repo: &Repository,
    candidate: &str,
    base: Option<&str>,
    resolved_only: bool,
) -> Result<(crate::diagnostic::Report, serde_json::Value), RepoError> {
    let pins = list(repo, resolved_only)?;
    let (report, acceptance) = crate::acceptance::assess(repo, candidate, base)?;
    let beside: Vec<serde_json::Value> = pins
        .pins
        .iter()
        .map(|pin| {
            let mut v = crate::output::value(pin);
            if pin.state == PinState::Resolved
                && let Some(a) = acceptance
                    .warrants
                    .iter()
                    .find(|a| a.warrant == pin.warrant)
                && let Some(obj) = v.as_object_mut()
            {
                obj.insert("acceptance".to_owned(), crate::output::value(&a.state));
            }
            v
        })
        .collect();
    Ok((
        report,
        serde_json::json!({
            "schema": SCHEMA,
            "pins": beside,
            "acceptance": crate::output::value(&acceptance),
        }),
    ))
}

/// `war pins --history <path>` — every Warrant that ever governed a path,
/// oldest first, and whether each delivery still verifies from history.
///
/// A historical pin is a claim about bytes at a moment. The moment is the
/// resolution's `[locator]` when one was recorded (OW-ADR-0021); before that
/// ADR nothing recorded a commit, and the honest answer for those is UNKNOWN,
/// not a guess from `git log`.
pub fn history(repo: &Repository, path: &str) -> Result<String, RepoError> {
    let ownership = crate::ownership::Ownership::index(repo)?;
    let mut s = String::new();
    let mut rows: Vec<(String, String, String, String)> = Vec::new();
    // Every pin on this path, owner or not: legacy Warrants own nothing but
    // did deliver, and the lineage is incomplete without them.
    for dir in repo.warrant_dirs()? {
        let Some(alias) = dir.file_name().map(str::to_owned) else {
            continue;
        };
        let deliverables = repo.load_deliverables(&dir)?;
        for d in deliverables.records.iter().filter(|d| d.target_ref == path) {
            let resolved = repo.load_resolution(&dir)?;
            let recorded = d
                .provenance
                .as_ref()
                .map(|p| p.content_digest.clone())
                .unwrap_or_else(|| "(no digest)".into());
            // A broken chain has no head; the recorded digest stands in and
            // the row says so through `verifies`, never through a guess.
            let head = crate::correct::head_for(&repo.load_corrections(&dir)?, &d.id, &recorded)
                .1
                .unwrap_or_else(|_| recorded.clone());
            let standing = match (&resolved, ownership.current(path)) {
                (None, _) => "draft or authorized".to_owned(),
                (Some(_), Some(cur)) if cur.alias == alias => "current".to_owned(),
                (Some(_), Some(cur)) => format!("historical → {}", cur.alias),
                (Some(_), None) => "resolved, ungoverned".to_owned(),
            };
            let verifies = match resolved.as_ref().map(|r| r.locator.as_ref()) {
                // An unresolved pin is a note about a file, not a delivery;
                // asking whether it verifies from history is the wrong question.
                None => "not yet resolved".to_owned(),
                Some(None) => "UNKNOWN (no locator; resolved before OW-ADR-0021)".to_owned(),
                Some(Some(loc)) => {
                    let want = head.trim_start_matches("sha256:");
                    let out = std::process::Command::new("git")
                        .args(["show", &format!("{}:{}", loc.commit_sha, path)])
                        .current_dir(&repo.root)
                        .output();
                    match out {
                        Ok(o)
                            if o.status.success()
                                && openwarrant_compiler::sha256_hex(&o.stdout) == want =>
                        {
                            format!("verifies at {}", &loc.commit_sha[..12])
                        }
                        Ok(o) if o.status.success() => {
                            format!("DIFFERS at {}", &loc.commit_sha[..12])
                        }
                        _ => format!("UNKNOWN (commit {} not readable)", &loc.commit_sha[..12]),
                    }
                }
            };
            let when = resolved
                .as_ref()
                .map(|r| r.resolution.effective_at.clone())
                .unwrap_or_default();
            rows.push((
                when,
                format!("{alias}/{}", d.id),
                format!("{standing}  {}", &head[..std::cmp::min(19, head.len())]),
                verifies,
            ));
        }
    }
    rows.sort();
    if rows.is_empty() {
        s.push_str(&format!("no Warrant declares {path}\n"));
        return Ok(s);
    }
    s.push_str(&format!("{path}\n"));
    for (when, who, what, verifies) in rows {
        s.push_str(&format!(
            "  {:<22} {:<20} {:<40} {}\n",
            if when.is_empty() {
                "—".to_owned()
            } else {
                when
            },
            who,
            what,
            verifies
        ));
    }
    Ok(s)
}

/// `war pins --refresh [alias]` — bring an unresolved Warrant's recorded
/// digests back to the bytes on disk.
///
/// The gap this fills: a Warrant is written at the start of the work, its
/// deliverables name files that are still being written, and every commit moves
/// them. Before this existed the only way to re-record a digest was to edit
/// `deliverables.toml` by hand, so `war check` reported drift on every run and
/// the operator learned to ignore it — which is worse than not checking, because
/// the same rule guards resolved records where it matters.
///
/// Refused for a RESOLVED Warrant, whose §56.2 record binds
/// `sha256(deliverables.toml)`: moving a pin there changes what was accepted,
/// and `war correct` is the act that exists for it. An authorization binds the
/// contract, not the bytes, so an authorized-but-unresolved Warrant refreshes
/// like any draft.
pub fn refresh(
    repo: &Repository,
    alias: Option<&str>,
) -> Result<crate::diagnostic::Report, RepoError> {
    use crate::diagnostic::{Diagnostic, Report};
    let mut report = Report::default();
    for dir in repo.warrant_dirs()? {
        let Some(name) = dir.file_name().map(str::to_owned) else {
            continue;
        };
        if alias.is_some_and(|want| want != name) {
            continue;
        }
        let one = repo.load_warrant(&dir)?;
        if crate::check::resolution_binds(repo, &one) {
            if alias.is_some() {
                report.push(Diagnostic::error(
                    "pins.signed",
                    repo.relative(&dir.join("deliverables.toml")),
                    format!(
                        "{name} is resolved: its §56.2 record binds sha256(deliverables.toml). \
                         Moving a pin here would change what was accepted — \
                         `war correct {name} <D-id>` records why the file moved"
                    ),
                ));
            }
            continue;
        }
        let deliverables = repo.load_deliverables(&dir)?;
        let path = dir.join("deliverables.toml");
        let Ok(original) = std::fs::read_to_string(&path) else {
            continue;
        };
        let mut text = original.clone();
        let mut moved = Vec::new();
        for d in deliverables.records.iter().filter(|d| d.content_addressed) {
            let Some(provenance) = &d.provenance else {
                continue;
            };
            let recorded = provenance.content_digest.trim_start_matches("sha256:");
            let Ok(bytes) = std::fs::read(repo.root.join(&d.target_ref)) else {
                report.push(Diagnostic::warn(
                    "pins.unreadable",
                    repo.relative(&path),
                    format!(
                        "{name}: {} names {} and it cannot be read; its pin is left as recorded",
                        d.id, d.target_ref
                    ),
                ));
                continue;
            };
            let actual = openwarrant_compiler::sha256_hex(&bytes);
            if actual == recorded {
                continue;
            }
            // Textual, on the exact recorded digest: the file is hand-written
            // and hand-commented, and a round trip through the parser would
            // rewrite the operator's prose along with the digest.
            if !text.contains(recorded) {
                report.push(Diagnostic::error(
                    "pins.not-found",
                    repo.relative(&path),
                    format!(
                        "{name}: {} records sha256:{recorded} and that string is not in the file; \
                         nothing is rewritten",
                        d.id
                    ),
                ));
                continue;
            }
            text = text.replace(recorded, &actual);
            moved.push((
                d.id.clone(),
                d.target_ref.clone(),
                recorded.to_owned(),
                actual,
            ));
        }
        if moved.is_empty() {
            if alias.is_some() {
                report.push(Diagnostic::pass(
                    "pins.current",
                    format!("{name}: every content-addressed pin matches its bytes"),
                ));
            }
            continue;
        }
        std::fs::write(&path, &text).map_err(|source| RepoError::Io {
            context: format!("could not write {path}"),
            source,
        })?;
        for (id, target, before, after) in moved {
            report.push(Diagnostic::pass(
                "pins.refreshed",
                format!(
                    "{name}: {id} — {target} sha256:{} → sha256:{}",
                    &before[..12],
                    &after[..12]
                ),
            ));
        }
    }
    if report.diagnostics.is_empty() {
        report.push(Diagnostic::pass(
            "pins.current",
            "every draft Warrant's pins match their bytes".to_owned(),
        ));
    }
    report.note(
        "A refreshed pin records what a file IS, not that anyone approved it. Signing is what \
         makes a pin a promise.",
    );
    Ok(report)
}

// SPDX-License-Identifier: Apache-2.0
//! `war correct` — the correction act (OW-WAR-0064): the fifth two-half seam.
//!
//! An agent may EMIT a request naming a resolved Warrant's deliverable, the
//! digest its record pins, the digest the file has now, and who may sign. Only a
//! human's RESPONSE — ingested through the authority register, refused for every
//! agent regardless of what it claims (§27.2) — writes a correction record. The
//! record is appended beside `deliverables.toml`, never written into it: a
//! resolution binds `sha256(deliverables.toml)`, and a correction that edited the
//! manifest would stale the resolution it exists to leave standing.
//!
//! # What ingestion refuses, each before anything is written
//!
//! - a response for another Warrant or an unknown deliverable;
//! - a Warrant that is not resolved (regenerate the record instead — the
//!   ordinary remedy still applies before resolution);
//! - a file that has not drifted (there is nothing to correct);
//! - a signer the register does not know, knows as an agent, or who may not
//!   authorize (including the performer: `SelfAct`);
//! - `new_digest` that is not the file's bytes now — it corrects nothing;
//! - `superseded_digest` that is not the chain head — it supersedes nothing that
//!   happened;
//! - an empty reason, or an `effective_time` that is not RFC 3339;
//! - a record file that already exists: a second correction is a second file.
//!
//! # What `war check` then holds
//!
//! The journal carries the digest of each correction file as written. A record
//! edited afterwards, or a second correction applied as an edit to the first,
//! fails `correction.edited`; a record with no journal line is
//! `correction.unjournalled`. The superseded digest is never removed from
//! anything.

use camino::Utf8Path;
use openwarrant_core::WarUuid;
use openwarrant_core::authority::{ActorKind, ActorRole};
use openwarrant_core::correction::{
    CORRECTION_SCHEMA, ChainError, Correction, CorrectionKind, CorrectionRecord, chain_head,
};
use serde::{Deserialize, Serialize};

use crate::diagnostic::{Diagnostic, Report};
use crate::repo::{Loaded, RepoError, Repository};

pub const REQUEST_SCHEMA: &str = "oh.war/correction-request/v1";
pub const RESPONSE_SCHEMA: &str = "oh.war/correction-response/v1";

/// What an agent may emit. No recommendation, no suggested wording.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CorrectionRequest {
    pub schema: String,
    pub warrant: String,
    pub deliverable_id: String,
    pub target_ref: String,
    pub title: String,
    /// A correction is for a RESOLVED Warrant; before resolution, regenerate.
    pub resolved: bool,
    /// The digest `deliverables.toml` records.
    pub recorded_digest: String,
    /// The digest the chain of prior corrections resolves to.
    pub chain_head: String,
    /// The digest of the file's bytes now.
    pub current_digest: String,
    /// `current_digest != chain_head`.
    pub drift: bool,
    pub prior_corrections: u32,
    pub next_sequence: u32,
    /// Humans the register lets authorize on this Warrant. Agents never appear.
    pub eligible_correctors: Vec<String>,
}

/// What the human returns.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CorrectionResponse {
    pub schema: String,
    pub warrant: String,
    pub deliverable_id: String,
    /// Must equal the request's `chain_head` at ingest.
    pub superseded_digest: String,
    /// Must equal the file's bytes at ingest.
    pub new_digest: String,
    pub reason: String,
    pub kind: CorrectionKind,
    pub corrected_by: String,
    /// §27.4 — the role actually exercised.
    pub acting_role: String,
    pub effective_time: String,
    /// `tty` or `ssh` via `war sign`; absent when hand-written. Provenance only.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub signed_via: Option<String>,
}

fn sha256_of(path: &Utf8Path) -> Result<String, RepoError> {
    let bytes = std::fs::read(path).map_err(|source| RepoError::Io {
        context: format!("could not read {path}"),
        source,
    })?;
    Ok(format!(
        "sha256:{}",
        openwarrant_compiler::sha256_hex(&bytes)
    ))
}

/// What one deliverable's records say about it, computed once so every
/// caller agrees.
struct Standing {
    target_ref: String,
    title: String,
    recorded: String,
    corrections: Vec<Correction>,
}

fn standing(repo: &Repository, one: &Loaded, alias: &str, id: &str) -> Result<Standing, RepoError> {
    let deliverables = repo.load_deliverables(&one.dir)?;
    let Some(d) = deliverables.records.iter().find(|d| d.id == id) else {
        return Err(RepoError::Message(format!(
            "{alias}: no deliverable {id:?} in deliverables.toml"
        )));
    };
    let Some(p) = d.provenance.as_ref() else {
        return Err(RepoError::Message(format!(
            "{alias}: {id} carries no provenance, so there is no recorded digest to correct"
        )));
    };
    if !d.content_addressed {
        return Err(RepoError::Message(format!(
            "{alias}: {id} is not content-addressed; there is no pinned digest to correct"
        )));
    }
    Ok(Standing {
        target_ref: d.target_ref.clone(),
        title: d.title.clone(),
        recorded: p.content_digest.clone(),
        corrections: repo.load_corrections(&one.dir)?.for_deliverable(id),
    })
}

/// `war correct <alias> <deliverable-id>`: the request. Writes nothing.
pub fn request(repo: &Repository, alias: &str, id: &str) -> Result<CorrectionRequest, RepoError> {
    request_with(repo, alias, id, &crate::ownership::Ownership::index(repo)?)
}

/// [`request`] over an ownership index already built. A caller asking for
/// many requests in one pass (`war sign --list` asks for every
/// content-addressed deliverable of every resolved Warrant) builds the index
/// once; built per request, it re-loaded the whole corpus each time.
pub fn request_with(
    repo: &Repository,
    alias: &str,
    id: &str,
    ownership: &crate::ownership::Ownership,
) -> Result<CorrectionRequest, RepoError> {
    let dir = repo.warrant_dir(alias)?;
    let one = repo.load_warrant(&dir)?;
    let s = standing(repo, &one, alias, id)?;
    // OW-ADR-0021: a pin a later authorized Warrant governs is historical.
    // There is nothing to correct — the file moved under that Warrant's
    // authority, and this Warrant's delivery verifies at its own resolution.
    let authorized_at = repo
        .load_authorization(&dir)?
        .and_then(|a| a.revision.authorization.map(|x| x.effective_time));
    if let Some(owner) = ownership.newer_than(&s.target_ref, alias, authorized_at.as_deref()) {
        return Err(RepoError::Message(format!(
            "correction.historical: nothing to correct — {} is governed by {}/{} (authorized {}), \
             so {alias}/{id}'s pin is historical. It verifies at {alias}'s resolution, not against \
             the working tree (OW-ADR-0021). To move the file, work under {}",
            s.target_ref, owner.alias, owner.deliverable_id, owner.authorized_at, owner.alias
        )));
    }
    let head = chain_head(&s.recorded, &s.corrections)
        .map_err(|e| RepoError::Message(format!("{alias}/{id}: {e}")))?;
    let current = sha256_of(&repo.root.join(&s.target_ref))?;
    let resolved = repo.load_resolution(&dir)?.is_some();
    let register = repo.load_authority_register()?;
    let performer = repo.performer();
    let eligible = register
        .holders(ActorRole::Authorizer)
        .filter(|a| a.actor_kind == ActorKind::Human)
        .filter(|a| a.may_authorize(&performer).is_ok())
        .map(|a| a.actor.clone())
        .collect();
    let prior = u32::try_from(s.corrections.len()).unwrap_or(u32::MAX);
    Ok(CorrectionRequest {
        schema: REQUEST_SCHEMA.to_owned(),
        warrant: alias.to_owned(),
        deliverable_id: id.to_owned(),
        target_ref: s.target_ref,
        title: s.title,
        resolved,
        recorded_digest: s.recorded,
        drift: current != head,
        chain_head: head,
        current_digest: current,
        prior_corrections: prior,
        next_sequence: prior.saturating_add(1),
        eligible_correctors: eligible,
    })
}

fn load_response(path: &Utf8Path) -> Result<CorrectionResponse, RepoError> {
    let text = std::fs::read_to_string(path).map_err(|source| RepoError::Io {
        context: format!("could not read {path}"),
        source,
    })?;
    toml::from_str(&text).map_err(|e| RepoError::Message(format!("{path}: {e}")))
}

/// `war correct <alias> <deliverable-id> --response <file>`: ingest a human's
/// correction. Every refusal happens before anything is written.
pub fn ingest(
    repo: &Repository,
    alias: &str,
    id: &str,
    path: &Utf8Path,
) -> Result<Report, RepoError> {
    ingest_with(repo, alias, id, path, crate::sign::IngestMode::Record)
}

/// [`ingest`], or the same judgment with the write withheld (see
/// `sign::IngestMode`): every refusal runs, `DryRun` stops before the
/// correction file is created with `correction.would-record`.
pub fn ingest_with(
    repo: &Repository,
    alias: &str,
    id: &str,
    path: &Utf8Path,
    mode: crate::sign::IngestMode,
) -> Result<Report, RepoError> {
    let mut report = Report::default();
    let refuse = |report: &mut Report, rule: &'static str, why: String| {
        report.push(Diagnostic::error(rule, path.to_string(), why));
    };
    let response = load_response(path)?;
    if response.schema != RESPONSE_SCHEMA {
        refuse(
            &mut report,
            "correction.schema",
            format!("expected {RESPONSE_SCHEMA}, found {:?}", response.schema),
        );
        return Ok(report);
    }
    if response.warrant != alias || response.deliverable_id != id {
        refuse(
            &mut report,
            "correction.wrong-warrant",
            format!(
                "the response names {}/{}; ingesting for {alias}/{id}",
                response.warrant, response.deliverable_id
            ),
        );
        return Ok(report);
    }
    let dir = repo.warrant_dir(alias)?;
    let one = repo.load_warrant(&dir)?;
    let s = match standing(repo, &one, alias, id) {
        Ok(s) => s,
        Err(e) => {
            refuse(&mut report, "correction.unknown-deliverable", e.to_string());
            return Ok(report);
        }
    };
    if repo.load_resolution(&dir)?.is_none() {
        refuse(
            &mut report,
            "correction.not-resolved",
            format!(
                "{alias} is not resolved. A correction supersedes a pin a resolution holds; \
                 before resolution, regenerate deliverables.toml"
            ),
        );
        return Ok(report);
    }
    // One narrow exception, symmetric with the authorization and resolution
    // seams: the chain head is already recorded, this response repeats it
    // exactly, and no verified signature exists for it. Then this is the
    // signature that record was written without, the records are left alone,
    // and the refusals below — which would all fire, starting with
    // `correction.no-drift`, because the file already IS the corrected bytes —
    // do not apply.
    if let Some(recorded_head) = s.corrections.iter().max_by_key(|c| c.sequence).filter(|c| {
        c.superseded_digest == response.superseded_digest
            && c.new_digest == response.new_digest
            && c.reason == response.reason
            && c.kind == response.kind
            && !crate::authority_check::verify_excluding(
                repo,
                crate::authority_check::Act::Correct,
                &format!("{alias}.{id}"),
                c.authorized_by_ref.trim_start_matches("person://"),
                Some(&c.new_digest),
                Some(path),
            )
            .is_signed()
    }) {
        if let Some(v) = &one.validated {
            crate::journal_cmd::record(
                &dir,
                &v.uuid.to_string(),
                crate::journal_cmd::CORRECTION_SIGNATURE_RECORDED,
                &format!("person://{}", response.corrected_by),
                &format!(
                    "{{\"deliverable_id\":\"{id}\",\"sequence\":{},\"new_digest\":\"{}\",\"response\":\"{}\"}}",
                    recorded_head.sequence,
                    recorded_head.new_digest,
                    repo.relative(path)
                ),
            )?;
        }
        report.push(Diagnostic::warn(
            "correction.signature-supplied",
            path.to_string(),
            format!(
                "{alias}/{id}: correction {} was recorded without a verified signature; this \
                 signature supplies it. The correction record is unchanged",
                recorded_head.sequence
            ),
        ));
        return Ok(report);
    }
    let head = match chain_head(&s.recorded, &s.corrections) {
        Ok(h) => h,
        Err(e) => {
            refuse(
                &mut report,
                "correction.chain",
                format!("{alias}/{id}: {e}"),
            );
            return Ok(report);
        }
    };
    let current = sha256_of(&repo.root.join(&s.target_ref))?;
    if current == head {
        refuse(
            &mut report,
            "correction.no-drift",
            format!("{alias}/{id}: the file is at {head}; there is nothing to correct"),
        );
        return Ok(report);
    }
    if response.new_digest != current {
        refuse(
            &mut report,
            "correction.stale",
            format!(
                "{alias}/{id}: the response records new digest {} but the file is {current} — \
                 it corrects nothing",
                response.new_digest
            ),
        );
        return Ok(report);
    }
    if response.superseded_digest != head {
        refuse(
            &mut report,
            "correction.superseded-mismatch",
            format!(
                "{alias}/{id}: the response supersedes {} but the digest on record is {head} — \
                 it supersedes nothing that happened",
                response.superseded_digest
            ),
        );
        return Ok(report);
    }
    if response.reason.trim().is_empty() {
        refuse(
            &mut report,
            "correction.reason-empty",
            format!("{alias}/{id}: a correction with no reason is a change nobody can answer for"),
        );
        return Ok(report);
    }
    if let Err(e) = openwarrant_core::timestamp::validate_rfc3339_utc(&response.effective_time) {
        refuse(
            &mut report,
            "correction.effective-time",
            format!("{alias}/{id}: effective_time {}", e),
        );
        return Ok(report);
    }

    // The signer, through the register. Never through the response's claims.
    let register = repo.load_authority_register()?;
    let Some(assignment) = register.actor(&response.corrected_by) else {
        refuse(
            &mut report,
            "correction.unknown-actor",
            format!(
                "{:?} holds no role assignment in docs/authority/roles.toml",
                response.corrected_by
            ),
        );
        return Ok(report);
    };
    if assignment.actor_kind == ActorKind::Agent {
        refuse(
            &mut report,
            "correction.agent",
            format!(
                "{:?} is an agent. §27.2: an agent SHALL NOT correct a delivered artifact — a \
                 performer that could move its own pins would be judging its own work twice",
                response.corrected_by
            ),
        );
        return Ok(report);
    }
    if let Err(e) = assignment.may_authorize(&repo.performer()) {
        refuse(
            &mut report,
            "correction.not-permitted",
            format!("{}: {e}", response.corrected_by),
        );
        return Ok(report);
    }

    // Saturating, and the same arithmetic `request()` uses for `next_sequence`.
    let sequence = u32::try_from(s.corrections.len())
        .unwrap_or(u32::MAX)
        .saturating_add(1);
    let now = crate::gate_cmd::receipt::now_rfc3339_public();
    let correction = Correction {
        id: WarUuid::mint().to_string(),
        deliverable_id: id.to_owned(),
        target_ref: s.target_ref.clone(),
        sequence,
        superseded_digest: response.superseded_digest.clone(),
        new_digest: response.new_digest.clone(),
        reason: response.reason.clone(),
        kind: response.kind,
        authorized_by_ref: format!("person://{}", response.corrected_by),
        acting_role_ref: format!("role://{}", response.acting_role),
        effective_at: response.effective_time.clone(),
        recorded_at: now,
    };
    if let Err(e) = correction.validate() {
        refuse(
            &mut report,
            "correction.malformed",
            format!("{alias}/{id}: {e}"),
        );
        return Ok(report);
    }
    let record = CorrectionRecord {
        schema: CORRECTION_SCHEMA.to_owned(),
        warrant: alias.to_owned(),
        correction,
    };
    let cdir = dir.join("corrections");
    std::fs::create_dir_all(&cdir).map_err(|source| RepoError::Io {
        context: format!("could not create {cdir}"),
        source,
    })?;
    let out = cdir.join(format!("{id}-{sequence}.toml"));
    let body = toml::to_string_pretty(&record)
        .map_err(|e| RepoError::Message(format!("could not render the correction: {e}")))?;
    if mode == crate::sign::IngestMode::DryRun {
        if out.exists() {
            refuse(
                &mut report,
                "correction.exists",
                format!(
                    "{}: already exists; a correction is never overwritten",
                    repo.relative(&out)
                ),
            );
        } else {
            report.push(Diagnostic::pass(
                "correction.would-record",
                format!(
                    "{alias}/{id}: correction {sequence} ({} → {}) would be recorded. Not written",
                    &record.correction.superseded_digest[..19],
                    &record.correction.new_digest[..19]
                ),
            ));
        }
        return Ok(report);
    }
    // `create_new`: a second correction is a second file, never an overwrite.
    let mut f = match std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&out)
    {
        Ok(f) => f,
        Err(e) => {
            refuse(
                &mut report,
                "correction.exists",
                format!(
                    "{}: already exists ({e}); a correction is never overwritten",
                    repo.relative(&out)
                ),
            );
            return Ok(report);
        }
    };
    use std::io::Write as _;
    f.write_all(body.as_bytes())
        .map_err(|source| RepoError::Io {
            context: format!("could not write {out}"),
            source,
        })?;
    drop(f);
    let record_digest = sha256_of(&out)?;
    if let Some(v) = &one.validated {
        crate::journal_cmd::record(
            &dir,
            &v.uuid.to_string(),
            crate::journal_cmd::CORRECTION_RECORDED,
            &format!("person://{}", response.corrected_by),
            // Built by the serializer, not by hand: the digests are validated
            // hex today, but a payload that could go malformed on a future
            // field is a witness that could go silent.
            &serde_json::json!({
                "deliverable": id,
                "sequence": sequence,
                "superseded": response.superseded_digest,
                "new": response.new_digest,
                "record_digest": record_digest,
                "channel": response.signed_via.as_deref().unwrap_or("file"),
            })
            .to_string(),
        )?;
    }
    report.push(Diagnostic::pass(
        "correction.recorded",
        format!(
            "{alias}/{id}: correction {sequence} by {} — {} superseded by {} → {}",
            response.corrected_by,
            response.superseded_digest,
            response.new_digest,
            repo.relative(&out)
        ),
    ));
    Ok(report)
}

/// The head digest and the corrections behind it, for `war check`'s digest
/// comparison. `None` when the deliverable has no recorded digest to chain from.
pub fn head_for(
    corrections: &crate::repo::CorrectionSet,
    deliverable_id: &str,
    recorded: &str,
) -> (Vec<Correction>, Result<String, ChainError>) {
    let list = corrections.for_deliverable(deliverable_id);
    let head = chain_head(recorded, &list);
    (list, head)
}

/// Structural checks on the records themselves: parse, warrant, actor kind,
/// and the journal witness. The digest chain is checked where the digests are
/// compared (`check_deliverable_digests`), so the two cannot disagree.
pub fn check(repo: &Repository, one: &Loaded, alias: &str, report: &mut Report) {
    let set = match repo.load_corrections(&one.dir) {
        Ok(s) => s,
        Err(e) => {
            report.push(Diagnostic::error(
                "correction.unreadable",
                repo.relative(&one.dir.join("corrections")),
                format!("{alias}: {e}"),
            ));
            return;
        }
    };
    for (path, why) in &set.failures {
        report.push(Diagnostic::error(
            "correction.malformed",
            path.clone(),
            format!("{alias}: {why} — an unreadable correction is not an absent one"),
        ));
    }
    if set.records.is_empty() {
        return;
    }
    let register = repo.load_authority_register().ok();
    let journal = crate::journal_cmd::load(&one.dir).ok();
    for (path, rec) in &set.records {
        let c = &rec.correction;
        if rec.schema != CORRECTION_SCHEMA {
            report.push(Diagnostic::error(
                "correction.malformed",
                path.clone(),
                format!(
                    "{alias}: schema {:?}, expected {CORRECTION_SCHEMA}",
                    rec.schema
                ),
            ));
            continue;
        }
        if let Err(e) = c.validate() {
            report.push(Diagnostic::error(
                "correction.malformed",
                path.clone(),
                format!("{alias}: {e}"),
            ));
            continue;
        }
        if rec.warrant != alias {
            report.push(Diagnostic::error(
                "correction.wrong-warrant",
                path.clone(),
                format!("{alias}: the record names {:?}", rec.warrant),
            ));
            continue;
        }
        let actor = c.authorized_by_ref.trim_start_matches("person://");
        match register.as_ref().and_then(|r| r.actor(actor)) {
            None => report.push(Diagnostic::error(
                "correction.unknown-actor",
                path.clone(),
                format!("{alias}: {actor:?} holds no role assignment in docs/authority/roles.toml"),
            )),
            Some(a) if a.actor_kind == ActorKind::Agent => report.push(Diagnostic::error(
                "correction.agent",
                path.clone(),
                format!("{alias}: {actor:?} is an agent; §27.2"),
            )),
            Some(_) => {}
        }
        // The journal witness: the file as written, or not this file.
        let witnessed = journal.as_ref().and_then(|j| {
            j.events.iter().find_map(|e| {
                if e.event_type != crate::journal_cmd::CORRECTION_RECORDED {
                    return None;
                }
                let v: serde_json::Value = serde_json::from_str(&e.payload).ok()?;
                (v.get("deliverable")?.as_str()? == c.deliverable_id
                    && v.get("sequence")?.as_u64()? == u64::from(c.sequence))
                .then(|| v.get("record_digest")?.as_str().map(str::to_owned))
                .flatten()
            })
        });
        match witnessed {
            None => report.push(Diagnostic::error(
                "correction.unjournalled",
                path.clone(),
                format!(
                    "{alias}: no `correction.recorded` journal event names {} sequence {}; a \
                     correction nobody ingested is a file, not an act",
                    c.deliverable_id, c.sequence
                ),
            )),
            Some(expected) => match sha256_of(&repo.root.join(path)) {
                Ok(actual) if actual == expected => {}
                Ok(actual) => report.push(Diagnostic::error(
                    "correction.edited",
                    path.clone(),
                    format!(
                        "{alias}: the journal witnessed this record as {expected} and it is now \
                         {actual} — edited after authorization. A second correction is a second \
                         file ({}-{}.toml), never an edit",
                        c.deliverable_id,
                        c.sequence + 1
                    ),
                )),
                Err(e) => report.push(Diagnostic::error(
                    "correction.unreadable",
                    path.clone(),
                    format!("{alias}: {e}"),
                )),
            },
        }
    }
}

// SPDX-License-Identifier: Apache-2.0
//! §56.2 resolution: the third two-half seam.
//!
//! `war authorize` (§28.4) and `war sas accept` (§101.2) established the shape:
//! an agent may EMIT a request that names exactly what a human would be
//! signing, and only a human's RESPONSE — ingested through the authority
//! register, refused for every agent regardless of what it claims — writes a
//! record. Resolution is the act §27.2 names most plainly ("an agent SHALL NOT
//! resolve a delivery"), and until this module existed `war resolve` could only
//! report whether the thirteen were met; nothing could record that they were.
//!
//! # What ingestion refuses
//!
//! - any of §56.1's thirteen unmet, re-evaluated at ingest, never trusted from
//!   the request;
//! - a `contract_digest` that is not the one the Warrant compiles to now;
//! - a resolver the register does not know, or knows as an agent, or who does
//!   not hold `resolver`, or who is the performer (`may_resolve`);
//! - `common_outcome = satisfied` when §38.6 says the obligations are not
//!   established — a resolver may close a Warrant, and may not close it as
//!   *satisfied* over the verifiers' heads;
//! - `falsified` on a profile with no falsifiable claim (§56.3, via
//!   [`Resolution::validate`]);
//! - a Warrant that already carries a resolution. §56 has dispute and annulment
//!   for changing one; overwriting is neither.
//!
//! # What the record binds
//!
//! The contract digest, the assurance-case snapshot digest (the compiled
//! `assurance_case` section under `DigestDomain::AssuranceCaseSnapshot`), the
//! artifact manifest digest (the bytes of `deliverables.toml`), and the
//! repository-relative paths of every admissible gate run, judgment and residual
//! risk it relied on. When the contract later moves, `war check` reports the
//! resolution as stale rather than letting a record about revision N read as a
//! record about revision N+1.

use camino::Utf8Path;
use openwarrant_compiler::canonical::sha256_digest;
use openwarrant_compiler::digest::{DigestDomain, sha256_hex};
use openwarrant_core::WarUuid;
use openwarrant_core::authority::{ActorKind, ActorRole, PolicyResolutionContext};
use openwarrant_core::resolution::{CommonOutcome, Resolution};
use serde::{Deserialize, Serialize};

use crate::diagnostic::{Diagnostic, Report};
use crate::repo::{RepoError, Repository};
use crate::resolve::{assess, declared_obligations};

pub const REQUEST_SCHEMA: &str = "oh.war/resolution-request/v1";
pub const RESPONSE_SCHEMA: &str = "oh.war/resolution-response/v1";
pub const RECORD_SCHEMA: &str = "oh.war/resolution/v1";

/// What an agent may emit: the state of the thirteen, what a signature would
/// bind, and who may sign. No recommendation, no suggested wording.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ResolutionRequest {
    pub schema: String,
    pub warrant: String,
    pub title: String,
    pub contract_digest: String,
    pub contract_revision: u32,
    /// All thirteen met right now. When false, `unmet` says which.
    pub requirements_met: bool,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub unmet: Vec<String>,
    /// §38.6, beside the thirteen: `None` when no obligation is declared.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub would_resolve_satisfied: Option<bool>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub established: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub unestablished: Vec<String>,
    /// The outcomes a signature may name, given §38.6. `satisfied` appears only
    /// when every obligation is established.
    pub permitted_outcomes: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub gate_run_refs: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub judgment_refs: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub residual_risk_refs: Vec<String>,
    /// Humans the register lets resolve this Warrant. Agents never appear.
    pub eligible_resolvers: Vec<String>,
}

/// What the resolver returns.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ResolutionResponse {
    pub schema: String,
    pub warrant: String,
    /// Must equal the digest the Warrant compiles to at ingest.
    pub contract_digest: String,
    pub resolved_by: String,
    /// §27.4 — the role actually exercised.
    pub acting_role: String,
    pub common_outcome: CommonOutcome,
    /// The profile's own word for it (§56.2's example: `delivered`).
    pub profile_outcome: String,
    /// §56.2 — what accepting asserts. Not optional.
    pub meaning: String,
    pub effective_time: String,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// Where the delivered bytes were when the resolution was recorded
/// (OW-ADR-0021, §56.2 `locator`). Optional: records made before this
/// existed have none and read as UNKNOWN when history is asked for, which is
/// the honest answer rather than a commit guessed from the log.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Locator {
    /// `git rev-parse HEAD` at ingest, forty lowercase hex.
    pub commit_sha: String,
    /// Whether every declared deliverable was committed at that moment. A
    /// dirty path means the bytes the resolution bound are NOT the ones at
    /// `commit_sha`, and `paths_dirty` says which.
    pub worktree_clean: bool,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub paths_dirty: Vec<String>,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// The persisted record: `docs/warrants/<alias>/resolution.toml`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ResolutionRecord {
    pub schema: String,
    pub warrant: String,
    pub resolution: Resolution,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub locator: Option<Locator>,
}

/// The commit the tree is at, and which of `paths` are not committed there.
/// `None` when git cannot answer — a resolution outside a repository records
/// no locator rather than a made-up one.
fn locate(root: &camino::Utf8Path, paths: &[String]) -> Option<Locator> {
    let head = std::process::Command::new("git")
        .args(["rev-parse", "HEAD"])
        .current_dir(root)
        .output()
        .ok()
        .filter(|o| o.status.success())?;
    let commit_sha = String::from_utf8_lossy(&head.stdout).trim().to_owned();
    if commit_sha.len() != 40
        || !commit_sha
            .bytes()
            .all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase())
    {
        return None;
    }
    let mut args = vec![
        "status".to_owned(),
        "--porcelain".to_owned(),
        "--".to_owned(),
    ];
    args.extend(paths.iter().cloned());
    let status = std::process::Command::new("git")
        .args(&args)
        .current_dir(root)
        .output()
        .ok()
        .filter(|o| o.status.success())?;
    let paths_dirty: Vec<String> = String::from_utf8_lossy(&status.stdout)
        .lines()
        .filter_map(|l| l.get(3..).map(str::to_owned))
        .collect();
    Some(Locator {
        commit_sha,
        worktree_clean: paths_dirty.is_empty(),
        paths_dirty,
    })
}

fn load_response(path: &Utf8Path) -> Result<ResolutionResponse, RepoError> {
    let text = std::fs::read_to_string(path).map_err(|source| RepoError::Io {
        context: format!("could not read {path}"),
        source,
    })?;
    toml::from_str(&text).map_err(|e| RepoError::Message(format!("{path}: {e}")))
}

/// Which outcomes §38.6 leaves open.
fn permitted_outcomes(would_satisfy: Option<bool>) -> Vec<String> {
    let mut v = vec![];
    if would_satisfy == Some(true) {
        v.push(CommonOutcome::Satisfied.to_string());
    }
    v.push(CommonOutcome::NotSatisfied.to_string());
    v.push(CommonOutcome::Cancelled.to_string());
    v.push(CommonOutcome::Blocked.to_string());
    v
}

struct Bound {
    contract_digest: String,
    contract_revision: u32,
    assurance_case_snapshot_digest: String,
    artifact_manifest_digest: String,
}

fn bind(alias: &str, one: &crate::repo::Loaded) -> Result<Bound, RepoError> {
    let (Some(basis), Some(validated)) = (&one.basis, &one.validated) else {
        return Err(RepoError::Message(format!(
            "{alias}: the manifest did not validate, so there is no contract to resolve"
        )));
    };
    let ir = openwarrant_compiler::lower(basis, validated)
        .map_err(|e| RepoError::Message(format!("{alias}: could not compile contract: {e}")))?;
    let contract_digest = ir
        .contract_digest()
        .map_err(|e| RepoError::Message(format!("{alias}: could not digest contract: {e}")))?;
    // §56.2's assurance-case snapshot. The IR carries no `assurance_case`
    // section today (the compiler lowers it as `None`), so the snapshot is
    // taken over the assurance ATOMS as compiled: (ordinal, role, sha256 of
    // bytes) for each, under the snapshot domain. A record with no assurance
    // atom to bind is refused — "absent" would be a digest of nothing that
    // reads like a digest of something.
    let snapshot = match &ir.assurance_case {
        Some(a) => sha256_digest(DigestDomain::AssuranceCaseSnapshot, a)
            .map_err(|e| RepoError::Message(format!("{alias}: assurance snapshot: {e}")))?,
        None => {
            let atoms: Vec<(u32, String, String)> = basis
                .atoms
                .iter()
                .filter(|a| a.role == "assurance")
                .map(|a| (a.ordinal, a.role.clone(), sha256_hex(&a.bytes)))
                .collect();
            if atoms.is_empty() {
                return Err(RepoError::Message(format!(
                    "{alias}: no assurance atom to snapshot; §56.2 binds the assurance case and there is none"
                )));
            }
            sha256_digest(DigestDomain::AssuranceCaseSnapshot, &atoms)
                .map_err(|e| RepoError::Message(format!("{alias}: assurance snapshot: {e}")))?
        }
    };
    let snapshot = format!("sha256:{snapshot}");
    let manifest_path = one.dir.join("deliverables.toml");
    let artifact_manifest_digest = std::fs::read(&manifest_path)
        .map(|b| format!("sha256:{}", sha256_hex(&b)))
        .unwrap_or_else(|_| "absent".to_owned());
    Ok(Bound {
        contract_digest,
        contract_revision: ir.contract_revision,
        assurance_case_snapshot_digest: snapshot,
        artifact_manifest_digest,
    })
}

/// `war resolve <alias>` with no flag: the request.
pub fn request(repo: &Repository, alias: &str) -> Result<ResolutionRequest, RepoError> {
    let dir = repo.warrant_dir(alias)?;
    let one = repo.load_warrant(&dir)?;
    let bound = bind(alias, &one)?;
    let a = assess(repo, &one)?;
    let register = repo.load_authority_register()?;
    let performer = repo.performer();
    let declared = declared_obligations(&one);
    let assumptions = repo.load_rationale(&dir)?;
    let context = PolicyResolutionContext {
        policy_allows: repo.config.policy.allow_automated_resolution,
        assurance_level: &one
            .validated
            .as_ref()
            .map(|v| v.assurance_level.to_string())
            .unwrap_or_else(|| "basic".to_owned()),
        all_obligations_mechanical: declared.is_empty(),
        residual_risk_judgment_required: assumptions
            .as_deref()
            .is_none_or(|a| !crate::authorize::residual_risks_in(a).is_empty()),
    };
    let eligible_resolvers: Vec<String> = register
        .holders(ActorRole::Resolver)
        .filter(|r| r.actor_kind == ActorKind::Human)
        .filter(|r| {
            r.may_resolve(
                &performer,
                PolicyResolutionContext {
                    assurance_level: context.assurance_level,
                    ..context
                },
            )
            .is_ok()
        })
        .map(|r| r.actor.clone())
        .collect();
    let evidence = crate::evidence::load(repo, &dir)?;
    let gate_run_refs = crate::evidence::admissible_runs(&evidence, Some(&bound.contract_digest))
        .iter()
        .filter_map(|run| {
            evidence
                .iter()
                .find(|e| e.run.id == run.id && e.run.gate == run.gate)
                .map(|e| repo.relative(&e.receipt_path))
        })
        .collect();
    let judgment_refs = repo
        .load_judgments(&dir)?
        .iter()
        .map(|j| format!("judgment://{}", j.id))
        .collect();
    let residual_risk_refs = assumptions
        .as_deref()
        .map(|a| {
            crate::authorize::residual_risks_in(a)
                .iter()
                .map(|r| format!("assumption://{}", r.assumption_id))
                .collect()
        })
        .unwrap_or_default();
    let unmet: Vec<String> = a.checks.unmet().into_iter().map(str::to_owned).collect();
    Ok(ResolutionRequest {
        schema: REQUEST_SCHEMA.to_owned(),
        warrant: alias.to_owned(),
        title: one
            .validated
            .as_ref()
            .map(|v| v.raw.title.clone())
            .unwrap_or_default(),
        contract_digest: bound.contract_digest,
        contract_revision: bound.contract_revision,
        requirements_met: unmet.is_empty(),
        unmet,
        would_resolve_satisfied: a.would_resolve_satisfied,
        established: a.established,
        unestablished: a.unestablished,
        permitted_outcomes: permitted_outcomes(a.would_resolve_satisfied),
        gate_run_refs,
        judgment_refs,
        residual_risk_refs,
        eligible_resolvers,
    })
}

/// `war resolve <alias> --response <file>`: ingest a human's resolution.
pub fn ingest(repo: &Repository, alias: &str, path: &Utf8Path) -> Result<Report, RepoError> {
    ingest_with(repo, alias, path, crate::sign::IngestMode::Record)
}

/// [`ingest`], or the same judgment with the write withheld (see
/// `sign::IngestMode`). Every §56.1 refusal runs either way; `DryRun` stops
/// at the record write with `resolution.would-record`.
pub fn ingest_with(
    repo: &Repository,
    alias: &str,
    path: &Utf8Path,
    mode: crate::sign::IngestMode,
) -> Result<Report, RepoError> {
    let mut report = Report::default();
    let refuse = |report: &mut Report, rule: &'static str, why: String| {
        report.push(Diagnostic::error(rule, path.to_string(), why));
    };
    let response = load_response(path)?;
    if response.schema != RESPONSE_SCHEMA {
        refuse(
            &mut report,
            "resolution.schema",
            format!(
                "{alias}: expected {RESPONSE_SCHEMA}, found {:?}",
                response.schema
            ),
        );
        return Ok(report);
    }
    if response.warrant != alias {
        refuse(
            &mut report,
            "resolution.wrong-warrant",
            format!(
                "the response names {:?}; ingesting for {alias}",
                response.warrant
            ),
        );
        return Ok(report);
    }

    let dir = repo.warrant_dir(alias)?;
    // OW-WAR-0121: the record this act writes, as it is before the act reads
    // anything else. The write refuses if it moved since (`storage.prestate-
    // moved`); a symlink in its place is refused now (`storage.symlink-target`).
    let out = dir.join("resolution.toml");
    let before = match crate::compile::atomic::prestate(&out) {
        Ok(b) => b,
        Err(refused) => {
            report.push(refused.diagnostic());
            return Ok(report);
        }
    };
    if let Err(e) = openwarrant_core::timestamp::validate_rfc3339_utc(&response.effective_time) {
        refuse(
            &mut report,
            "resolution.effective-time",
            format!(
                "{alias}: effective_time {:?} is not an RFC 3339 UTC timestamp ({e}); a \
                 record dated \"soon\" cannot be ordered against any other",
                response.effective_time
            ),
        );
        return Ok(report);
    }
    // OW-WAR-0137: on a Warrant whose authorizer signed an assignment, only
    // the assigned resolver's response is taken — whether it records a
    // resolution or supplies the signature a recorded one lacks — and an
    // assignment that is not the one signed lets nobody resolve. Checked
    // before either path writes anything. Unassigned Warrants skip this.
    match crate::authorize::assignment_standing(repo, &dir)?
        .for_act(crate::authorize::assignment::Act::Resolve)
    {
        Ok(None) => {}
        Ok(Some(assigned)) if assigned.contains(&response.resolved_by) => {}
        Ok(Some(assigned)) => {
            refuse(
                &mut report,
                "resolution.not-assigned",
                format!(
                    "{alias}: {:?} is not the assigned resolver; the assignment the authorizer \
                     signed names {}. An assignment narrows who may resolve",
                    response.resolved_by,
                    assigned.join(", ")
                ),
            );
            return Ok(report);
        }
        Err(finding) => {
            refuse(
                &mut report,
                finding.rule,
                format!("{alias}: {}", finding.message),
            );
            return Ok(report);
        }
    }
    if dir.join("resolution.toml").is_file() {
        // One narrow exception to "a resolution is written once": the recorded
        // resolution binds this contract, says exactly what this response says,
        // and carries no verified signature. Then this response is not a second
        // resolution — it is the signature the first was recorded without, and
        // the record is left byte-for-byte alone. Anything else is refused.
        let existing = repo.load_resolution(&dir)?;
        let supplies_signature = existing.as_ref().is_some_and(|r| {
            r.resolution.contract_digest == response.contract_digest
                && r.resolution.common_outcome == response.common_outcome
                && r.resolution.profile_outcome == response.profile_outcome
                && !crate::authority_check::verify_excluding(
                    repo,
                    crate::authority_check::Act::Resolve,
                    alias,
                    r.resolution.resolved_by_ref.trim_start_matches("person://"),
                    Some(&r.resolution.contract_digest),
                    Some(path),
                )
                .is_signed()
        });
        if supplies_signature {
            // The signature belongs in the journal even though the record does
            // not move: §66's point is that every material act leaves a trace.
            if let Ok(one) = repo.load_warrant(&dir)
                && let Some(v) = &one.validated
            {
                crate::journal_cmd::record(
                    &dir,
                    &v.uuid.to_string(),
                    crate::journal_cmd::RESOLUTION_SIGNATURE_RECORDED,
                    &format!("person://{}", response.resolved_by),
                    &format!(
                        "{{\"common_outcome\":\"{}\",\"contract_digest\":\"{}\",\"response\":\"{}\"}}",
                        response.common_outcome,
                        response.contract_digest,
                        repo.relative(path)
                    ),
                )?;
            }
            report.push(Diagnostic::warn(
                "resolution.signature-supplied",
                path.to_string(),
                format!(
                    "{alias}: the recorded resolution carried no verified signature; this \
                     signature supplies it. resolution.toml is unchanged — the outcome, the \
                     evidence refs and the snapshot digests are the ones already recorded"
                ),
            ));
            return Ok(report);
        }
        refuse(
            &mut report,
            "resolution.exists",
            format!(
                "{alias} already carries a resolution. §56.4 dispute and §56.5 annulment change one; \
             overwriting is neither"
            ),
        );
        return Ok(report);
    }
    let one = repo.load_warrant(&dir)?;
    let bound = bind(alias, &one)?;
    if response.contract_digest != bound.contract_digest {
        refuse(
            &mut report,
            "resolution.stale-digest",
            format!(
                "{alias}: the response resolves contract {} and the Warrant now compiles to {} — \
             §56.1 asks for the EXACT authorized revision",
                response.contract_digest, bound.contract_digest
            ),
        );
        return Ok(report);
    }

    // OW-ADR-0029: a Warrant authorized through a standing class is resolved
    // by a human, always. §27.3's policy-service path is refused by name,
    // before anything else about the resolution is judged, so the refusal
    // does not depend on whether the thirteen happen to be met.
    if let Some(why) = crate::resolve::standing_needs_human(repo, &dir, &response.resolved_by)? {
        refuse(&mut report, "resolve.standing-needs-human", why);
        return Ok(report);
    }

    let a = assess(repo, &one)?;
    let unmet = a.checks.unmet();
    if !unmet.is_empty() {
        refuse(
            &mut report,
            "resolution.requirements-unmet",
            format!(
                "{alias}: {} of 13 §56.1 requirements unmet: {}",
                unmet.len(),
                unmet.join("; ")
            ),
        );
        return Ok(report);
    }

    // The resolver, through the register. Never through the response's claims.
    let register = repo.load_authority_register()?;
    let Some(assignment) = register.actor(&response.resolved_by) else {
        refuse(
            &mut report,
            "resolution.unknown-resolver",
            format!(
                "{:?} holds no role assignment in docs/authority/roles.toml",
                response.resolved_by
            ),
        );
        return Ok(report);
    };
    if assignment.actor_kind == ActorKind::Agent {
        refuse(
            &mut report,
            "resolution.agent",
            format!(
                "{:?} is an agent. §27.2: an agent SHALL NOT resolve a delivery",
                response.resolved_by
            ),
        );
        return Ok(report);
    }
    let declared = declared_obligations(&one);
    let assumptions = repo.load_rationale(&dir)?;
    let assurance = one
        .validated
        .as_ref()
        .map(|v| v.assurance_level.to_string())
        .unwrap_or_else(|| "basic".to_owned());
    if let Err(e) = assignment.may_resolve(
        &repo.performer(),
        PolicyResolutionContext {
            policy_allows: repo.config.policy.allow_automated_resolution,
            assurance_level: &assurance,
            all_obligations_mechanical: declared.is_empty(),
            residual_risk_judgment_required: assumptions
                .as_deref()
                .is_none_or(|a| !crate::authorize::residual_risks_in(a).is_empty()),
        },
    ) {
        refuse(
            &mut report,
            "resolution.not-permitted",
            format!("{}: {e}", response.resolved_by),
        );
        return Ok(report);
    }
    if !assignment.holds(ActorRole::Resolver) {
        refuse(
            &mut report,
            "resolution.not-permitted",
            format!("{:?} does not hold the resolver role", response.resolved_by),
        );
        return Ok(report);
    }

    // §38.6 bounds the outcome a signature may name.
    if response.common_outcome == CommonOutcome::Satisfied
        && a.would_resolve_satisfied != Some(true)
    {
        refuse(
            &mut report,
            "resolution.outcome-unsupported",
            format!(
                "{alias}: `satisfied` needs every declared obligation established by an admissible \
             verification, and {} are not: {}",
                a.unestablished.len(),
                if a.unestablished.is_empty() {
                    "none declared".to_owned()
                } else {
                    a.unestablished.join(", ")
                }
            ),
        );
        return Ok(report);
    }
    if response.meaning.trim().is_empty() {
        refuse(
            &mut report,
            "resolution.no-meaning",
            format!("{alias}: §56.2 — a resolution with no stated meaning is not a resolution"),
        );
        return Ok(report);
    }

    let req = request(repo, alias)?;
    let resolution = Resolution {
        id: WarUuid::mint().to_string(),
        common_outcome: response.common_outcome,
        profile_outcome: response.profile_outcome.clone(),
        contract_revision: bound.contract_revision,
        contract_digest: bound.contract_digest.clone(),
        assurance_case_snapshot_digest: bound.assurance_case_snapshot_digest,
        artifact_manifest_digest: bound.artifact_manifest_digest,
        gate_run_refs: req.gate_run_refs,
        judgment_refs: req.judgment_refs,
        residual_risk_refs: req.residual_risk_refs,
        resolved_by_ref: format!("person://{}", response.resolved_by),
        acting_role_ref: format!(
            "role-assignment://{}/{}",
            response.resolved_by, response.acting_role
        ),
        meaning: response.meaning.clone(),
        effective_at: response.effective_time.clone(),
        recorded_at: crate::gate_cmd::receipt::now_rfc3339_public(),
        standing: openwarrant_core::ResolutionStanding::Valid,
    };
    let falsifiable = one
        .validated
        .as_ref()
        .is_some_and(|v| matches!(v.profile.as_str(), "experiment" | "feasibility"));
    if let Err(e) = resolution.validate(a.checks, falsifiable) {
        refuse(&mut report, "resolution.invalid", format!("{alias}: {e}"));
        return Ok(report);
    }

    let declared: Vec<String> = repo
        .load_deliverables(&dir)?
        .records
        .iter()
        .map(|d| d.target_ref.clone())
        .collect();
    let record = ResolutionRecord {
        schema: RECORD_SCHEMA.to_owned(),
        warrant: alias.to_owned(),
        resolution,
        locator: locate(&repo.root, &declared),
    };
    if mode == crate::sign::IngestMode::DryRun {
        report.push(Diagnostic::pass(
            "resolution.would-record",
            format!(
                "{alias}: {} would be recorded against contract {}; the thirteen hold. Not written",
                record.resolution.common_outcome, record.resolution.contract_digest
            ),
        ));
        return Ok(report);
    }
    let body = toml::to_string_pretty(&record)
        .map_err(|e| RepoError::Message(format!("could not render the resolution: {e}")))?;
    if let Err(refused) = crate::compile::atomic::write_if(&out, body, &before) {
        report.push(refused.diagnostic());
        return Ok(report);
    }
    if let Some(v) = &one.validated {
        crate::journal_cmd::record(
            &dir,
            &v.uuid.to_string(),
            crate::journal_cmd::RESOLUTION_RECORDED,
            &format!("person://{}", response.resolved_by),
            &format!(
                "{{\"common_outcome\":\"{}\",\"contract_digest\":\"{}\"}}",
                response.common_outcome, bound.contract_digest
            ),
        )?;
    }
    report.push(Diagnostic::pass(
        "resolution.recorded",
        format!(
            "{alias}: {} · {} by {} acting as {} → {}",
            response.common_outcome,
            response.profile_outcome,
            response.resolved_by,
            response.acting_role,
            repo.relative(&out)
        ),
    ));
    Ok(report)
}

/// `war check` rules for a recorded resolution.
pub fn check(
    repo: &Repository,
    warrant_dir: &Utf8Path,
    alias: &str,
    current_contract_digest: Option<&str>,
    report: &mut Report,
) {
    check_disputes(repo, warrant_dir, alias, report);
    let path = warrant_dir.join("resolution.toml");
    match repo.load_resolution(warrant_dir) {
        Ok(None) => {}
        Ok(Some(r)) => {
            if r.warrant != alias {
                report.push(Diagnostic::error(
                    "resolution.wrong-warrant",
                    repo.relative(&path),
                    format!("{alias}: the record names {:?}", r.warrant),
                ));
            } else if Some(r.resolution.contract_digest.as_str()) == current_contract_digest {
                report.push(Diagnostic::pass(
                    "resolution.recorded",
                    format!(
                        "{alias}: {} · resolved by {} at {}",
                        r.resolution.common_outcome,
                        r.resolution.resolved_by_ref,
                        r.resolution.effective_at
                    ),
                ));
            } else {
                report.push(Diagnostic::error(
                    "resolution.stale",
                    repo.relative(&path),
                    format!(
                        "{alias}: the resolution binds contract {} and the Warrant now compiles to {} — \
                         a resolution of an earlier revision is not a resolution of this one. §45: \
                         dispute or annul it; do not edit around it",
                        r.resolution.contract_digest,
                        current_contract_digest.unwrap_or("nothing (the manifest does not validate)")
                    ),
                ));
            }
        }
        Err(e) => report.push(Diagnostic::error(
            "resolution.malformed",
            repo.relative(&path),
            format!("{alias}: {e} — an unreadable resolution is not an absent one"),
        )),
    }
}

/// OW-WAR-0136 — standing read from disputes, never written into the record.
///
/// A resolution with an open dispute is `resolution.disputed`: the record is
/// true history and is not relied on while the dispute stands. A dispute
/// counts only when the invalidation that wrote it counts — its response
/// signed by a human holding `resolver` who is not the performer
/// ([`crate::invalidation::counted_record`]) — and lists this file at the
/// digest it has now. Anything else is an error on the dispute, and the
/// resolution's standing is what the resolution says: an unsigned
/// invalidation never counts.
pub fn check_disputes(repo: &Repository, warrant_dir: &Utf8Path, alias: &str, report: &mut Report) {
    let disputes = crate::invalidation::load_disputes(warrant_dir);
    if disputes.is_empty() {
        return;
    }
    let resolution = repo.load_resolution(warrant_dir).ok().flatten();
    for (path, parsed) in disputes {
        let rel = repo.relative(&path);
        let record = match parsed {
            Ok(r) => r,
            Err(e) => {
                report.push(Diagnostic::error(
                    "resolution.dispute-malformed",
                    rel,
                    format!("{alias}: {e} — an unreadable dispute is not an absent one"),
                ));
                continue;
            }
        };
        if record.schema != crate::invalidation::DISPUTE_SCHEMA
            || record.warrant != alias
            || record.status != crate::invalidation::OPEN
        {
            report.push(Diagnostic::error(
                "resolution.dispute-malformed",
                rel,
                format!(
                    "{alias}: a dispute is {} of this Warrant with status {:?}; this one is {:?} \
                     of {:?} with status {:?}. Closing a dispute is a later act, never an edit",
                    crate::invalidation::DISPUTE_SCHEMA,
                    crate::invalidation::OPEN,
                    record.schema,
                    record.warrant,
                    record.status
                ),
            ));
            continue;
        }
        if let Err(e) = record.dispute.validate() {
            report.push(Diagnostic::error(
                "resolution.dispute-malformed",
                rel,
                format!("{alias}: §56.4 — {e}"),
            ));
            continue;
        }
        let Some(resolution) = &resolution else {
            report.push(Diagnostic::error(
                "resolution.dispute-orphan",
                rel,
                format!("{alias}: disputes a resolution, and {alias} has none"),
            ));
            continue;
        };
        if record.dispute.challenged_resolution != resolution.resolution.id {
            report.push(Diagnostic::error(
                "resolution.dispute-orphan",
                rel,
                format!(
                    "{alias}: disputes {} and the resolution on record is {}",
                    record.dispute.challenged_resolution, resolution.resolution.id
                ),
            ));
            continue;
        }
        let invalidation = match crate::invalidation::counted_record(repo, &record.gate) {
            None => Err(format!(
                "it names {} and no invalidation of {} is recorded",
                record.invalidation, record.gate
            )),
            Some(r) => r,
        };
        let invalidation = match invalidation {
            Ok(i) => i,
            Err(why) => {
                report.push(Diagnostic::error(
                    "resolution.dispute-unsigned",
                    rel,
                    format!(
                        "{alias}: this dispute does not count, and the resolution stands as \
                         recorded — {why}"
                    ),
                ));
                continue;
            }
        };
        let now = std::fs::read(&path)
            .map(|b| format!("sha256:{}", openwarrant_compiler::sha256_hex(&b)))
            .unwrap_or_default();
        match invalidation.disputes.iter().find(|d| d.path == rel) {
            None => report.push(Diagnostic::error(
                "resolution.dispute-unlisted",
                rel,
                format!(
                    "{alias}: {} does not list this dispute; a dispute the signed invalidation \
                     did not write does not count",
                    record.invalidation
                ),
            )),
            Some(d) if d.sha256 != now || d.warrant != alias => {
                report.push(Diagnostic::error(
                    "resolution.dispute-edited",
                    rel,
                    format!(
                        "{alias}: {} recorded this dispute at {} and it is now {now} — edited \
                         after it was written",
                        record.invalidation, d.sha256
                    ),
                ));
            }
            Some(_) => report.push(Diagnostic::warn(
                "resolution.disputed",
                rel,
                format!(
                    "{alias}: resolution {} is disputed ({}, open): {}. Reliance: {} \
                     resolution.toml is unchanged; standing is read from the dispute",
                    resolution.resolution.id,
                    record.dispute.id,
                    record.dispute.grounds,
                    record.dispute.reliance_policy
                ),
            )),
        }
    }
}

// SPDX-License-Identifier: Apache-2.0
//! `war check` — deterministic, agent-free validation (SAS §71.7, RQ-074).
//!
//! No model, no network, no clock. Reproducibility is not a nicety here: a
//! checker whose verdict can vary is not a control.
//!
//! That was once guaranteed by the binary having no HTTP client at all. Since
//! OW-WAR-0044 it is guaranteed by this module not using the one it has: `ureq`
//! is linked for the §67 Knowledge Fabric seam, and `war kf` is the only
//! command that dials. `war check` reaching the network would make its verdict
//! depend on someone else's uptime, which is the opposite of a control.

use std::collections::{BTreeMap, BTreeSet};

use openwarrant_compiler::{ChildRef, lower};
use openwarrant_core::{ValidatedManifest, detect_parent_cycles, milestones, obligation, seam};

use crate::compile::{adr_overview, projections, warrant_overview};

// OW-WAR-0119: the corpus identity rules. A child of this module, not a
// sibling in `lib.rs`, because `war check` is their only caller.
#[path = "identity_check.rs"]
mod identity_check;
use crate::diagnostic::{Diagnostic, Report, Severity};
use crate::repo::{Loaded, RepoError, Repository};

/// OW-WAR-0137 — a Warrant's review assignment against what its authorizer
/// signed, named by rule. An assignment edited, added or removed after
/// signing (`assignment.moved`) or one that does not parse
/// (`assignment.malformed`) is an ERROR: nobody may take the act it governs
/// until a human restores or re-authorizes it. An assignee who has since lost
/// the role is a WARN (`assignment.role-revoked`): the act waits, and nobody
/// else is substituted. A Warrant with no assignment reports nothing.
fn check_assignment(
    repo: &Repository,
    one: &Loaded,
    register: Option<&openwarrant_core::authority::AuthorityRegister>,
    report: &mut Report,
) {
    use crate::authorize::assignment::{self, Standing};
    let alias = one.alias();
    let file = repo.relative(&one.dir.join(assignment::FILE));
    let standing = match crate::authorize::assignment_standing(repo, &one.dir) {
        Ok(s) => s,
        Err(e) => {
            report.push(Diagnostic::unknown(
                "assignment.unreadable",
                file,
                format!("{alias}: the assignment's standing could not be read: {e}"),
            ));
            return;
        }
    };
    match standing {
        Standing::None => {}
        Standing::Moved { .. } | Standing::Malformed(_) => {
            if let Err(f) = standing.for_act(assignment::Act::Resolve) {
                report.push(Diagnostic::error(
                    f.rule,
                    file,
                    format!("{alias}: {}", f.message),
                ));
            }
        }
        Standing::Unsigned(ref a) | Standing::Signed(ref a) => {
            let signed = matches!(standing, Standing::Signed(_));
            let findings = register
                .map(|r| assignment::validate(a, r, &repo.performer()))
                .unwrap_or_default();
            for f in &findings {
                // Before signing, `war authorize` will refuse it; after, the
                // register moved under a signed assignment.
                let rule = if signed && f.rule == "assignment.role-missing" {
                    "assignment.role-revoked"
                } else {
                    f.rule
                };
                report.push(Diagnostic::warn(
                    rule,
                    file.clone(),
                    format!("{alias}: {}", f.message),
                ));
            }
            if findings.is_empty() {
                report.push(Diagnostic::pass(
                    if signed {
                        "assignment.signed"
                    } else {
                        "assignment.proposed"
                    },
                    format!(
                        "{alias}: {} {}",
                        a.digest(),
                        if signed {
                            "is the assignment the authorizer signed"
                        } else {
                            "awaits the authorizer's signature"
                        }
                    ),
                ));
            }
        }
    }
}

/// Run every Phase 1 check over the whole corpus, or one Warrant.
pub fn run(
    repo: &Repository,
    only: Option<&str>,
    check_generated: bool,
) -> Result<Report, RepoError> {
    let dirs = match only {
        Some(alias) => vec![repo.warrant_dir(alias)?],
        None => repo.warrant_dirs()?,
    };

    let mut report = Report::default();
    let mut undisposed_warrants = 0usize;
    let mut total_warrants = 0usize;

    if dirs.is_empty() {
        report.push(Diagnostic::warn(
            "corpus.empty",
            repo.config.paths.warrants.clone(),
            "no Warrants found; nothing to check",
        ));
        return Ok(report);
    }

    let mut loaded = Vec::new();
    for dir in &dirs {
        let one = repo.load_warrant(dir)?;
        loaded.push(one);
    }

    // OW-WAR-0121: a temp file of the atomic write path is a write that
    // stopped before its rename. The record it was meant to replace is whole
    // (old or absent); the temp file is named so a person can remove it.
    check_stray_temps(repo, only.map(|_| dirs.as_slice()), &mut report);

    // A parent's contract digest is computed from the parent, so verifying a
    // child's citation needs the whole corpus in hand. When only one Warrant was
    // requested, load the rest read-only so the citation can still be checked
    // rather than reported as unknowable.
    let corpus = if only.is_some() {
        let mut all = Vec::new();
        for dir in repo.warrant_dirs()? {
            all.push(repo.load_warrant(&dir)?);
        }
        all
    } else {
        loaded.clone()
    };
    let parent_digests = contract_digests(&corpus);

    // §43.1 — local gate candidates. Loaded once for the corpus so an obligation
    // citing a gate can be resolved rather than taken on trust.
    let gates = load_gate_registry(repo, &mut report);
    report_independence(repo, &loaded, &mut report);
    // OW-WAR-0138: where the actor binding and the policy keys come from —
    // `authority.unprotected` once without a store, a divergence per key
    // with one.
    for d in crate::authority_check::protection_report(repo) {
        report.push(d);
    }

    // OW-ADR-0022: currency is derived from relations, once, over the whole
    // corpus, and read by everything below that asks it.
    let currencies = crate::relations::currencies(&corpus);

    // §20 and §21 relation conformance (OW-WAR-0043 OBL-004, §91.5 tests 30-35).
    // Built over the WHOLE corpus for the same reason parent digests are: a
    // parent/child claim is not checkable from one side of the relation.
    {
        let related: Vec<crate::relations::Related<'_>> = corpus
            .iter()
            .filter_map(|one| {
                let validated = one.validated.as_ref()?;
                let basis = one.basis.as_ref()?;
                let atom_source = basis
                    .atoms
                    .iter()
                    .map(|a| String::from_utf8_lossy(&a.bytes).into_owned())
                    .collect::<Vec<_>>()
                    .join("\n");
                Some(crate::relations::Related {
                    alias: one.alias().to_string(),
                    manifest: validated,
                    manifest_file: one.dir.join("manifest.toml").to_string(),
                    generated_view: std::fs::read_to_string(
                        one.dir.join("generated").join("WAR.md"),
                    )
                    .ok(),
                    atom_source,
                })
            })
            .collect();
        crate::relations::check(&related, &currencies, &mut report);
    }
    // OW-ADR-0023: the roadmap record, and the Warrants it holds to a phase.
    crate::roadmap_cmd::check(repo, &corpus, &mut report);
    let roadmap = crate::roadmap_cmd::load(repo).ok().flatten();

    // OW-ADR-0021: which Warrant governs each path NOW. Built once — it
    // verifies one attestation per owning Warrant, and the drift decision
    // below asks it for every content-addressed deliverable in the corpus.
    let ownership = crate::ownership::Ownership::index_with(repo, &currencies)?;
    // OW-WAR-0125: each recorded SAS revision split into sections, read from
    // the document or from history at most once per run.
    let sas_sections = crate::sas::RevisionSections::new(repo);

    let shared = Shared {
        corpus: &corpus,
        parent_digests: &parent_digests,
        gates: &gates,
        ownership: &ownership,
        roadmap: roadmap.as_ref(),
        sas_sections: &sas_sections,
    };
    // OW-WAR-0137: the register, once, for every Warrant's assignment.
    let register = repo.load_authority_register();
    for one in &loaded {
        check_one(repo, one, shared, check_generated, &mut report);
        check_assignment(repo, one, register.as_ref().ok(), &mut report);
        if let Some(basis) = &one.basis {
            total_warrants += 1;
            let fully_undisposed = basis
                .atoms
                .iter()
                .filter(|a| a.role == "assurance")
                .filter_map(|a| obligation::parse(&String::from_utf8_lossy(&a.bytes)).ok())
                .any(|set| {
                    !set.obligations.is_empty() && set.undisposed().len() == set.obligations.len()
                });
            if fully_undisposed {
                undisposed_warrants += 1;
            }
        }
    }

    // Cross-Warrant checks need the whole corpus, so they run after the loop.
    // §91.2 test 12.
    let validated: Vec<ValidatedManifest> =
        loaded.iter().filter_map(|l| l.validated.clone()).collect();
    let cycles = detect_parent_cycles(&validated);
    if cycles.is_empty() {
        report.push(Diagnostic::pass(
            "composition.acyclic",
            format!(
                "parent graph is acyclic across {} Warrant(s)",
                validated.len()
            ),
        ));
    } else {
        for cycle in cycles {
            report.push(Diagnostic::error(
                "composition.cycle",
                repo.config.paths.warrants.clone(),
                format!("parent cycle: {}", cycle.path.join(" → ")),
            ));
        }
    }

    // ADR corpus (§19). A malformed ADR is an error; the Overview is a
    // projection and drift-checks exactly like a Warrant parent (§19.7).
    let adrs = repo.load_adrs()?;
    for (path, err) in &adrs.failures {
        report.push(Diagnostic::error(
            "adr.malformed",
            path.clone(),
            err.to_string(),
        ));
    }
    if adrs.failures.is_empty() && !adrs.records.is_empty() {
        report.push(Diagnostic::pass(
            "adr.parsed",
            format!("{} ADR(s) parsed", adrs.records.len()),
        ));
    }
    // §12 identity (OW-WAR-0119), once per run: duplicates and alias
    // resolution need every Warrant and every ADR in hand, so this sits after
    // both are loaded rather than inside the per-Warrant loop.
    identity_check::check(repo, &corpus, &loaded, &adrs.records, &mut report);
    // §101 — the SAS is a controlled document. The bytes on disk are held to
    // the latest recorded revision's digest. Until OW-WAR-0058 nothing in code
    // compared them: the digest appeared in six places, all prose.
    match repo.load_sas_revisions() {
        Err(err) => report.push(Diagnostic::error(
            "sas.revision-malformed",
            repo.config.paths.sas.clone(),
            err.to_string(),
        )),
        Ok(revisions) => match crate::sas::pin_of(&revisions) {
            None => report.push(Diagnostic::warn(
                "sas.unrecorded",
                repo.config.paths.sas.clone(),
                "no SAS revision is recorded; the document is pinned by prose only. \
                 `war sas propose <version>` records one"
                    .to_owned(),
            )),
            Some(pin) => match repo.sas_document() {
                Err(err) => report.push(Diagnostic::error(
                    "sas.document",
                    repo.config.paths.sas.clone(),
                    err.to_string(),
                )),
                Ok((path, bytes)) => {
                    let actual = openwarrant_compiler::sha256_hex(&bytes);
                    if actual == pin.sha256 {
                        report.push(Diagnostic::pass(
                            "sas.pinned",
                            format!(
                                "{} matches revision {} ({}), sha256:{}",
                                repo.relative(&path),
                                pin.version,
                                pin.state,
                                &pin.sha256[..12]
                            ),
                        ));
                    } else if let Some(proposed) = revisions
                        .iter()
                        .find(|r| r.sha256 == actual && r.version != pin.version)
                    {
                        // The remedy the error names, taken: the document IS a
                        // recorded proposal awaiting a human. The accepted
                        // revision stays normative until then (§101.2).
                        report.push(Diagnostic::warn(
                            "sas.proposed-unaccepted",
                            repo.relative(&path),
                            format!(
                                "the document is revision {} ({}), sha256:{}; the accepted \
                                 revision {} remains normative until `war sign {}` accepts it",
                                proposed.version,
                                proposed.state,
                                &actual[..12],
                                pin.version,
                                proposed.version
                            ),
                        ));
                    } else {
                        report.push(Diagnostic::error(
                            "sas.digest-drift",
                            repo.relative(&path),
                            format!(
                                "the document is sha256:{actual} but revision {} ({}) records \
                                 sha256:{}. §101.6: the accepted revision is normative and mirrors \
                                 state its exact digest. Either restore the bytes or propose a \
                                 new revision — an edited document under an unchanged record is \
                                 the failure this check exists for",
                                pin.version, pin.state, pin.sha256
                            ),
                        ));
                    }
                }
            },
        },
    }

    // OW-ADR-0029: every class file — one that reaches an authority path, or
    // whose acceptance no longer verifies over its bytes, is an error.
    crate::standing_cmd::check_classes(repo, &mut report);

    // Accepting a SAS revision is the act that makes a specification normative
    // for every Warrant that pins it, so it is held to the same rule as an
    // authorization: a human signature over the acceptance response's exact
    // bytes, naming the digest of the document accepted. Leaving this act out
    // would have left one path where a record is believed for its contents.
    let sas_revisions = repo.load_sas_revisions().unwrap_or_default();
    let sas_pin = crate::sas::pin_of(&sas_revisions).map(|p| p.version.clone());
    for rev in &sas_revisions {
        let Some(acceptance) = &rev.acceptance else {
            continue;
        };
        let subject = format!("SAS-{}", rev.version);
        let verdict = crate::authority_check::verify(
            repo,
            crate::authority_check::Act::Accept,
            &subject,
            &acceptance.accepted_by,
            Some(&rev.sha256),
        );
        if verdict.is_signed() {
            report.push(Diagnostic::pass(
                "authority.signed",
                format!("{subject}: {}", verdict.why()),
            ));
        } else if sas_pin.as_deref() == Some(rev.version.as_str()) {
            report.push(Diagnostic::error(
                verdict.rule(),
                format!("docs/sas/revisions/{}.toml", rev.version),
                format!("{subject}: {}", verdict.why()),
            ));
        } else {
            // A superseded revision is normative for nothing. Its acceptance
            // predates enforcement and cannot be signed now without dating the
            // act wrongly, so it is reported and not treated as a live failure.
            report.push(Diagnostic::warn(
                verdict.rule(),
                format!("docs/sas/revisions/{}.toml", rev.version),
                format!(
                    "{subject}: superseded by {} and normative for nothing; {}",
                    sas_pin.as_deref().unwrap_or("no accepted revision"),
                    verdict.why()
                ),
            ));
        }
    }

    // Both corpus-wide projections drift-check through the same function, so
    // they cannot come to report drift differently.
    if check_generated && repo.config.generated.verify_drift {
        drift_check(
            repo,
            warrant_overview(repo),
            "warrant-overview",
            &mut report,
        );
        drift_check(repo, adr_overview(repo), "adr-overview", &mut report);
        drift_check(
            repo,
            crate::status::corpus_status_md(repo),
            "corpus-status",
            &mut report,
        );
        drift_check(
            repo,
            crate::status::corpus_status_json(repo),
            "corpus-status",
            &mut report,
        );
        drift_check(
            repo,
            crate::status::corpus_status_html(repo),
            "corpus-status",
            &mut report,
        );
        drift_check(
            repo,
            crate::timeline::corpus_timeline_json(repo),
            "corpus-timeline",
            &mut report,
        );
        drift_check(
            repo,
            crate::timeline::corpus_pending_json(repo),
            "corpus-pending",
            &mut report,
        );
        // The SAS normative projection (E1), when there is a document.
        if repo.sas_document().is_ok() {
            match crate::compile::sas_normative(repo) {
                Ok(files) => {
                    for file in files {
                        drift_check(repo, Ok(file), "sas-normative", &mut report);
                    }
                }
                Err(e) => drift_check(repo, Err(e), "sas-normative", &mut report),
            }
            // The section index (OW-WAR-0125), by the same function.
            match crate::compile::sas_sections(repo) {
                Ok(files) => {
                    for file in files {
                        drift_check(repo, Ok(file), "sas-sections", &mut report);
                    }
                }
                Err(e) => drift_check(repo, Err(e), "sas-sections", &mut report),
            }
        }
        // OW-ADR-0022: the master document, and the history when this
        // repository keeps one. `generated.drift`, the rule every projection
        // of a Warrant reports under: CURRENT.md is written by `compile` and by
        // nothing else. With `history = false` nothing is compiled for
        // HISTORY.md, so nothing is compared.
        match crate::compile::master_documents(repo) {
            Ok(files) => {
                for file in files {
                    drift_check(repo, Ok(file), "generated", &mut report);
                }
            }
            Err(e) => drift_check(repo, Err(e), "generated", &mut report),
        }
    }

    // §38.6 disposition status, aggregated once for the corpus rather than
    // blocking each Warrant. Undisposed is the normal state of planned work.
    if undisposed_warrants > 0 {
        report.note(format!(
            "{undisposed_warrants} of {total_warrants} Warrant(s) have no disposed              obligations — §38.6 yields no resolution verdict for them, which is the              expected state of work that has not been assessed"
        ));
    }

    // §28.5 coverage, reported once for the corpus. A contract digest covering
    // 8 of 17 elements is not a §28.5 contract digest, and saying so on every
    // run is what stops it being mistaken for one (OW-ADR-0004).
    let coverage = openwarrant_compiler::WarIr::current_coverage();
    if !coverage.is_complete() {
        report.note(format!(
            "contract digest covers {} of {} §28.5 elements — missing: {}",
            coverage.len(),
            openwarrant_core::ContractElement::ALL.len(),
            coverage
                .missing()
                .iter()
                .map(ToString::to_string)
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }

    // Printed on every run including a clean one, and deliberately NOT a
    // diagnostic: a report that answers "ok" while whole classes of check go
    // unasked reads as full coverage, but a scope note that blocked readiness
    // would make the verdict permanently negative and therefore meaningless.
    report.note("gate execution — `war gate --run` executes a registered gate (§44), but `war check` does not invoke it, so nothing here is evidence that a Warrant's acceptance gates were run");
    report.note("Preflight readiness (§32.7) — 'well-formed' is a claim about the record only");
    report.note("bound-atom resolution — `ref =` atoms cannot be fetched offline");
    // Kept, and now says WHY rather than only that. OW-WAR-0049's OBL-003 asks
    // this note to match reality: the tests are not merely unimplemented, they
    // are blocked on a decision this repository has not made, and OW-ADR-0007
    // records which decision. A note that says "unchecked" without saying what
    // would change it reads as a backlog item; this one names the blocker.
    report.note(
        "Source Holder ambiguity and classification propagation (§91.2 tests 14, 15) — \
         narrowed by OW-ADR-0008: test 14 needs a `source_holder` on atoms, which §13 \
         requires and none declares; test 15 needs a classification ordering, which \
         the SAS does not give. Neither is undecided — both are undeclared",
    );
    if !check_generated {
        report.note("generated-view drift — pass --generated to compare committed projections");
    }
    if only.is_none() {
        check_roadmap_status_claims(repo, &mut report);
    }

    Ok(report)
}

/// `storage.stray-temp` (warning) for each file `atomic::stray` finds under
/// `docs/`; with one Warrant asked for, only those inside its directory.
fn check_stray_temps(
    repo: &Repository,
    within: Option<&[camino::Utf8PathBuf]>,
    report: &mut Report,
) {
    for s in crate::compile::atomic::stray(&repo.root) {
        if within.is_some_and(|dirs| !dirs.iter().any(|d| s.temp.starts_with(d))) {
            continue;
        }
        report.push(Diagnostic::warn(
            "storage.stray-temp",
            repo.relative(&s.temp),
            format!(
                "{} is a temp file left by a write that stopped before its rename; it was meant \
                 to replace {}, which is whole as it stands (the previous bytes, or absent). \
                 Nothing reads the temp file. Remove it once you know which act stopped",
                repo.relative(&s.temp),
                repo.relative(&s.record)
            ),
        ));
    }
}

/// Compare one generated corpus-wide projection against a fresh compilation.
///
/// Shared by the Warrant and ADR overviews so the two cannot drift apart in how
/// they report drift — a duplicated check is a check that gets fixed in one place.
fn drift_check(
    repo: &Repository,
    compiled: Result<(camino::Utf8PathBuf, String), RepoError>,
    rule: &str,
    report: &mut Report,
) {
    match compiled {
        Ok((path, expected)) => {
            let relative = repo.relative(&path);
            let name = path.file_name().unwrap_or("overview").to_owned();
            match std::fs::read_to_string(&path) {
                Ok(actual) if actual == expected => report.push(Diagnostic::pass(
                    format!("{rule}.drift"),
                    format!("{name} matches a fresh compilation"),
                )),
                Ok(_) => report.push(Diagnostic::error(
                    format!("{rule}.drift"),
                    relative,
                    format!(
                        "the committed {name} differs from a fresh compilation; it was \
                         edited by hand or its sources changed without recompiling"
                    ),
                )),
                Err(_) if repo.config.generated.commit => report.push(Diagnostic::error(
                    format!("{rule}.missing"),
                    relative,
                    format!(
                        "{name} is missing and this repository commits generated views; \
                         run `war compile`"
                    ),
                )),
                Err(_) => {}
            }
        }
        Err(err) => report.push(Diagnostic::error(
            format!("{rule}.compile"),
            repo.config.paths.warrants.clone(),
            err.to_string(),
        )),
    }
}

/// Contract digest per Warrant UUID, for verifying children's citations.
///
/// A Warrant that could not be validated has no contract digest and is simply
/// absent from the map; a child citing it gets an honest "cannot verify" rather
/// than a comparison against a value invented from broken sources.
fn contract_digests(corpus: &[Loaded]) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    for one in corpus {
        let (Some(basis), Some(validated)) = (&one.basis, &one.validated) else {
            continue;
        };
        if let Ok(ir) = lower(basis, validated)
            && let Ok(digest) = ir.contract_digest()
        {
            out.insert(validated.uuid.to_string(), digest);
        }
    }
    out
}

/// §46.3 — report, ONCE, whether verification here meets each level's minimum.
///
/// Independence is declared per repository, so reporting it per Warrant says the
/// same sentence forty-nine times. A finding repeated once per record is a
/// finding nobody reads, which would defeat the point of surfacing it at all.
///
/// Never fatal at draft. §46.3's minimum binds when a resolution is recorded
/// (§56.1 requirement 10). A repository that could not pass its own gate on day
/// one would have the rule deleted rather than the gap closed — but silence is
/// worse, and silence is what alpha shipped: "this repository authored and
/// verified itself" was a paragraph in the roadmap that no tool could act on.
fn report_independence(repo: &Repository, loaded: &[Loaded], report: &mut Report) {
    let config_path = repo.relative(&repo.root.join("openwarrant.toml"));

    let Some(independence) = &repo.config.independence else {
        report.push(Diagnostic::warn(
            "independence.undeclared",
            config_path,
            "no independence is declared for this repository, so §46.3's minimums \
             cannot be evaluated for any Warrant. Absent is not the same as none — \
             `none` reads as examined and absent, absent reads as unexamined"
                .to_owned(),
        ));
        return;
    };

    // Group by the level actually declared, since the minimum differs per level.
    let mut by_level: BTreeMap<String, usize> = BTreeMap::new();
    for one in loaded {
        if let Some(v) = &one.validated {
            *by_level.entry(v.assurance_level.to_string()).or_insert(0) += 1;
        }
    }

    for (level, count) in by_level {
        match independence.meets(&level) {
            Ok(()) => report.push(Diagnostic::pass(
                "independence.sufficient",
                format!("{count} {level} Warrant(s): declared independence meets §46.3's minimum"),
            )),
            Err(err) => report.push(Diagnostic::warn(
                "independence.insufficient",
                config_path.clone(),
                format!("{count} {level} Warrant(s): {err}"),
            )),
        }
    }
}

/// Load `docs/gates/*.yaml` as §43.1 local candidates.
///
/// A malformed definition is an ERROR rather than a skip. A registry that
/// quietly drops the file it could not read would let every citation of that
/// gate report unresolved, or worse, let a later valid-looking file take its
/// place unnoticed.
pub(crate) fn load_gate_registry(
    repo: &Repository,
    report: &mut Report,
) -> openwarrant_core::GateRegistry {
    let mut registry = openwarrant_core::GateRegistry::default();
    let dir = repo.root.join(&repo.config.paths.gates);
    let Ok(entries) = dir.read_dir_utf8() else {
        // No gates directory is a legitimate state: a repository may declare no
        // gates. It is reported as a note so it cannot be mistaken for a
        // registry that was read and found empty.
        report.note(format!(
            "gate registry — {} does not exist, so no gate citation can be \
             resolved. §43.1 local candidates live there",
            repo.config.paths.gates
        ));
        return registry;
    };

    let mut paths: Vec<_> = entries
        .filter_map(Result::ok)
        .map(|e| e.into_path())
        .filter(|p| p.extension().is_some_and(|e| e == "yaml" || e == "yml"))
        .collect();
    paths.sort();

    for path in paths {
        let rel = repo.relative(&path);
        let Ok(text) = std::fs::read_to_string(&path) else {
            report.push(Diagnostic::error(
                "gate.unreadable",
                rel,
                "gate definition could not be read".to_owned(),
            ));
            continue;
        };
        let doc = match openwarrant_core::structured::parse(&text) {
            Ok(d) => d,
            Err(err) => {
                report.push(Diagnostic::error("gate.malformed", rel, format!("{err}")));
                continue;
            }
        };
        match openwarrant_core::gate::definition_from_structured(&doc) {
            Ok(def) => {
                let key = def.key();
                let provenance = def.provenance;
                match registry.insert(def) {
                    Ok(()) => report.push(Diagnostic::pass(
                        "gate.registered",
                        format!("{key}: {provenance}, qualified against its declared fault model"),
                    )),
                    Err(err) => {
                        report.push(Diagnostic::error("gate.duplicate", rel, format!("{err}")));
                    }
                }
            }
            Err(err) => report.push(Diagnostic::error("gate.invalid", rel, format!("{err}"))),
        }
    }
    registry
}

#[allow(clippy::too_many_arguments)]
/// §37.2 — a declared deliverable's recorded digest must still match its bytes.
///
/// # Why this belongs in `war check` and not only in `war resolve`
///
/// `war resolve` already recomputes these digests, and it caught the drift both
/// times it happened. It caught it *late*: resolve is run deliberately, by
/// someone asking about one Warrant, so a stale record sat in `main` until
/// somebody thought to look. Twice in two days an unrelated pull request edited
/// a file some Warrant had declared — once `ci.yml` under a Bonsai change, once
/// `ci.yml` again under a dependency bump — and each time OW-WAR-0001 silently
/// lost a requirement.
///
/// A record that no longer describes the bytes it names is false as written, so
/// this is an ERROR rather than a warning. The remedy is small and specific:
/// either the artifact changed and the record must be regenerated, or the
/// artifact changed and should not have.
///
/// # Deliberately not silent about the missing case
///
/// A deliverable declaring `content_addressed` with no provenance, or with a
/// target that cannot be read, is reported rather than skipped. "The digest does
/// not match" and "there is nothing to match against" are different problems and
/// a check that collapsed them would send the reader to the wrong fix.
/// Does a signed record bind this Warrant's deliverable digests?
///
/// Exactly one thing does: a resolution, whose §56.2 record carries
/// `artifact_manifest_digest` = sha256 of `deliverables.toml`. Moving a pin
/// under it would change what the resolution resolved, so that is an ERROR and
/// `war correct` is the act for it (OW-WAR-0064).
///
/// An authorization does NOT. The contract digest covers intent, scope,
/// obligations, milestones and stages — not which bytes a file happens to have
/// while the work is being done. Treating it as binding sent a signed but
/// unresolved Warrant to `war correct`, which refuses with
/// `correction.not-resolved`: an error whose only remedy was itself refused.
///
/// So a pin that no one has resolved against is out of date, not violated —
/// `war pins --refresh` re-records it. That distinction is why `war check` can
/// run during ordinary work: a repository with nineteen unsigned Warrants
/// pinning living source files reported ten ERRORs and NOT READY on every
/// commit, forever, protecting nothing.
pub fn resolution_binds(repo: &Repository, one: &Loaded) -> bool {
    repo.load_resolution(&one.dir).ok().flatten().is_some()
}

fn check_deliverable_digests(
    repo: &Repository,
    one: &Loaded,
    alias: &str,
    ownership: &crate::ownership::Ownership,
    report: &mut Report,
) {
    let bound = resolution_binds(repo, one);
    let authorization = repo.load_authorization(&one.dir).ok().flatten();
    let authorized_at = authorization
        .as_ref()
        .and_then(|a| a.revision.authorization.as_ref())
        .map(|a| a.effective_time.clone());
    let deliverables = match repo.load_deliverables(&one.dir) {
        Ok(set) => set,
        Err(err) => {
            report.push(Diagnostic::error(
                "deliverable.unreadable",
                repo.relative(&one.dir.join("deliverables.toml")),
                format!("{alias}: {err}"),
            ));
            return;
        }
    };
    let file = repo.relative(&one.dir.join("deliverables.toml"));
    for (path, why) in &deliverables.failures {
        report.push(Diagnostic::error(
            "deliverable.malformed",
            path.clone(),
            format!("{why} — an unreadable deliverables file is not an absent one"),
        ));
    }

    // OW-ADR-0021: the set the authorizer signed for is the set that owns.
    // A record with no `owned` set predates ownership and owns nothing, so
    // there is nothing to compare; one with a set is held to it both ways.
    // `authorize` refuses a set that moved between drafting and signing
    // (`authorize.stale-deliverables`); these two catch the edit AFTER.
    if let Some(record) = &authorization
        && !record.owned.is_empty()
        && deliverables.failures.is_empty()
    {
        let declared: BTreeSet<(&str, &str)> = deliverables
            .records
            .iter()
            .map(|d| (d.id.as_str(), d.target_ref.as_str()))
            .collect();
        let owned: BTreeSet<(&str, &str)> = record
            .owned
            .iter()
            .map(|d| (d.id.as_str(), d.target_ref.as_str()))
            .collect();
        let mut agree = true;
        for (id, target) in declared.difference(&owned) {
            agree = false;
            report.push(Diagnostic::warn(
                "deliverable.undeclared-at-authorization",
                file.clone(),
                format!(
                    "{alias}: {id} → {target} is declared now but was not in the set the \
                     authorization signed for, so {alias} does not own it and no other \
                     Warrant's pin on it becomes historical. Ownership widens only through \
                     an amendment and a re-authorization (§31, OW-ADR-0021)"
                ),
            ));
        }
        for (id, target) in owned.difference(&declared) {
            agree = false;
            report.push(Diagnostic::error(
                "deliverable.declared-then-removed",
                file.clone(),
                format!(
                    "{alias}: the authorization signed for {id} → {target} and \
                     deliverables.toml no longer declares it. A signed claim on a path \
                     cannot be withdrawn by deleting the line — restore the declaration, \
                     or amend and re-authorize (§31, OW-ADR-0021)"
                ),
            ));
        }
        if agree {
            report.push(Diagnostic::pass(
                "deliverable.owned",
                format!(
                    "{alias}: the {} deliverable(s) declared are the {} the authorization \
                     signed for",
                    declared.len(),
                    owned.len()
                ),
            ));
        }
    }

    let addressed: Vec<_> = deliverables
        .records
        .iter()
        .filter(|d| d.content_addressed)
        .collect();
    if addressed.is_empty() {
        return;
    }

    // OW-WAR-0064 — a resolved Warrant's pin may have been superseded by an
    // authorized correction. The structural checks on the correction records
    // live in `correct::check`; the chain is resolved HERE, beside the digest
    // comparison, so "corrected" and "drifted" are decided by one computation.
    crate::correct::check(repo, one, alias, report);
    let corrections = repo.load_corrections(&one.dir).unwrap_or_default();

    let mut drifted = 0usize;
    let mut corrected = 0usize;
    let mut historical = 0usize;
    for deliverable in &addressed {
        let Some(provenance) = deliverable.provenance.as_ref() else {
            report.push(Diagnostic::error(
                "deliverable.no-provenance",
                file.clone(),
                format!(
                    "{alias}: {} declares content addressing and carries no provenance, so there \
                     is no digest to check",
                    deliverable.id
                ),
            ));
            drifted += 1;
            continue;
        };
        // Only sha256 is supported, and an unsupported algorithm is said so
        // rather than compared. `trim_start_matches` would leave "md5:abc"
        // intact, which never equals a sha256 hex, so the check still refuses —
        // but it refuses as "digest drift", sending the reader to regenerate a
        // record whose algorithm is the actual problem. The verdict was already
        // right; the diagnosis was not.
        let Some(recorded) = provenance.content_digest.strip_prefix("sha256:") else {
            report.push(Diagnostic::error(
                "deliverable.unsupported-digest",
                file.clone(),
                format!(
                    "{alias}: {} records {:?}, and only sha256: is supported. This is not                      drift — the record cannot be checked at all",
                    deliverable.id, provenance.content_digest
                ),
            ));
            drifted += 1;
            continue;
        };
        let (chain, head) =
            crate::correct::head_for(&corrections, &deliverable.id, &provenance.content_digest);
        let head = match head {
            Ok(h) => h,
            Err(openwarrant_core::correction::ChainError::Gap { expected, found }) => {
                report.push(Diagnostic::error(
                    "correction.sequence-gap",
                    file.clone(),
                    format!(
                        "{alias}: {} corrections are numbered 1..n without gaps; expected {expected}, \
                         found {found}",
                        deliverable.id
                    ),
                ));
                drifted += 1;
                continue;
            }
            Err(e @ openwarrant_core::correction::ChainError::SupersededNeverDelivered { .. }) => {
                report.push(Diagnostic::error(
                    "correction.superseded-never-delivered",
                    file.clone(),
                    format!("{alias}: {} — {e}", deliverable.id),
                ));
                drifted += 1;
                continue;
            }
        };
        let head_hex = head.trim_start_matches("sha256:");
        match std::fs::read(repo.root.join(&deliverable.target_ref)) {
            Ok(bytes) => {
                let actual = openwarrant_compiler::sha256_hex(&bytes);
                if actual == head_hex {
                    if !chain.is_empty() {
                        corrected += 1;
                        report.push(Diagnostic::pass(
                            "deliverable.corrected",
                            format!(
                                "{alias}: {} corrected {} time(s); sha256:{recorded} superseded, \
                                 now {head}",
                                deliverable.id,
                                chain.len()
                            ),
                        ));
                    }
                } else if let Some(newer) = bound
                    .then(|| {
                        ownership.newer_than(
                            &deliverable.target_ref,
                            alias,
                            authorized_at.as_deref(),
                        )
                    })
                    .flatten()
                {
                    // OW-ADR-0021: a later authorized Warrant declares this
                    // path, so the bytes are its to answer for. This pin is a
                    // claim about a moment — `war pins --history` finds the
                    // commit — and neither drift nor a correction applies.
                    // Decided before the correction branch on purpose: a
                    // chain that stopped matching because a NEWER OWNER moved
                    // the file is not a correction that corrects nothing.
                    historical += 1;
                    report.push(Diagnostic::pass(
                        "deliverable.superseded-by",
                        format!(
                            "{alias}: {} pinned {} at {head}; {}/{} (authorized {}) now \
                             governs that path, so this pin is historical and the bytes \
                             are that Warrant's to answer for (OW-ADR-0021) — `war pins \
                             --history {}`",
                            deliverable.id,
                            deliverable.target_ref,
                            newer.alias,
                            newer.deliverable_id,
                            newer.authorized_at,
                            deliverable.target_ref
                        ),
                    ));
                } else if !chain.is_empty() {
                    report.push(Diagnostic::error(
                        "correction.new-digest-mismatch",
                        file.clone(),
                        format!(
                            "{alias}: {} — the latest correction records {head} but the file is \
                             sha256:{actual}; it corrects nothing. A further change is a further \
                             correction, `war correct {alias} {}`",
                            deliverable.id, deliverable.id
                        ),
                    ));
                    drifted += 1;
                } else if bound {
                    report.push(Diagnostic::error(
                        "deliverable.digest-drift",
                        file.clone(),
                        format!(
                            "{alias}: {} records sha256:{recorded} for {} but the file is now \
                             sha256:{actual}. A resolution binds this manifest and no later \
                             authorized Warrant declares {}, so the artifact moved outside any \
                             authorization — restore it; declare it as a deliverable of a \
                             Warrant and have that Warrant authorized (OW-ADR-0021); or record \
                             why it moved: `war correct {alias} {}` (OW-WAR-0064)",
                            deliverable.id,
                            deliverable.target_ref,
                            deliverable.target_ref,
                            deliverable.id
                        ),
                    ));
                    drifted += 1;
                } else {
                    // Nobody has signed for this Warrant, so the pin is a note
                    // about a file, not a promise about it.
                    report.push(Diagnostic::warn(
                        "deliverable.pin-stale",
                        file.clone(),
                        format!(
                            "{alias}: {} records sha256:{recorded} for {} and the file is now \
                             sha256:{actual}. No resolution binds this manifest, so the pin is \
                             out of date rather than violated — `war pins --refresh {alias}`",
                            deliverable.id, deliverable.target_ref
                        ),
                    ));
                }
            }
            Err(err) => {
                let why = format!(
                    "{alias}: {} names {} and it cannot be read: {err}. An unreadable artifact \
                     is not a verified one",
                    deliverable.id, deliverable.target_ref
                );
                if bound {
                    report.push(Diagnostic::error(
                        "deliverable.target-unreadable",
                        file.clone(),
                        why,
                    ));
                    drifted += 1;
                } else {
                    report.push(Diagnostic::warn(
                        "deliverable.target-unreadable",
                        file.clone(),
                        why,
                    ));
                }
            }
        }
    }

    if drifted == 0 {
        report.push(Diagnostic::pass(
            "deliverable.digests",
            format!(
                "{alias}: {} content-addressed deliverable(s) match their bytes{}{}",
                addressed.len(),
                if corrected > 0 {
                    format!(" ({corrected} through an authorized correction)")
                } else {
                    String::new()
                },
                if historical > 0 {
                    format!(" ({historical} historical, governed by a later Warrant)")
                } else {
                    String::new()
                }
            ),
        ));
    }
}

/// §34 and §105 — the references a Warrant makes to the SAS and the Roadmap.
///
/// # Why these were never checked before
///
/// `Implements.contribution` is an `Option<String>` on disk and `RoadmapRef` is
/// a bare `String`, and both were copied verbatim into the IR. So a manifest
/// could say `contribution = "mostly"` or `roadmap://OW-PHASE-11/x` and nothing
/// would object — `war show` says outright that only `war://` is resolved. The
/// corpus projection groups Warrants by phase and derives requirement status
/// from contributions, so both now have to parse, and a value that does not
/// parse is reported here rather than silently dropped from a count.
///
/// An absent contribution is a warning, not an error: §34.2 says a WAR SHOULD
/// declare it, and turning a SHOULD into a refusal would be reading a rule into
/// the text.
fn check_traceability(
    repo: &Repository,
    one: &Loaded,
    alias: &str,
    roadmap: Option<&crate::roadmap_cmd::Loaded>,
    report: &mut Report,
) {
    use openwarrant_core::traceability::{Contribution, RequirementRef, RoadmapRef};

    let Some(basis) = one.basis.as_ref() else {
        return;
    };
    let file = repo.relative(&one.dir.join("manifest.toml"));
    let mut bad = 0usize;

    for r in &basis.manifest.roadmap {
        match RoadmapRef::parse(&r.r#ref) {
            Err(err) => {
                report.push(Diagnostic::error(
                    "roadmap.malformed",
                    file.clone(),
                    format!("{alias}: {err}"),
                ));
                bad += 1;
            }
            // A `roadmap://` ref names THIS program's §98: another prefix is a
            // phase of a SAS this repository does not carry (slice C5).
            Ok(parsed) if parsed.prefix != repo.config.project.namespace.as_str() => {
                report.push(Diagnostic::error(
                    "roadmap.wrong-namespace",
                    file.clone(),
                    format!(
                        "{alias}: {} names phase prefix {:?}; this repository's namespace is \
                         {:?}, and its SAS is the only §98 a roadmap ref can point into",
                        r.r#ref,
                        parsed.prefix,
                        repo.config.project.namespace.as_str()
                    ),
                ));
                bad += 1;
            }
            // OW-ADR-0023: with a roadmap record, the phase must be one of its
            // phases; without one, §98's 0..=10.
            Ok(parsed) => match roadmap {
                Some(rm) => {
                    if !crate::roadmap_cmd::check_ref(rm, alias, &parsed, &file, report) {
                        bad += 1;
                    }
                }
                None if parsed.phase > RoadmapRef::MAX_PHASE => {
                    report.push(Diagnostic::error(
                        "roadmap.malformed",
                        file.clone(),
                        format!(
                            "{alias}: {} names phase {}; §98 defines 0..=10 and this program has no roadmap record to say otherwise",
                            r.r#ref, parsed.phase
                        ),
                    ));
                    bad += 1;
                }
                None => {}
            },
        }
    }

    // §106 of the SAS as it stands: an `implements` ref must name a row that
    // exists. `None` when the document cannot be read — then nothing is
    // refused and nothing is vouched for (OW-WAR-0063).
    let known_requirements: Option<std::collections::BTreeMap<String, String>> = repo
        .sas_document()
        .ok()
        .map(|(_, bytes)| openwarrant_core::sas::section_106(&String::from_utf8_lossy(&bytes)))
        .filter(|m| !m.is_empty());
    for i in &basis.manifest.implements {
        if let Err(err) = RequirementRef::parse(&i.r#ref) {
            report.push(Diagnostic::error(
                "traceability.requirement-ref",
                file.clone(),
                format!("{alias}: {err}"),
            ));
            bad += 1;
        }
        if let Ok(rq) = RequirementRef::parse(&i.r#ref)
            && let Some(known) = &known_requirements
            && !known.contains_key(&rq.canonical())
        {
            bad += 1;
            report.push(Diagnostic::error(
                "traceability.unknown-requirement",
                repo.relative(&one.dir.join("manifest.toml")),
                format!(
                    "{alias}: implements {} and §106 of the pinned SAS has no such row (§34.1: a Warrant implements a requirement that exists)",
                    i.r#ref
                ),
            ));
        }
        match i.contribution.as_deref() {
            None => report.push(Diagnostic::warn(
                "traceability.contribution-unstated",
                file.clone(),
                format!(
                    "{alias}: {} declares no contribution; §34.2 says a WAR SHOULD state \
                     one of {}",
                    i.r#ref,
                    Contribution::known()
                ),
            )),
            Some(text) => {
                if let Err(err) = text.parse::<Contribution>() {
                    report.push(Diagnostic::error(
                        "traceability.contribution",
                        file.clone(),
                        format!("{alias}: {}: {err}", i.r#ref),
                    ));
                    bad += 1;
                }
            }
        }
    }

    if bad == 0 && !(basis.manifest.roadmap.is_empty() && basis.manifest.implements.is_empty()) {
        report.push(Diagnostic::pass(
            "traceability.refs",
            format!(
                "{alias}: {} requirement ref(s) and {} roadmap ref(s) parse",
                basis.manifest.implements.len(),
                basis.manifest.roadmap.len()
            ),
        ));
    }
}

/// What every Warrant's check reads from the corpus as a whole: built once
/// in `run`, never per Warrant.
#[derive(Clone, Copy)]
struct Shared<'a> {
    corpus: &'a [Loaded],
    /// Contract digests by alias, for a child's citation of its parent.
    parent_digests: &'a BTreeMap<String, String>,
    gates: &'a openwarrant_core::GateRegistry,
    /// OW-ADR-0021: which Warrant governs each path now.
    ownership: &'a crate::ownership::Ownership,
    /// OW-ADR-0023: the roadmap record, when the program has one.
    roadmap: Option<&'a crate::roadmap_cmd::Loaded>,
    /// OW-WAR-0125: recorded SAS revisions by section, for citations.
    sas_sections: &'a crate::sas::RevisionSections<'a>,
}

fn check_one(
    repo: &Repository,
    one: &Loaded,
    shared: Shared<'_>,
    check_generated: bool,
    report: &mut Report,
) {
    let Shared {
        corpus,
        parent_digests,
        gates,
        ownership,
        roadmap,
        sas_sections,
    } = shared;
    let alias = one.alias();

    // Carry forward whatever loading already found.
    for diagnostic in &one.report.diagnostics {
        report.push(diagnostic.clone());
    }

    let (Some(basis), Some(validated)) = (&one.basis, &one.validated) else {
        // The manifest was invalid; loading already reported why, and every
        // downstream check would be reporting consequences of that one fact.
        return;
    };

    report.push(Diagnostic::pass(
        "manifest.valid",
        format!("{alias}: manifest and composition are well-formed"),
    ));

    check_deliverable_digests(repo, one, &alias, ownership, report);
    check_traceability(repo, one, &alias, roadmap, report);
    {
        // §44.6 recorded runs and the §56.2 record, both held to the contract
        // as it compiles NOW (OW-WAR-0059).
        let current = match (&one.basis, &one.validated) {
            (Some(basis), Some(validated)) => openwarrant_compiler::lower(basis, validated)
                .ok()
                .and_then(|ir| ir.contract_digest().ok()),
            _ => None,
        };
        crate::evidence::check(repo, &one.dir, &alias, current.as_deref(), report);
        crate::resolution_cmd::check(repo, &one.dir, &alias, current.as_deref(), report);
        let uuid = one.validated.as_ref().map(|v| v.uuid.to_string());
        crate::journal_cmd::check(repo, &one.dir, &alias, uuid.as_deref(), report);
        // §14 — the SAS pin must name a recorded revision, and a Warrant pinned
        // behind the latest revision is said so. The pin is the latest
        // amendment's `sas_revision` when one names it (OW-ADR-0016), else the
        // authorization's.
        let all = repo.load_sas_revisions().unwrap_or_default();
        let amended = crate::repo::amendment_sas_revision(&one.dir);
        if let Some((v, amendment_path)) = &amended {
            let file = repo.relative(amendment_path);
            match all.iter().find(|r| &r.version == v) {
                None => report.push(Diagnostic::error(
                    "sas.pin-unknown",
                    file,
                    format!("{alias}: an amendment re-pins to SAS revision {v}, and no record of it exists under docs/sas/revisions/ — `war sas propose {v}` first"),
                )),
                Some(rev) => {
                    // The re-pinned revision must still carry every row this
                    // Warrant implements; a requirement that vanished under it
                    // is a broken trace, not a silent one.
                    for i in &basis.manifest.implements {
                        if let Ok(rq) = openwarrant_core::traceability::RequirementRef::parse(&i.r#ref)
                            && !rev.requirements.contains_key(&rq.canonical())
                        {
                            report.push(Diagnostic::error(
                                "sas.repin-unknown-requirement",
                                file.clone(),
                                format!("{alias}: re-pinned to SAS {v}, whose §106 has no {} — the Warrant implements a requirement that revision does not have", i.r#ref),
                            ));
                        }
                    }
                    if repo.load_resolution(&one.dir).ok().flatten().is_some() {
                        report.push(Diagnostic::warn(
                            "sas.repin-resolved",
                            file,
                            format!("{alias}: re-pinned to SAS {v} after resolution; the resolution binds the contract as it was and is reported stale, never moved (§56.3)"),
                        ));
                    }
                }
            }
        }
        // Is this authorization one a human signed? Until this call existed the
        // answer was "it says so in the file". A forged authorization.toml
        // naming the owner passed `war check` with zero errors and satisfied
        // §56.1 requirement 1 (demonstrated 2026-09-19 against 1.0.0-alpha.1).
        if let Ok(Some(a)) = repo.load_authorization(&one.dir)
            && let Some(auth) = &a.revision.authorization
        {
            {
                let verdict = crate::authority_check::verify(
                    repo,
                    crate::authority_check::Act::Authorize,
                    &alias,
                    &auth.authorizer,
                    Some(&a.revision.contract_digest),
                );
                let at = repo.relative(&one.dir.join("authorization.toml"));
                if verdict.is_signed() {
                    report.push(Diagnostic::pass(
                        verdict.rule(),
                        format!("{alias}: {}", verdict.why()),
                    ));
                } else {
                    report.push(Diagnostic::error(
                        verdict.rule(),
                        at,
                        format!("{alias}: {}", verdict.why()),
                    ));
                }
            }
            // OW-ADR-0029: an authorization made through a standing class is
            // re-derived, never trusted — the class, its signature, the stamp
            // against the class's expiry, count and revocation, and the
            // Warrant as it stands against every term. Removing this call
            // fails `conformance/plants.d/69-standing.sh`.
            crate::standing_cmd::check(repo, one, &a, report);
        }
        // A resolution is the act that says the work is done. It was trusted on
        // content alone for exactly as long as the authorization was.
        if let Ok(Some(r)) = repo.load_resolution(&one.dir) {
            let verdict = crate::authority_check::verify(
                repo,
                crate::authority_check::Act::Resolve,
                &alias,
                r.resolution.resolved_by_ref.trim_start_matches("person://"),
                Some(&r.resolution.contract_digest),
            );
            let at = repo.relative(&one.dir.join("resolution.toml"));
            if verdict.is_signed() {
                report.push(Diagnostic::pass(
                    "authority.signed",
                    format!("{alias} resolution: {}", verdict.why()),
                ));
            } else {
                report.push(Diagnostic::error(
                    verdict.rule(),
                    at,
                    format!("{alias} resolution: {}", verdict.why()),
                ));
            }
        }
        // Each correction moves a delivered file past the wall, so each needs
        // its own signature over its own bytes.
        if let Ok(set) = repo.load_corrections(&one.dir) {
            for (_, c) in &set.records {
                let subject = format!("{alias}.{}", c.correction.deliverable_id);
                let verdict = crate::authority_check::verify(
                    repo,
                    crate::authority_check::Act::Correct,
                    &subject,
                    c.correction
                        .authorized_by_ref
                        .trim_start_matches("person://"),
                    Some(&c.correction.new_digest),
                );
                if verdict.is_signed() {
                    report.push(Diagnostic::pass(
                        "authority.signed",
                        format!("{subject} correction: {}", verdict.why()),
                    ));
                } else {
                    report.push(Diagnostic::error(
                        verdict.rule(),
                        repo.relative(&one.dir.join("corrections")),
                        format!("{subject} correction: {}", verdict.why()),
                    ));
                }
            }
        }
        if let Ok(Some(a)) = repo.load_authorization(&one.dir)
            && let Some(v) = &a.sas_revision
            && amended.is_none()
        {
            if !all.iter().any(|r| &r.version == v) {
                report.push(Diagnostic::error(
                    "sas.pin-unknown",
                    repo.relative(&one.dir.join("authorization.toml")),
                    format!("{alias}: authorized against SAS revision {v}, and no record of it exists under docs/sas/revisions/"),
                ));
            } else if let Some(latest) = repo.latest_sas_revision().ok().flatten()
                && &latest.version != v
            {
                // A resolved Warrant executes nothing further under any
                // Basis; the revision it was accepted under is its history,
                // not a debt. Only a Warrant still open to execution is asked
                // to re-pin (OW-WAR-0112, OW-ADR-0021).
                if repo.load_resolution(&one.dir).ok().flatten().is_some() {
                    report.push(Diagnostic::pass(
                        "sas.pin-historical",
                        format!(
                            "{alias}: resolved under SAS {v}; {} is in force now and asks \
                             nothing of a Warrant that executes no further",
                            latest.version
                        ),
                    ));
                } else {
                    report.push(Diagnostic::warn(
                        "sas.pin-superseded",
                        repo.relative(&one.dir.join("authorization.toml")),
                        format!("{alias}: authorized against SAS {v}; the latest recorded revision is {} — the contract keeps its Basis until an amendment carrying `sas_revision: \"{}\"` re-pins it and a human re-authorizes (OW-ADR-0016)", latest.version, latest.version),
                    ));
                }
            }
        }
    }

    // Ordinals ascending is not required by the SAS, but a manifest whose
    // ordinals descend renders in an order its author probably did not intend.
    let ordinals: Vec<u32> = basis.manifest.atoms.iter().map(|a| a.ordinal).collect();
    let mut sorted = ordinals.clone();
    sorted.sort_unstable();
    if ordinals != sorted {
        report.push(Diagnostic::warn(
            "composition.ordinal-order",
            repo.relative(&one.dir.join("manifest.toml")),
            format!("{alias}: atom ordinals are not in ascending order; the parent renders in declared order"),
        ));
    }

    // §43 / RQ-056: a gate cited by an obligation must resolve to a registered,
    // bindable definition.
    //
    // OW-WAR-0019's Intent records why: in the parent project's corpus, 23 of 94
    // declared gates named a tool, script, or crate that was not in the tree.
    // Nothing read those strings, so nothing noticed.
    for atom in basis.atoms.iter().filter(|a| a.role == "assurance") {
        let text = String::from_utf8_lossy(&atom.bytes);
        let file = repo.relative(&one.dir.join(&atom.source));
        let cited = openwarrant_core::gate::cited_gate_uris(&text);
        let mut resolved = 0usize;
        for uri in &cited {
            match gates.resolve_citation(&alias, uri) {
                Ok(def) if def.lifecycle.is_bindable() => resolved += 1,
                Ok(def) => report.push(Diagnostic::error(

// SPDX-License-Identifier: Apache-2.0
//! `war resolve --dry-run` — evaluate §56.1's thirteen requirements.
//!
//! # Why this is a dry run and nothing else, for now
//!
//! §56.1 lists thirteen things resolution SHALL verify. `ResolutionChecks`
//! implemented all thirteen during alpha as named booleans, each tested to block
//! on its own, and was referenced by no binary. So the thirteen were a struct
//! nothing computed.
//!
//! This computes them from the corpus as it actually is, and reports which
//! block. It deliberately does NOT record a resolution: §56.2's record needs an
//! authorizer, an acting role and a stated meaning, and inventing those to make
//! the command feel complete is the substitution §40.7 forbids.
//!
//! # Where requirement 10 is read from, and why it moved
//!
//! Independence used to be answered from `openwarrant.toml`'s single global
//! `[independence]` block. That was unsound in the dangerous direction: one
//! block set true would make EVERY Warrant claim independence, including ones
//! nothing independent had ever looked at.
//!
//! It is now answered from the verification records attached to the Warrant
//! (`verifications/*.toml`, see [`openwarrant_core::verification`]). Each
//! verification carries the independence its verifier ACTUALLY had, and
//! `admissible_for` refuses self-verification, evidence-free verdicts, and
//! independence below §46.3's minimum for the level. An obligation with no
//! admissible verification does not count as dispositioned.
//!
//! # What is computed
//!
//! All thirteen, from records. None is a constant any more:
//!
//! - deliverables and artifact digests (§37, digests recomputed from the bytes);
//! - obligation dispositions and independence (§46, from verification records);
//! - gate results (§44.5, from persisted Gate Runs);
//! - the authorized contract revision (§28.4), judgments (§42), residual-risk
//!   authority (§36.2 with §27.2) and the resolver's role (§27), through
//!   [`Authority`];
//! - blocking unknowns (§36.3) and runtime receipts (§48.4, §49.3).
//!
//! Two answer `true` structurally: no blocker remains, and deviations are
//! dispositioned. Nothing else defaults to true — an unanswerable requirement is
//! unmet, which is §32's fail-closed rule applied to §56.
//!
//! # Computed is not the same as satisfied
//!
//! Wiring the last of these up closed no Warrant, and was not meant to. Four
//! requirements read records only a human may write: a role assignment in
//! `docs/authority/roles.toml`, then a signed authorization carrying judgments
//! and risk acceptances. §27.2 forbids an agent authorizing a proposed WAR,
//! accepting residual risk, or resolving a delivery, so no implementation here
//! can make those true.
//!
//! What implementation CAN do is make them answerable — turning "a constant says
//! no" into "this specific record is absent", which is a state somebody can act
//! on. That is the whole of the difference.
//!
//! # §38.6 is reported separately, and that separation is load-bearing
//!
//! Requirement 4 asks whether every obligation is *dispositioned*.
//! `not_established` is a disposition, so a Warrant can meet all thirteen while
//! every obligation on record says the claim was not established. See
//! [`would_resolve_satisfied`].
//!
//! # Two citations this file used to get wrong
//!
//! Residual-risk authority is §36.2 with §27.2, not §58 (which is
//! Representations). And the ten §39.3 adequacy warnings `war check` reports are
//! a gap in the REVIEW, not §36.3 blocking unknowns; see
//! [`Authority::no_required_unknown_remains`] for why they are not folded in.
//! Neither error changed a verdict — both were `false` regardless — but each
//! would have sent a reader to the wrong page.

use openwarrant_core::GateRun;
use openwarrant_core::authority::{AuthorityRegister, PolicyResolutionContext};
use openwarrant_core::deliverable::Deliverable;
use openwarrant_core::epistemic::Judgment;
use openwarrant_core::rationale::Assumption;
use openwarrant_core::resolution::{RESOLUTION_REQUIREMENTS, ResolutionChecks};
use openwarrant_core::verification::Verification;

use crate::authorize::AuthorizationRecord;
use crate::diagnostic::{Diagnostic, Report};
use crate::repo::{RepoError, Repository};

/// Compute §56.1's thirteen from the corpus as it stands.
///
/// Each is answered from a record or answered `false`. Nothing is assumed true
/// because it is probably fine — an unanswerable requirement is unmet, which is
/// the same fail-closed rule §32 applies to Preflight.
fn evaluate(
    repo: &Repository,
    one: &crate::repo::Loaded,
    verifications: &[Verification],
    deliverables: &[Deliverable],
    gate_runs: &[GateRun],
    authority: &Authority<'_>,
) -> ResolutionChecks {
    let validated = one.validated.as_ref();
    let basis = one.basis.as_ref();

    let assurance = validated
        .map(|v| v.assurance_level.to_string())
        .unwrap_or_else(|| "basic".to_owned());

    // The obligations this Warrant declares, by id.
    let declared: Vec<String> = basis
        .map(|b| {
            b.atoms
                .iter()
                .filter(|a| a.role == "assurance")
                .filter_map(|a| {
                    openwarrant_core::obligation::parse(&String::from_utf8_lossy(&a.bytes)).ok()
                })
                .flat_map(|set| set.obligations.into_iter().map(|o| o.id))
                .collect()
        })
        .unwrap_or_default();

    // §46.3 is now answered from the verifications that actually happened, not
    // from a project-wide declaration.
    //
    // The global `[independence]` block could only ever be an aspiration: one
    // block set true made EVERY Warrant claim independence, including ones
    // nothing independent had looked at. Independence is a property of a
    // verifier examining a claim, so it is read from the verification record.
    let admissible: Vec<&Verification> = verifications
        .iter()
        .filter(|v| v.admissible_for(&assurance).is_ok())
        .collect();

    // Every declared obligation must carry an ADMISSIBLE verification. A
    // verification that is present but inadmissible (self-verified, evidence-free,
    // or insufficiently independent) counts for nothing, which is the point.
    let obligations_dispositioned = !declared.is_empty()
        && declared
            .iter()
            .all(|id| admissible.iter().any(|v| &v.obligation == id));

    // Independence holds when something was actually verified independently.
    // With no verifications at all this is false, which is correct: nothing
    // independent happened.
    let independence_met = !admissible.is_empty()
        && declared
            .iter()
            .all(|id| admissible.iter().any(|v| &v.obligation == id));

    // Gate citations across this Warrant's assurance atoms (§43.5).
    //
    // Read from declared `- **gate:**` bullets, never by scanning prose for
    // `gate://` — a gate identified by pattern-matching prose is the
    // "string, not a gate" failure §43 exists to end.
    let cited: Vec<String> = basis
        .map(|b| {
            b.atoms
                .iter()
                .filter(|a| a.role == "assurance")
                .flat_map(|a| {
                    openwarrant_core::gate::cited_gate_uris(&String::from_utf8_lossy(&a.bytes))
                })
                .collect()
        })
        .unwrap_or_default();
    let gates_ok = every_required_gate_has_admissible_result(&cited, gate_runs);

    let required_deliverables_exist =
        required_deliverables_exist(&repo.root, deliverables, &declared);
    // Unreadable corrections mean the chain cannot be computed, so requirement
    // 3 is unmet rather than assumed: `correction.unreadable` from `war check`
    // is the diagnostic that names the file.
    let artifact_digests_verify = match repo.load_corrections(&one.dir) {
        Ok(corrections) => artifact_digests_verify(&repo.root, deliverables, &corrections),
        Err(_) => false,
    };

    // Requirement 1 asks for the EXACT authorized revision, and "authorized"
    // means a human signed it. A record that says `authorized` and carries no
    // verifying signature satisfied this requirement until 2026-09-19, which is
    // how a forged authorization.toml could carry a Warrant all the way to a
    // resolution. The digest the signature must bind is the one the record
    // carries, so a signature cannot be moved onto a revision it never saw.
    let authorization_signed = authority.authorization.is_some_and(|record| {
        record.revision.authorization.as_ref().is_some_and(|auth| {
            crate::authority_check::verify(
                repo,
                crate::authority_check::Act::Authorize,
                &one.alias(),
                &auth.authorizer,
                Some(&record.revision.contract_digest),
            )
            .is_signed()
        })
    });

    ResolutionChecks {
        exact_authorized_contract_revision: authority.contract_is_authorized()
            && authorization_signed,
        required_deliverables_exist,
        artifact_digests_verify,
        every_required_obligation_dispositioned: obligations_dispositioned,
        every_required_gate_has_admissible_result: gates_ok,
        no_required_unknown_remains: authority.no_required_unknown_remains(),
        // §53.1: "an unmet condition preventing valid progress". A declared
        // §36.3 blocking unknown is exactly that, so requirement 7 is answered
        // from the same record as requirement 6 and deliberately computes the
        // same thing for now.
        //
        // The duplication is the honest option. §53.1 has its own shape —
        // condition_ref, owner_ref, required_to_unblock — raised during
        // execution, and nothing in this repository can record one. Leaving this
        // as a bare `true` while OW-WAR-0026 and OW-WAR-0040 declare themselves
        // unstartable made requirement 7 a false assertion, and a Warrant scored
        // HIGHER for declaring itself blocked than for declaring a weighable
        // risk. A correct duplicate beats a wrong constant.
        no_blocker_remains: authority.no_required_unknown_remains(),
        deviations_dispositioned: true,
        required_judgments_exist: authority.required_judgments_exist(),
        independence_requirements_met: independence_met,
        residual_risks_have_sufficient_authority: authority.residual_risks_are_covered(),
        runtime_receipts_match_the_basis: runtime_receipts_match_the_basis(basis),
        resolver_holds_the_role: authority.a_resolver_is_eligible(&assurance, &declared),
    }
}

/// Everything §27, §28.4, §42 and §36.2 need, read once from disk.
///
/// Grouped into one type rather than four more parameters because all four
/// requirements are answers to the same question — *who decided this, and were
/// they entitled to* — and splitting them across the call site made it easy to
/// pass one and forget the rest.
pub struct Authority<'a> {
    pub register: &'a AuthorityRegister,
    /// The persisted authorization, if the Warrant has one.
    pub authorization: Option<&'a AuthorizationRecord>,
    /// The contract digest the Warrant compiles to RIGHT NOW. `None` when it
    /// would not compile, which makes requirement 1 unanswerable rather than
    /// satisfied.
    pub current_contract_digest: Option<&'a str>,
    pub judgments: &'a [Judgment],
    /// `None` means no `rationale.toml` — the residual-risk question was never
    /// asked. `Some(&[])` means it was asked and the answer was none. Law 15:
    /// those are different, and only one of them may pass.
    pub assumptions: Option<&'a [Assumption]>,
    /// §27.3 condition 1 — repository policy, set by a human.
    pub policy_allows_automated_resolution: bool,
    /// The actor whose work is being resolved, from [`Repository::performer`].
    ///
    /// Threaded rather than written as a literal here, and the reason is the
    /// direction the two could diverge. §27.3 condition 4 is "performer and
    /// resolver identities are distinct", so this name is what stops an actor
    /// closing its own delivery. A second copy of the string that fell out of
    /// step with `performer()` would not fail loudly — it would compare the
    /// resolver against a name nobody uses any more, find them distinct, and
    /// let the real performer through.
    pub performer: &'a str,
}

impl Authority<'_> {
    /// §56.1 requirement 1 — the EXACT authorized Contract Revision.
    ///
    /// Both halves are load-bearing. A record in any state but `Authorized` is a
    /// proposal, and one whose digest no longer matches the tree authorizes a
    /// revision that has since been edited — the precise failure the word
    /// "exact" exists to catch.
    #[must_use]
    pub fn contract_is_authorized(&self) -> bool {
        let (Some(record), Some(current)) = (self.authorization, self.current_contract_digest)
        else {
            return false;
        };
        crate::authorize::authorizes_current_contract(record, current)
    }

    /// §56.1 requirement 6 — no required unknown remains.
    ///
    /// §36.3 is the record this asks about: an assumption carrying
    /// `epistemic_status: blocking_unknown`, which
    /// [`EpistemicStatus::blocks_readiness`] already identifies. A Warrant
    /// resting on an unresolved blocking unknown may not close, because the
    /// thing it does not know is by its own declaration load-bearing.
    ///
    /// Absent `rationale.toml` is `false`, not vacuously true. The same
    /// asked-versus-unasked rule the residual-risk check applies: a Warrant that
    /// never declared its assumptions has not shown it has no blocking ones, and
    /// Law 15 keeps those two apart.
    ///
    /// # What this deliberately does NOT count
    ///
    /// An earlier comment here read "the adequacy warnings ARE required
    /// unknowns", and that conflated two different things. `war check` reports
    /// ten Warrants whose §39.3 adequacy review executed no attacks — a real gap,
    /// and one worth fixing — but it is a gap in the REVIEW, not an assumption
    /// the Warrant declared it was unsure about. Folding it in here would make
    /// requirement 6 unfixable by the record it names, since resolving it would
    /// mean running attacks rather than resolving an unknown.
    #[must_use]
    pub fn no_required_unknown_remains(&self) -> bool {
        use openwarrant_core::rationale::EpistemicStatus;

        let Some(assumptions) = self.assumptions else {
            return false;
        };
        !assumptions
            .iter()
            .any(|a| a.epistemic_status == EpistemicStatus::BlockingUnknown)
    }

    /// §56.1 requirement 9 — required judgments exist.
    ///
    /// A judgment counts only if it validates AND its author is recorded as
    /// authorized (§42's `require_authorized`). A Warrant needs a judgment for
    /// every residual risk it declares; one that declares none needs none, and
    /// that is a real pass rather than a vacuous one — but only once the
    /// question has been asked, which is what `assumptions.is_some()` records.
    #[must_use]
    pub fn required_judgments_exist(&self) -> bool {
        let Some(assumptions) = self.assumptions else {
            return false;
        };
        let required = crate::authorize::residual_risks_in(assumptions);
        if !self
            .judgments
            .iter()
            .all(|j| j.validate().is_ok() && j.require_authorized().is_ok())
        {
            return false;
        }
        required
            .iter()
            .all(|risk| self.judgments.iter().any(|j| refers_to(j, risk)))
    }

    /// §56.1 requirement 11 — residual risks have SUFFICIENT AUTHORITY.
    ///
    /// Distinct from requirement 9, which only asks whether the judgments exist.
    /// This asks whether the actor who made each one was entitled to accept
    /// organizational residual risk — §27.2 forbids it to agents outright, and
    /// holding `judge` is not holding `risk_acceptor`.
    #[must_use]
    pub fn residual_risks_are_covered(&self) -> bool {
        let Some(assumptions) = self.assumptions else {
            return false;
        };
        crate::authorize::residual_risks_in(assumptions)
            .iter()
            .all(|risk| {
                self.judgments.iter().any(|j| {
                    refers_to(j, risk)
                        && self
                            .register
                            .actor(&j.actor)
                            .is_some_and(|a| a.may_accept_residual_risk().is_ok())
                })
            })
    }

    /// §56.1 requirement 13 — the resolver holds the role.
    ///
    /// Asks the register whether ANY assigned actor could lawfully resolve this
    /// Warrant, given the performer and §27.3's conditions. `false` means nobody
    /// may close it — which is the honest answer for a repository whose role
    /// register is empty, and is why an empty register grants nothing.
    #[must_use]
    pub fn a_resolver_is_eligible(&self, assurance: &str, declared: &[String]) -> bool {
        self.register
            .eligible_resolver(
                self.performer,
                PolicyResolutionContext {
                    policy_allows: self.policy_allows_automated_resolution,
                    assurance_level: assurance,
                    // Conservative on purpose: an obligation is treated as
                    // non-mechanical unless the Warrant declares none at all.
                    // §27.3 lets a policy service close only mechanical work, and
                    // guessing in the permissive direction here would hand a
                    // machine exactly the Warrants it may not touch.
                    all_obligations_mechanical: declared.is_empty(),
                    residual_risk_judgment_required: self
                        .assumptions
                        .is_none_or(|a| !crate::authorize::residual_risks_in(a).is_empty()),
                },
            )
            .is_some()
    }
}

/// OW-ADR-0029 — a Warrant authorized through a standing authorization is
/// never resolved by §27.3's policy service, whatever the repository's policy
/// says: a class carries no resolution term, and the owner's rule is that no
/// resolution is automatic. `Some(why)` when `resolver` is a registered actor
/// that is not a human and the Warrant's authorization names a class; `None`
/// otherwise (an unknown resolver is refused by name elsewhere).
///
/// # Errors
/// When the authorization or the register will not read.
pub fn standing_needs_human(
    repo: &Repository,
    dir: &camino::Utf8Path,
    resolver: &str,
) -> Result<Option<String>, RepoError> {
    let Some(basis) = covered_basis(repo, dir)? else {
        return Ok(None);
    };
    let register = repo.load_authority_register()?;
    Ok(register
        .actor(resolver)
        .filter(|a| a.actor_kind != openwarrant_core::authority::ActorKind::Human)
        .map(|a| {
            format!(
                "{resolver:?} is {} and this Warrant was authorized under the standing \
                 authorization {basis}. A covered Warrant is resolved by a human, always: a \
                 class carries no resolution term, and §27.3's policy-service path does not \
                 apply to it whatever `policy.allow_automated_resolution` says",
                a.actor_kind
            )
        }))
}

/// The `standing://` reference a Warrant's authorization records, if any.
fn covered_basis(repo: &Repository, dir: &camino::Utf8Path) -> Result<Option<String>, RepoError> {
    Ok(repo.load_authorization(dir)?.and_then(|a| {
        a.revision
            .authorization
            .and_then(|x| x.policy_basis)
            .filter(|b| b.starts_with(openwarrant_core::standing::SCHEME))
    }))
}

/// Whether a judgment addresses a given residual risk.
///
/// Matched through the assumption's own `judgment_ref` when it declares one, and
/// otherwise through the judgment's `basis_refs`. Both directions are checked
/// because §36.2 points assumption→judgment while §42 points judgment→basis, and
/// a record written from either side must be readable from the other.
fn refers_to(judgment: &Judgment, risk: &crate::authorize::RequestedResidualRisk) -> bool {
    let by_ref = !risk.judgment_ref.is_empty()
        && (risk.judgment_ref == judgment.id
            || risk.judgment_ref == format!("judgment://{}", judgment.id));
    let by_basis = judgment
        .basis_refs
        .iter()
        .any(|b| b == &risk.assumption_id || b == &format!("assumption://{}", risk.assumption_id));
    by_ref || by_basis
}

/// §56.1 — every gate a required obligation cites must have an admissible result.
///
/// "Admissible" is §44.5's conjunction, already modelled as
/// [`GateRun::satisfies_required_pass`]: askable AND completed AND pass. An
/// unaskable gate cannot pass (SAS §99 criterion 19), and a run that timed out
/// is a blocking unknown rather than a failure (RQ-054).
///
/// A cited gate with NO recorded run is unmet, not vacuously satisfied. That is
/// the whole point: the gate must have been asked, not merely referenced.
///
/// # Zero cited gates is UNMET, and this comment used to say the opposite
///
/// The prose here claimed "obligations citing no gate impose nothing — the
/// requirement is about gates that were cited", while the code below has always
/// returned `false` for an empty list. One of them was wrong, and it was the
/// prose: a reader trusting it would conclude a Warrant citing no gate had
/// passed requirement 5, when it had failed.
///
/// The code is kept. §56.1 asks whether every required gate has an admissible
/// result, and a Warrant that names no gate has produced no mechanical proof of
/// anything — reporting that as satisfied would let a Warrant clear the
/// requirement by declaring nothing, which is the shape of false completion this
/// resolver exists to refuse. It is the same rule
/// [`required_deliverables_exist`] applies to a Warrant that declares no
/// deliverables.
///
/// The consequence is real and is not a defect: OW-WAR-0001 through 0018 were
/// authored before the Gate Registry existed, cite no gates, and therefore
/// cannot satisfy requirement 5. Adding gate bullets to their assurance atoms
/// now would move the contract digest and would be editing a document to make a
/// tool go green. It needs an amendment somebody authorizes, not a quiet edit.
#[must_use]
pub fn every_required_gate_has_admissible_result(cited_uris: &[String], runs: &[GateRun]) -> bool {
    if cited_uris.is_empty() {
        return false;
    }
    cited_uris.iter().all(|uri| {
        let key = uri.trim_start_matches("gate://");
        runs.iter()
            .any(|r| r.gate == key && r.satisfies_required_pass())
    })
}

/// §56.1 requirement 12 — runtime receipts match the basis.
///
/// # Which stages this is actually about
///
/// §48.4 is a clause of §48, *Katana integration*: "Katana SHALL return, at
/// minimum: session identity, Dispatch digest, PromptIR digest, ... receipt
/// digest." §49.3 gives BLUT the equivalent duty for its own lineage. Those two
/// are the executors that return receipts.
///
/// A `human`, `agent` or `service` stage does not produce a §48.4 receipt. It
/// submits through §47's Stage Submission, which is a different record with a
/// different shape, and demanding a runtime receipt from a person would make
/// this requirement permanently unmeetable for the ordinary case.
///
/// So a Warrant that dispatches nothing to a runtime has no receipts to match,
/// and that is a genuine pass rather than a vacuous one: the milestones atom is
/// REQUIRED by the delivery profile, so the question was always asked, and the
/// answer "no runtime stages" is recorded in the contract itself.
///
/// # Where this is strict
///
/// A Warrant with a `katana` or `blut` stage needs a receipt, and none exists
/// anywhere in this repository — Katana has no checkout and nothing has been
/// dispatched. Those Warrants report unmet, which is correct.
///
/// Reading the executor kind from the atom is safe because the atom is part of
/// the Compilation Basis: mis-declaring a Katana stage as `human` to dodge this
/// would change the contract digest, and is a false declaration rather than a
/// hole in this check.
///
/// A Warrant whose milestones atom will not parse is unmet, not exempt.
#[must_use]
pub fn runtime_receipts_match_the_basis(
    basis: Option<&openwarrant_compiler::CompilationBasis>,
) -> bool {
    use openwarrant_core::milestones::ExecutorKind;

    let Some(basis) = basis else {
        return false;
    };
    let atoms: Vec<_> = basis
        .atoms
        .iter()
        .filter(|a| a.role == "milestones")
        .collect();
    if atoms.is_empty() {
        // The profile requires one. Its absence means the Warrant did not
        // compile as claimed, and an unanswerable requirement is unmet.
        return false;
    }

    let mut runtime_stages = 0usize;
    for atom in atoms {
        // `from_utf8`, not `from_utf8_lossy`. Lossy decoding replaces invalid
        // bytes with U+FFFD, which can turn bytes that described a katana stage
        // into YAML that parses cleanly and describes no runtime stage at all —
        // a silent pass in the one direction that matters. Invalid UTF-8 lands
        // in the same place as unparseable YAML: unmet.
        let Ok(text) = std::str::from_utf8(&atom.bytes) else {
            return false;
        };
        let Ok(graph) = openwarrant_core::milestones::parse(text) else {
            return false;
        };
        runtime_stages += graph
            .stages
            .iter()
            .filter(|s| matches!(s.executor_kind, ExecutorKind::Katana | ExecutorKind::Blut))
            .count();
    }

    // No receipt store exists yet, so any runtime stage is unmet. Written as a
    // comparison rather than `runtime_stages == 0` so that wiring receipts in
    // later is a change to this one expression.
    runtime_stages == 0
}

/// §38.6 — would this resolve SATISFIED, given the dispositions on record?
///
/// # This is a different question from §56.1's thirteen, and conflating them
/// # manufactures a false completion
///
/// Requirement 4 asks whether every obligation is *dispositioned*. A verdict of
/// `not_established` IS a disposition, so it satisfies requirement 4 — correctly:
/// §38.5 is about whether the question was answered, not about the answer.
///
/// Nothing in §56.1 then asks what the answers WERE. So a Warrant could meet all
/// thirteen requirements while every one of its obligations came back
/// `not_established`, and a resolver reading only the thirteen would call it
/// ready to close. §38.6 is the clause that stops this: a delivery resolves
/// satisfied only when every required obligation is established, or accepted
/// with residual risk under sufficient authority.
///
/// [`Disposition::permits_satisfied`] and [`ObligationSet::aggregate`] both
/// modelled this from the start and no binary called either — the same "a
/// function nothing computed" shape this module documents about itself. It is
/// computed here, from the ADMISSIBLE verifications rather than from the atom,
/// because an inadmissible verdict must not contribute to an outcome any more
/// than it contributes to a disposition.
///
/// `None` means the question cannot be answered yet: some obligation has no
/// admissible verdict at all. That is neither satisfied nor unsatisfied, which
/// is Law 15 — Unknown is neither failure nor pass.
#[must_use]
pub fn would_resolve_satisfied(declared: &[String], admissible: &[&Verification]) -> Option<bool> {
    if declared.is_empty() {
        return None;
    }
    let mut all_permit = true;
    for id in declared {
        let verdict = admissible.iter().find(|v| &v.obligation == id)?;
        if !verdict.disposition.permits_satisfied() {
            all_permit = false;
        }
    }
    Some(all_permit)
}

/// §37 — a required deliverable exists when it VALIDATES and its target is
/// actually present.
///
/// Validation alone would accept a record pointing at a file nobody produced,
/// which is precisely the claim this requirement exists to test. Zero required
/// deliverables is `false`, not vacuously true: a Warrant that declares nothing
/// has not shown that anything was delivered.
#[must_use]
pub fn required_deliverables_exist(
    root: &camino::Utf8Path,
    deliverables: &[Deliverable],
    declared_obligations: &[String],
) -> bool {
    let required: Vec<&Deliverable> = deliverables.iter().filter(|d| d.required).collect();
    !required.is_empty()
        && required
            .iter()
            .all(|d| d.validate(declared_obligations).is_ok() && root.join(&d.target_ref).exists())
}

/// §37.2 — a content-addressed deliverable's recorded digest must match the
/// bytes on disk.
///
/// A digest that is merely PRESENT proves nothing, so this RECOMPUTES it from
/// the file. A deliverable claiming content addressing whose target cannot be
/// read fails rather than being skipped — an unreadable artifact is not a
/// verified one.
#[must_use]
pub fn artifact_digests_verify(
    root: &camino::Utf8Path,
    deliverables: &[Deliverable],
    corrections: &crate::repo::CorrectionSet,
) -> bool {
    let addressed: Vec<&Deliverable> = deliverables
        .iter()
        .filter(|d| d.content_addressed)
        .collect();
    !addressed.is_empty()
        && addressed.iter().all(|d| {
            let Some(p) = d.provenance.as_ref() else {
                return false;
            };
            // The digest the deliverable OUGHT to have is the head of its
            // correction chain, not the one the manifest first pinned. §34.4
            // supersedes; it does not erase. Reading only the manifest made
            // this requirement unanswerable for every corrected file — `war
            // check` printed `deliverable.corrected` while requirement 3 read
            // unmet for the same bytes — so the chain is read here from the
            // same `chain_head` the check uses.
            let (_, head) = crate::correct::head_for(corrections, &d.id, &p.content_digest);
            // A broken chain is not a verified digest: fail closed, and let
            // `war check`'s correction rules say which link is wrong.
            let Ok(head) = head else {
                return false;
            };
            let want = head.trim_start_matches("sha256:");
            match std::fs::read(root.join(&d.target_ref)) {
                Ok(bytes) => openwarrant_compiler::sha256_hex(&bytes) == want,
                Err(_) => false,
            }
        })
}

/// Everything `war resolve` computes for one Warrant, before any diagnostic is
/// written.
///
/// Extracted so the corpus projection (`war status`) and `war resolve` compute
/// from ONE function. Two implementations of the thirteen would be two places
/// for them to disagree, and the projection would be the one nobody re-checked.
#[derive(Debug, Clone)]
pub struct Assessment {
    /// The digest the Warrant compiles to now; `None` when it will not compile.
    pub current_contract_digest: Option<String>,
    pub checks: ResolutionChecks,
    /// §38.6 — beside the thirteen, never folded in.
    pub would_resolve_satisfied: Option<bool>,
    /// Obligation ids with an admissible verification that permits satisfaction.
    pub established: Vec<String>,
    /// Obligation ids on record as not established or refuted.
    pub unestablished: Vec<String>,
    /// §36.3 blocking unknowns, by assumption id.
    pub blocking_unknowns: Vec<String>,
    /// Repository-relative paths of the admissible verification records.
    pub evidence_refs: Vec<String>,
    pub deliverable_failures: Vec<(String, String)>,
    pub verification_failures: Vec<(String, String)>,
}

/// Compute §56.1's thirteen and §38.6 for one loaded Warrant, reading gate
/// runs from the receipts path.
///
/// This is what `war resolve` calls. It is a LOCAL question — "what do the
/// records on this machine say?" — and the receipts under `docs/receipts/`
/// are part of that, gitignored or not.
pub fn assess(repo: &Repository, one: &crate::repo::Loaded) -> Result<Assessment, RepoError> {
    let evidence = crate::evidence::load(repo, &one.dir)?;
    assess_with(repo, one, &evidence)
}

/// The gate keys (`<id>@<version>`, no scheme) a Warrant's assurance atoms cite.
#[must_use]
pub fn cited_gate_keys(one: &crate::repo::Loaded) -> Vec<String> {
    one.basis
        .as_ref()
        .map(|b| {
            b.atoms
                .iter()
                .filter(|a| a.role == "assurance")
                .flat_map(|a| {
                    openwarrant_core::gate::cited_gate_uris(&String::from_utf8_lossy(&a.bytes))
                })
                .map(|u| u.trim_start_matches("gate://").to_owned())
                .collect()
        })
        .unwrap_or_default()
}

/// Assess against an explicit set of recorded runs.
///
/// Requirement 5 reads ONLY a Warrant's own committed `gate-runs/` — never the
/// gitignored receipts path — so the corpus projection and `war resolve` answer
/// the same question from the same tracked inputs, and a fresh clone reproduces
/// both. A run counts only when its receipt reseals and is bound to the
/// contract as it compiles now (`evidence::admissibility`).
pub fn assess_with(
    repo: &Repository,
    one: &crate::repo::Loaded,
    evidence: &[crate::evidence::GateEvidence],
) -> Result<Assessment, RepoError> {
    let dir = &one.dir;
    let verifications = repo.load_verifications(dir)?;
    let deliverables = repo.load_deliverables(dir)?;

    let performer = repo.performer();
    let mut register = repo.load_authority_register()?;
    // OW-ADR-0029: requirement 13 for a covered Warrant asks whether a HUMAN
    // may resolve it; a policy service never may.
    if covered_basis(repo, dir)?.is_some() {
        register
            .assignments
            .retain(|a| a.actor_kind == openwarrant_core::authority::ActorKind::Human);
    }
    let authorization = repo.load_authorization(dir)?;
    let judgments = repo.load_judgments(dir)?;
    let assumptions = repo.load_rationale(dir)?;
    // The digest the Warrant compiles to right now, which requirement 1 compares
    // the signature against. A Warrant that will not compile yields `None`, and
    // requirement 1 is then unanswerable rather than satisfied.
    let current_contract_digest = match (&one.basis, &one.validated) {
        (Some(basis), Some(validated)) => openwarrant_compiler::lower(basis, validated)
            .ok()
            .and_then(|ir| ir.contract_digest().ok()),
        _ => None,
    };
    let authority = Authority {
        register: &register,
        authorization: authorization.as_ref(),
        current_contract_digest: current_contract_digest.as_deref(),
        judgments: &judgments,
        assumptions: assumptions.as_deref(),
        policy_allows_automated_resolution: repo.config.policy.allow_automated_resolution,
        performer: &performer,
    };

    let gate_runs = crate::evidence::admissible_runs(evidence, current_contract_digest.as_deref());
    let checks = evaluate(
        repo,
        one,
        &verifications.records,
        &deliverables.records,
        &gate_runs,
        &authority,
    );

    // §38.6, reported alongside the thirteen and never folded into them. See
    // `would_resolve_satisfied` for why these are different questions.
    let assurance = one
        .validated
        .as_ref()
        .map(|v| v.assurance_level.to_string())
        .unwrap_or_else(|| "basic".to_owned());
    let declared = declared_obligations(one);
    let admissible: Vec<&Verification> = verifications
        .records
        .iter()
        .filter(|v| v.admissible_for(&assurance).is_ok())
        .collect();
    let would_resolve_satisfied = would_resolve_satisfied(&declared, &admissible);
    let mut established = Vec::new();
    let mut unestablished = Vec::new();
    for id in &declared {
        if let Some(v) = admissible.iter().find(|v| &v.obligation == id) {
            if v.disposition.permits_satisfied() {
                established.push(id.clone());
            } else {
                unestablished.push(id.clone());
            }
        }
    }
    let evidence_refs: Vec<String> = admissible
        .iter()
        .map(|v| {
            repo.relative(
                &dir.join("verifications")
                    .join(format!("{}.toml", v.obligation)),
            )
        })
        .collect();
    let blocking_unknowns: Vec<String> = assumptions
        .as_deref()
        .unwrap_or(&[])
        .iter()
        .filter(|a| {
            a.epistemic_status == openwarrant_core::rationale::EpistemicStatus::BlockingUnknown
        })
        .map(|a| a.id.clone())
        .collect();

    Ok(Assessment {
        current_contract_digest,
        checks,
        would_resolve_satisfied,
        established,
        unestablished,
        blocking_unknowns,
        evidence_refs,
        deliverable_failures: deliverables.failures,
        verification_failures: verifications.failures,
    })
}

/// `war resolve <alias> --dry-run`.
pub fn run(repo: &Repository, alias: &str) -> Result<Report, RepoError> {
    let dir = repo.warrant_dir(alias)?;
    let one = repo.load_warrant(&dir)?;
    let mut report = Report::default();

    let assessment = assess(repo, &one)?;
    for (path, why) in &assessment.deliverable_failures {
        report.push(Diagnostic::error(
            "deliverables.malformed",
            path.clone(),
            format!("{why} — an unreadable deliverables file is not an absent one"),
        ));
    }
    for (path, why) in &assessment.verification_failures {
        report.push(Diagnostic::error(
            "verification.malformed",
            path.clone(),
            format!("{why} — an unreadable verification is not an absent one"),
        ));
    }
    let checks = assessment.checks;
    let outcome = assessment.would_resolve_satisfied;

    // OW-ADR-0021: requirement 3 reads exactly as before — the bytes either
    // are what this Warrant pinned or they are not. But when they are not
    // BECAUSE a later authorized Warrant declares the path, "not established"
    // sends the reader to restore a file that is now someone else's. Name the
    // owner, and the act that fits: this Warrant was never resolved against
    // this pin, so the pin is out of date, and a refresh records what it
    // delivered as the tree stands under whose authority.
    if !checks.artifact_digests_verify
        && let Ok(set) = repo.load_deliverables(&dir)
        && let Ok(ownership) = crate::ownership::Ownership::index(repo)
    {
        let corrections = repo.load_corrections(&dir).unwrap_or_default();
        let authorized_at = repo
            .load_authorization(&dir)
            .ok()
            .flatten()
            .and_then(|a| a.revision.authorization.map(|x| x.effective_time));
        for d in set.records.iter().filter(|d| d.content_addressed) {
            let Some(p) = d.provenance.as_ref() else {
                continue;
            };
            let (_, head) = crate::correct::head_for(&corrections, &d.id, &p.content_digest);
            let Ok(head) = head else {
                continue;
            };
            let want = head.trim_start_matches("sha256:");
            let unchanged = std::fs::read(repo.root.join(&d.target_ref))
                .is_ok_and(|b| openwarrant_compiler::sha256_hex(&b) == want);
            if unchanged {
                continue;
            }
            if let Some(newer) =
                ownership.newer_than(&d.target_ref, alias, authorized_at.as_deref())
            {
                report.push(Diagnostic::warn(
                    "resolution.deliverable-moved",
                    repo.relative(&dir.join("deliverables.toml")),
                    format!(
                        "{alias}: {} → {} no longer carries the bytes this Warrant pinned; \
                         {}/{} (authorized {}) governs that path now. Requirement 3 stays \
                         unmet as written, and nothing here is drift: no resolution binds \
                         this pin, so `war pins --refresh --alias {alias}` records the bytes \
                         as they stand and the resolution then says what was delivered under \
                         whose authority (OW-ADR-0021)",
                        d.id, d.target_ref, newer.alias, newer.deliverable_id, newer.authorized_at
                    ),
                ));
            }
        }
    }
    let unestablished: Vec<&str> = assessment
        .unestablished
        .iter()
        .map(String::as_str)
        .collect();

    let unmet = checks.unmet();

    if unmet.is_empty() {
        report.push(Diagnostic::pass(
            "resolution.requirements",
            format!(
                "{alias}: all {} §56.1 requirements are met",
                RESOLUTION_REQUIREMENTS.len()
            ),
        ));
        report.note(
            "All thirteen are met, but no resolution has been RECORDED. §56.2's record \
             needs an authorizer, an acting role, and a stated meaning — none of which \
             this command may invent."
                .to_owned(),
        );
        push_outcome(&mut report, alias, outcome, &unestablished);
        return Ok(report);
    }

    // Each unmet requirement is named. "9 of 13" tells a reader nothing about
    // whether to worry; the names tell them what to fix.
    for (group, requirement, met) in checks
        .as_pairs()
        .into_iter()
        .map(|(name, met)| ("§56.1", name, met))
    {
        if met {
            report.push(Diagnostic::pass(
                "resolution.requirement-met",
                format!("{alias}: {group} {requirement}"),
            ));
        } else {
            report.push(Diagnostic::unknown(
                "resolution.requirement-unmet",
                repo.relative(&dir.join("manifest.toml")),
                format!("{alias}: {group} {requirement} — not established"),
            ));
        }
    }

    report.note(format!(
        "{} of {} §56.1 requirements are unmet, so {alias} cannot be resolved. That is \
         the correct outcome, not a defect: closing a Warrant while independence is \
         absent and no authorization record exists would manufacture the false \
         completion this system exists to prevent.",
        unmet.len(),
        RESOLUTION_REQUIREMENTS.len()
    ));
    push_outcome(&mut report, alias, outcome, &unestablished);
    Ok(report)
}

/// The obligation ids a Warrant declares, as the parser reads them.
pub fn declared_obligations(one: &crate::repo::Loaded) -> Vec<String> {
    one.basis
        .as_ref()
        .map(|b| {
            b.atoms
                .iter()
                .filter(|a| a.role == "assurance")
                .filter_map(|a| {
                    openwarrant_core::obligation::parse(&String::from_utf8_lossy(&a.bytes)).ok()
                })
                .flat_map(|set| set.obligations.into_iter().map(|o| o.id))
                .collect()
        })
        .unwrap_or_default()
}

/// Report §38.6 as its own line, never folded into the thirteen.
///
/// A Warrant meeting all thirteen requirements with an obligation on record as
/// `not_established` is READY to be resolved and would resolve NOT SATISFIED.
/// Printing only "all thirteen met" would let a reader take the first half of
/// that sentence for the whole of it.
fn push_outcome(report: &mut Report, alias: &str, outcome: Option<bool>, unestablished: &[&str]) {
    match outcome {
        Some(true) => report.push(Diagnostic::pass(
            "resolution.outcome",
            format!("{alias}: §38.6 every required obligation is established or accepted"),
        )),
        Some(false) => report.note(format!(
            "§38.6: {alias} would resolve NOT SATISFIED even once the §56.1 \
             requirements are met. {} obligation(s) are on record as not established \
             or refuted: {}. A disposition is not an establishment — requirement 4 \
             asks whether the question was answered, and §38.6 asks what the answer \
             was.",
            unestablished.len(),
            unestablished.join(", ")
        )),
        None => report.note(format!(
            "§38.6: whether {alias} would resolve satisfied is UNKNOWN — at least one \
             declared obligation has no admissible verification. Unknown is neither \
             failure nor pass (Law 15)."
        )),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use camino::Utf8PathBuf;
    use openwarrant_core::deliverable::{ArtifactProvenance, DeliverableKind};

    fn scratch(label: &str) -> Utf8PathBuf {
        let mut p = Utf8PathBuf::from_path_buf(std::env::temp_dir()).expect("utf-8 temp");
        p.push(format!("ow-deliv-{label}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&p);
        std::fs::create_dir_all(&p).expect("scratch");
        p
    }

    fn provenance(digest: &str) -> ArtifactProvenance {
        ArtifactProvenance {
            producer: "p".into(),
            producing_attempt: "a".into(),
            contract_digest: "c".into(),
            input_digests: vec![],
            tool_or_runtime_identity: "t".into(),
            creation_method: "authored".into(),
            content_digest: digest.into(),
            media_type: "text/plain".into(),
            classification: "internal".into(),
            retention: "r".into(),
            source_holder: "git".into(),
        }
    }

    fn deliverable(target: &str, digest: Option<&str>) -> Deliverable {
        Deliverable {
            id: "D-001".into(),
            title: "t".into(),
            kind: DeliverableKind::File,
            target_ref: target.into(),
            required: true,
            content_addressed: digest.is_some(),
            provenance_required: digest.is_some(),
            obligation_refs: vec![],
            provenance: digest.map(provenance),
        }
    }

    fn gate_run(gate: &str, askability: &str, status: &str, verdict: &str) -> GateRun {
        toml::from_str(&format!(
            "id = \"GR-1\"\ngate = \"{gate}\"\naskability = \"{askability}\"\n\
             execution_status = \"{status}\"\nverdict = \"{verdict}\"\n"
        ))
        .expect("valid run")
    }

    const GATE: &str = "software.repo.war-check@1.0.0";

    #[test]
    fn a_cited_gate_with_an_askable_completed_pass_is_admissible() {
        let runs = vec![gate_run(GATE, "askable", "completed", "pass")];
        assert!(every_required_gate_has_admissible_result(
            &[format!("gate://{GATE}")],
            &runs
        ));
    }

    /// SAS §99 criterion 19: unaskable gates cannot pass. A run claiming
    /// `not_askable` with verdict `pass` is incoherent and must not satisfy
    /// anything — checking the verdict first is how such a run slips through.
    #[test]
    fn an_unaskable_gate_cannot_pass() {
        let runs = vec![gate_run(GATE, "not_askable", "completed", "pass")];
        assert!(!every_required_gate_has_admissible_result(
            &[format!("gate://{GATE}")],
            &runs
        ));
    }

    #[test]
    fn a_failing_or_unknown_verdict_is_not_admissible() {
        for verdict in ["fail", "unknown"] {
            let runs = vec![gate_run(GATE, "askable", "completed", verdict)];
            assert!(
                !every_required_gate_has_admissible_result(&[format!("gate://{GATE}")], &runs),
                "verdict {verdict} must not satisfy a required pass"
