// ---------------------------------------------------------------------------
// `war init` as a conversation — the line front end (OW-WAR-0112 M4).
// ---------------------------------------------------------------------------

/// `war init` with no `--namespace`, at a terminal. Drives `guided::Machine`
/// with what the human types; applies each `Effect`; re-reads the tree.
///
/// The invariants the machine cannot hold are held here: the terminal gate
/// (`sign::at_a_terminal()`, checked by the caller and again before any
/// write), and write-once — an authority file that exists is never touched,
/// whatever was answered.
pub fn guided(root: Option<Utf8PathBuf>, program_hint: Option<&str>) -> Result<(), InitError> {
    let root = match root {
        Some(r) => r,
        None => {
            Utf8PathBuf::from_path_buf(std::env::current_dir().map_err(|source| InitError::Io {
                context: "could not read the current directory".to_owned(),
                source,
            })?)
            .map_err(|_| InitError::NonUtf8Path)?
        }
    };
    if !root.is_dir() {
        return Err(InitError::RootMissing { path: root });
    }
    let io = |context: String| move |source: std::io::Error| InitError::Io { context, source };
    let now = {
        let secs = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |d| d.as_secs());
        crate::gate_cmd::receipt::rfc3339_from_secs(secs)
    };
    let mut m = guided::Machine::new(guided::Facts::read(&root), now);
    let resumed = m.step != guided::Step::Program;
    println!("war init — setting up {}", root);
    if resumed {
        println!("resuming at: {}", m.step.title());
    }
    loop {
        use guided::{Answer, Effect, Step};
        println!();
        println!("{}", m.question());
        if m.step == Step::Done {
            return Ok(());
        }
        let answer = match m.step {
            Step::Program => {
                let default = program_hint
                    .map(str::to_owned)
                    .or_else(|| root.file_name().map(str::to_owned))
                    .unwrap_or_default();
                let Some(name) = ask(&format!("  program name [{default}]: "))? else {
                    return Ok(());
                };
                let name = if name.is_empty() { default } else { name };
                let Some(namespace) = ask("  namespace (A–Z): ")? else {
                    return Ok(());
                };
                Answer::Program {
                    name,
                    namespace: namespace.to_ascii_uppercase(),
                }
            }
            Step::Baseline => {
                let proposed = m.facts.head.clone().unwrap_or_default();
                let Some(named) = ask(&format!("  baseline commit [{proposed}]: "))? else {
                    return Ok(());
                };
                Answer::Baseline(named)
            }
            Step::Signer => {
                let git_name = git_user_name();
                let Some(name) = ask(&format!(
                    "  your name [{}]: ",
                    git_name.as_deref().unwrap_or("")
                ))?
                else {
                    return Ok(());
                };
                let name = if name.is_empty() {
                    git_name.unwrap_or_default()
                } else {
                    name
                };
                let default_principal: String = name
                    .to_ascii_lowercase()
                    .chars()
                    .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
                    .collect();
                let Some(principal) =
                    ask(&format!("  principal, no spaces [{default_principal}]: "))?
                else {
                    return Ok(());
                };
                let principal = if principal.is_empty() {
                    default_principal
                } else {
                    principal
                };
                let keys = loaded_keys();
                if keys.is_empty() {
                    println!(
                        "  (`ssh-add -L` lists no keys; paste one as `<keytype> <base64> [comment]`)"
                    );
                } else {
                    for (i, k) in keys.iter().enumerate() {
                        println!("  [{}] {}", i + 1, shorten(k));
                    }
                }
                let Some(pick) = ask("  which key (number, or paste a line): ")? else {
                    return Ok(());
                };
                let key = match pick.parse::<usize>() {
                    Ok(n) if n >= 1 && n <= keys.len() => keys[n - 1].clone(),
                    _ => pick,
                };
                Answer::Signer {
                    name,
                    principal,
                    key,
                }
            }
            Step::KeyLoaded => {
                let Some(a) = ask("  loaded with -c? [y/N]: ")? else {
                    return Ok(());
                };
                Answer::KeyLoaded(yes(&a))
            }
            Step::Sas | Step::Authorize => {
                let Some(a) = ask("  go ahead? [Y/n]: ")? else {
                    return Ok(());
                };
                if !a.is_empty() && !yes(&a) {
                    println!("stopped; run `war init` again to resume here");
                    return Ok(());
                }
                Answer::Proceed
            }
            Step::SignSas | Step::SignAuthorize => {
                let Some(a) = ask("  sign now? [y/N]: ")? else {
                    return Ok(());
                };
                Answer::SignNow(yes(&a))
            }
            Step::Done => unreachable!("handled above"),
        };
        let effects = match m.answer(answer) {
            Ok(e) => e,
            Err(why) => {
                println!("  refused: {why}");
                continue;
            }
        };
        for effect in effects {
            match effect {
                Effect::Scaffold { program, namespace } => {
                    // The baseline is the next question, not a default.
                    run_program_with(&program, &namespace, Some(root.clone()), Baseline::Deferred)?;
                }
                Effect::Adopt { baseline } => match adopt(&root, &baseline) {
                    Ok(Some(id)) => {
                        println!(
                            "  recorded [adoption] baseline = {id}: nothing up to it is claimed, \
                             owned or verified by any Warrant"
                        );
                        for dir in adr_dirs(&root) {
                            println!("  {}", migrate_line(dir, Some(&id)));
                        }
                    }
                    Ok(None) => println!("  [adoption] is already recorded — left untouched"),
                    // Refused: the tree is unchanged, so the step asks again.
                    Err(why @ InitError::Baseline { .. }) => println!("  refused: {why}"),
                    Err(other) => return Err(other),
                },
                Effect::Write { path, text } => {
                    // The two gates the machine cannot hold: a terminal, and
                    // write-once. Both are checked at the write, not before
                    // the questions, so a pipe that got this far still
                    // writes nothing.
                    if !crate::sign::at_a_terminal() {
                        return Err(InitError::Io {
                            context: format!("{path}: written only from answers at a terminal"),
                            source: std::io::Error::other("no terminal"),
                        });
                    }
                    let full = root.join(&path);
                    if full.exists() {
                        println!("  {path} exists — left untouched (a tool writes it once)");
                        continue;
                    }
                    println!("\n--- {path} ---\n{text}--- end ---");
                    let Some(ok) = ask(&format!("  write {path}? [Y/n]: "))? else {
                        return Ok(());
                    };
                    if !ok.is_empty() && !yes(&ok) {
                        println!("  not written");
                        continue;
                    }
                    if let Some(parent) = full.parent() {
                        fs::create_dir_all(parent)
                            .map_err(io(format!("could not create {parent}")))?;
                    }
                    fs::write(&full, text).map_err(io(format!("could not write {full}")))?;
                    println!("  wrote {path}");
                }
                Effect::ProposeSas { version } => {
                    child(&root, &["sas", "propose", &version])?;
                }
                Effect::Sign { target } => {
                    println!("  running: war sign {target} --ssh-sign");
                    child(&root, &["sign", &target, "--ssh-sign"])?;
                }
                Effect::Prepare { alias } => {
                    child(&root, &["check", &alias])?;
                    child(&root, &["compile"])?;
                    child(&root, &["authorize", &alias])?;
                    m.prepared();
                }
                Effect::Say(text) => println!("{text}"),
            }
        }
        let facts = guided::Facts::read(&root);
        m.observe(facts);
    }
}

/// One line from the human. `None` is end of input: a closed stdin stops the
/// conversation rather than spinning on empty answers.
fn ask(text: &str) -> Result<Option<String>, InitError> {
    use std::io::Write;
    let mut out = std::io::stdout();
    out.write_all(text.as_bytes())
        .and_then(|()| out.flush())
        .map_err(|source| InitError::Io {
            context: "could not write the prompt".to_owned(),
            source,
        })?;
    let mut line = String::new();
    let read = std::io::stdin()
        .read_line(&mut line)
        .map_err(|source| InitError::Io {
            context: "could not read the answer".to_owned(),
            source,
        })?;
    if read == 0 {
        println!();
        return Ok(None);
    }
    Ok(Some(line.trim().to_owned()))
}

fn yes(a: &str) -> bool {
    matches!(a.trim().to_ascii_lowercase().as_str(), "y" | "yes")
}

/// `git config user.name`, when git and a name exist; the default answer,
/// never the recorded one.
fn git_user_name() -> Option<String> {
    let out = std::process::Command::new("git")
        .args(["config", "user.name"])
        .output()
        .ok()?;
    let s = String::from_utf8_lossy(&out.stdout).trim().to_owned();
    (out.status.success() && !s.is_empty()).then_some(s)
}

/// `ssh-add -L`: every loaded public key, one per line, in exactly the shape
/// `allowed_signers` wants after the principal.
fn loaded_keys() -> Vec<String> {
    std::process::Command::new("ssh-add")
        .arg("-L")
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| {
            String::from_utf8_lossy(&o.stdout)
                .lines()
                .map(str::trim)
                .filter(|l| l.starts_with("ssh-") || l.starts_with("sk-"))
                .map(str::to_owned)
                .collect()
        })
        .unwrap_or_default()
}

fn shorten(key: &str) -> String {
    let mut it = key.split_whitespace();
    let kt = it.next().unwrap_or("");
    let b64 = it.next().unwrap_or("");
    let comment = it.collect::<Vec<_>>().join(" ");
    let short = if b64.len() > 20 {
        format!("{}…{}", &b64[..8], &b64[b64.len() - 8..])
    } else {
        b64.to_owned()
    };
    format!("{kt} {short} {comment}").trim_end().to_owned()
}

/// Run this same `war` on the repository, inheriting the terminal — so
/// `war sign` can raise the key's dialog and the human can answer it. The
/// app (M2) does the same; nothing here holds a key.
fn child(root: &Utf8Path, args: &[&str]) -> Result<(), InitError> {
    let exe = std::env::current_exe().map_err(|source| InitError::Io {
        context: "could not find this executable".to_owned(),
        source,
    })?;
    let status = std::process::Command::new(exe)
        .arg("--root")
        .arg(root.as_str())
        .args(args)
        .status()
        .map_err(|source| InitError::Io {
            context: format!("could not run war {}", args.join(" ")),
            source,
        })?;
    if !status.success() {
        println!(
            "  (war {} exited {}; the conversation continues from what the tree says)",
            args.join(" "),
            status.code().unwrap_or(-1)
        );
    }
    Ok(())
}

//! `war init` as a conversation: the state machine (OW-WAR-0112 M4).
//!
//! Setup was ten commands and a flag nobody remembers. This module is the
//! part of the conversation that can be tested without a terminal: given
//! what the tree already holds, which question comes next; given an answer,
//! what should happen. It performs no I/O in a transition. Two front ends
//! drive it — the line prompts in `init::guided` and the app's Setup tab —
//! and both apply the `Effect`s it returns, then hand back fresh `Facts`.
//!
//! # State lives in the tree, never in a file of its own
//!
//! `Facts::read` looks at `openwarrant.toml`, the two authority files, the
//! SAS revisions and the first Warrant's records, and `step_for` picks the
//! first step those facts leave undone. An interrupted setup resumes at the
//! right question because there is nothing else to resume from — the same
//! rule the release wizard follows.
//!
//! # The authority files
//!
//! `roles.toml` and `allowed_signers` are written HERE, from a human's
//! answers, and the policy that makes that acceptable is narrow and stated
//! in the file header the tool writes: only from answers typed at a
//! terminal (`sign::at_a_terminal()`, the same §27.2 gate `war sign` uses —
//! the front end holds it, this module cannot see a terminal), only once
//! (an existing file is never touched — `Effect::Write` says so and the
//! front end refuses), and the agent entry is `performer` and nothing
//! else — no answer can widen it, because no question asks. The one thing
//! `war` cannot check, that the key was loaded with `ssh-add -c`, is asked,
//! and the answer is recorded as the human's unverified statement.

use camino::Utf8Path;

/// The questions, in the order a fresh repository meets them.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Step {
    /// Name and namespace: `war init --program`.
    Program,
    /// Where governed work begins, in a repository with history
    /// (OW-WAR-0124): the `[adoption]` baseline.
    Baseline,
    /// Who signs, and with which key.
    Signer,
    /// The `-c` question: unverifiable, asked, recorded.
    KeyLoaded,
    /// `war sas propose 0.1.0`.
    Sas,
    /// A human signs the SAS.
    SignSas,
    /// The adopt Warrant: check, compile, the request.
    Authorize,
    /// A human signs the adopt Warrant.
    SignAuthorize,
    Done,
}

impl Step {
    /// One line naming the step, for the Setup tab and the resume message.
    #[must_use]
    pub const fn title(self) -> &'static str {
        match self {
            Self::Program => "name the program",
            Self::Baseline => "say where governed work begins",
            Self::Signer => "say who signs",
            Self::KeyLoaded => "confirm the key asks you",
            Self::Sas => "record the SAS",
            Self::SignSas => "sign the SAS (human)",
            Self::Authorize => "prepare the first Warrant",
            Self::SignAuthorize => "sign the first Warrant (human)",
            Self::Done => "done",
        }
    }
}

/// What the tree already holds. Read once per turn by `Facts::read`, the
/// only function here that touches disk — and it only reads.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Facts {
    pub initialized: bool,
    pub program: Option<String>,
    pub namespace: Option<String>,
    pub roles_exist: bool,
    pub signers_exist: bool,
    /// Every recorded SAS revision: (version, accepted).
    pub sas: Vec<(String, bool)>,
    /// The first Warrant, when one exists: (alias, authorized).
    pub adopt: Option<(String, bool)>,
    /// Commits in HEAD's history; 0 with none, or outside git (OW-WAR-0124).
    pub commits: u64,
    /// HEAD's full id: the baseline proposed when there is history.
    pub head: Option<String>,
    /// `[adoption] baseline`, when `openwarrant.toml` records one.
    pub baseline: Option<String>,
    /// An existing ADR directory `war migrate` could import, if one is found.
    pub adr_dir: Option<String>,
}

impl Facts {
    /// Read the tree. Absent, unreadable and malformed all read as "not
    /// there yet": the conversation then asks, and the write-once rule at
    /// the front end keeps it from clobbering a file that merely failed to
    /// parse.
    #[must_use]
    pub fn read(root: &Utf8Path) -> Self {
        let config = std::fs::read_to_string(root.join(super::CONFIG_FILE)).ok();
        let (program, namespace) = config
            .as_deref()
            .and_then(|t| toml::from_str::<toml::Value>(t).ok())
            .and_then(|v| {
                let p = v.get("project")?;
                Some((
                    p.get("name")?.as_str()?.to_owned(),
                    p.get("namespace")?.as_str()?.to_owned(),
                ))
            })
            .map_or((None, None), |(p, n)| (Some(p), Some(n)));
        let baseline = config
            .as_deref()
            .and_then(|t| toml::from_str::<toml::Value>(t).ok())
            .and_then(|v| Some(v.get("adoption")?.get("baseline")?.as_str()?.to_owned()));
        let (head, commits) = match super::history(root) {
            super::History::Inside {
                head: Some((id, count)),
            } => (Some(id), count),
            _ => (None, 0),
        };
        let auth = root.join("docs/authority");
        let mut sas: Vec<(String, bool)> = std::fs::read_dir(root.join("docs/sas/revisions"))
            .map(|rd| {
                rd.filter_map(Result::ok)
                    .filter_map(|e| {
                        let name = e.file_name().to_string_lossy().into_owned();
                        let version = name.strip_suffix(".toml")?.to_owned();
                        let text = std::fs::read_to_string(e.path()).ok()?;
                        let accepted = toml::from_str::<toml::Value>(&text)
                            .ok()
                            .and_then(|v| v.get("state")?.as_str().map(|s| s == "accepted"))
                            .unwrap_or(false);
                        Some((version, accepted))
                    })
                    .collect()
            })
            .unwrap_or_default();
        sas.sort();
        let adopt = namespace.as_deref().and_then(|ns| {
            let alias = format!("{ns}-WAR-0001");
            let dir = root.join("docs/warrants").join(&alias);
            dir.join("manifest.toml").is_file().then(|| {
                let authorized = std::fs::read_to_string(dir.join("authorization.toml"))
                    .ok()
                    .and_then(|t| toml::from_str::<toml::Value>(&t).ok())
                    .and_then(|v| {
                        v.get("revision")?
                            .get("state")?
                            .as_str()
                            .map(|s| s.eq_ignore_ascii_case("authorized"))
                    })
                    .unwrap_or(false);
                (alias, authorized)
            })
        });
        Self {
            initialized: config.is_some(),
            program,
            namespace,
            roles_exist: auth.join("roles.toml").is_file(),
            signers_exist: auth.join("allowed_signers").is_file(),
            sas,
            adopt,
            commits,
            head,
            baseline,
            adr_dir: super::adr_dirs(root).first().map(|d| (*d).to_owned()),
        }
    }
}

/// The first step the facts leave undone.
#[must_use]
pub fn step_for(f: &Facts) -> Step {
    if !f.initialized {
        return Step::Program;
    }
    // A repository with history says where governed work begins before
    // anything else is set up. Asked while the setup is at its start — no
    // SAS revision recorded yet; a repository further along adopted before
    // this step existed, and is not asked again.
    if f.commits > 0 && f.baseline.is_none() && f.sas.is_empty() {
        return Step::Baseline;
    }
    if !(f.roles_exist && f.signers_exist) {
        return Step::Signer;
    }
    if f.sas.is_empty() {
        return Step::Sas;
    }
    if !f.sas.iter().any(|(_, accepted)| *accepted) {
        return Step::SignSas;
    }
    match &f.adopt {
        // `war init` without `--program` scaffolds no first Warrant; the
        // setup is then complete and `war new` is the next thing.
        None => Step::Done,
        Some((_, false)) => Step::Authorize,
        Some((_, true)) => Step::Done,
    }
}

/// A human's answer to the current step.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Answer {
    Program {
        name: String,
        namespace: String,
    },
    /// The commit governed work starts from; empty confirms the proposed one.
    Baseline(String),
    Signer {
        /// The name in `roles.toml`; spaces allowed.
        name: String,
        /// The `ssh_principal` and the first field of the allowed_signers
        /// line. No spaces (OpenSSH's rule).
        principal: String,
        /// One line as `ssh-add -L` prints it: `<keytype> <base64> [comment]`.
        key: String,
    },
    /// The `-c` question.
    KeyLoaded(bool),
    /// "go ahead" for a step that only needs consent (propose, prepare).
    Proceed,
    /// "sign it now" / "not now" for a signing step.
    SignNow(bool),
}

/// What the front end must do. Every write carries its full text, so the
/// front end can show it before it exists and refuse if the path does.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Effect {
    /// `war init --program <program> --namespace <namespace>`.
    Scaffold { program: String, namespace: String },
    /// Write once; never over an existing file.
    Write { path: String, text: String },
    /// Record `[adoption] baseline` in `openwarrant.toml` — once. The front
    /// end resolves the commit and refuses one outside the history.
    Adopt { baseline: String },
    /// `war sas propose <version>`.
    ProposeSas { version: String },
    /// Print the command and, on consent, run `war sign <target> --ssh-sign`
    /// in a child that inherits the terminal.
    Sign { target: String },
    /// `war check`, `war compile`, then `war authorize <alias>` printed.
    Prepare { alias: String },
    /// Something to tell the human.
    Say(String),
}

/// The conversation's state: the facts and the answers not yet written.
#[derive(Debug, Clone)]
pub struct Machine {
    pub facts: Facts,
    pub step: Step,
    /// Stamped by the front end at construction — the machine has no clock.
    now: String,
    /// The signer's answers, held until the `-c` question is answered so the
    /// file header can record both at once.
    pending_signer: Option<(String, String, String)>,
}

impl Machine {
    #[must_use]
    pub fn new(facts: Facts, now: impl Into<String>) -> Self {
        let step = step_for(&facts);
        Self {
            facts,
            step,
            now: now.into(),
            pending_signer: None,
        }
    }

    /// Fresh facts after the front end applied effects; the step follows.
    pub fn observe(&mut self, facts: Facts) {
        self.facts = facts;
        self.step = if self.pending_signer.is_some() && self.step == Step::KeyLoaded {
            Step::KeyLoaded
        } else {
            step_for(&self.facts)
        };
    }

    /// What this step asks, for a line front end. Multi-line; the front end
    /// prints it verbatim.
    #[must_use]
    pub fn question(&self) -> String {
        match self.step {
            Step::Program => "What is this program called, and what namespace prefixes its \
                              Warrants (uppercase letters, e.g. OW → OW-WAR-0001)?"
                .to_owned(),
            Step::Baseline => {
                let head = self.facts.head.as_deref().unwrap_or("?");
                let mut q = format!(
                    "This repository has {} commit(s). Where does governed work begin? The \
                     adoption baseline is HEAD, {}, unless you name another commit in its \
                     history. Nothing up to it is claimed, owned or verified by any Warrant; \
                     `war telemetry` counts untracked work after it.",
                    self.facts.commits,
                    head.get(..12).unwrap_or(head)
                );
                if let Some(dir) = &self.facts.adr_dir {
                    q.push_str(&format!(
                        " Existing ADRs in {dir}/ can be imported afterwards with `war migrate`; \
                         nothing is imported now."
                    ));
                }
                q
            }
            Step::Signer => "Who signs for this repository — your name as it will appear in \
                             roles.toml, the principal you sign as (no spaces), and which \
                             loaded key (`ssh-add -L`) is yours?"
                .to_owned(),
            Step::KeyLoaded => "Was that key loaded with `ssh-add -c`, so that every signature \
                                asks you through a dialog? `war` cannot check this; your answer \
                                is recorded as your statement."
                .to_owned(),
            Step::Sas => format!(
                "Record the SAS as it stands as revision 0.1.0 (`war sas propose 0.1.0`)? \
                 Namespace {}.",
                self.facts.namespace.as_deref().unwrap_or("?")
            ),
            Step::SignSas => format!(
                "SAS {} is proposed and unsigned. Sign it now? (`war sign {} --ssh-sign` — one \
                 dialog)",
                self.latest_sas().unwrap_or("0.1.0"),
                self.latest_sas().unwrap_or("0.1.0")
            ),
            Step::Authorize => format!(
                "Prepare {} for authorization — check it, compile it, and print the request?",
                self.adopt_alias().unwrap_or("the first Warrant")
            ),
            Step::SignAuthorize => format!(
                "Authorize {} now? (`war sign {} --ssh-sign` — one dialog)",
                self.adopt_alias().unwrap_or("?"),
                self.adopt_alias().unwrap_or("?")
            ),
            Step::Done => "Setup is complete. Work starts as a ticket: `war create \"...\"`, \
                 then `war ready`, `war claim <id>`, `war done <id>` — no signature needed. \
                 `war next` lists ready items first, then any act awaiting a human."
                .to_owned(),
        }
    }

    fn latest_sas(&self) -> Option<&str> {
        self.facts.sas.last().map(|(v, _)| v.as_str())
    }

    fn adopt_alias(&self) -> Option<&str> {
        self.facts.adopt.as_ref().map(|(a, _)| a.as_str())
    }

    /// Apply one answer: the effects the front end must perform. A wrong
    /// answer is refused with the reason and the step does not move.
    pub fn answer(&mut self, answer: Answer) -> Result<Vec<Effect>, String> {
        match (self.step, answer) {
            (Step::Program, Answer::Program { name, namespace }) => {
                let name = name.trim().to_owned();
                if name.is_empty() || name.contains(['\n', '\r', '|']) {
                    return Err("the program needs a name without a newline or `|`".to_owned());
                }
                if namespace.is_empty() || !namespace.bytes().all(|b| b.is_ascii_uppercase()) {
                    return Err(format!(
                        "the namespace is uppercase ASCII letters only, A–Z (it prefixes \
                         `{namespace}-SAS-RQ-001`); got {namespace:?}"
                    ));
                }
                Ok(vec![Effect::Scaffold {
                    program: name,
                    namespace,
                }])
            }
            (Step::Baseline, Answer::Baseline(named)) => {
                let named = named.trim();
                let commit = if named.is_empty() {
                    self.facts
                        .head
                        .clone()
                        .ok_or_else(|| "there is no HEAD to propose; name a commit".to_owned())?
                } else {
                    named.to_owned()
                };
                if commit.starts_with('-') || commit.contains(char::is_whitespace) {
                    return Err(format!("{commit:?} is not a commit name"));
                }
                Ok(vec![Effect::Adopt { baseline: commit }])
            }
            (
                Step::Signer,
                Answer::Signer {
                    name,
                    principal,
                    key,
                },
            ) => {
                let name = name.trim().to_owned();
                if name.is_empty() || name.contains(['\n', '\r', '"']) {
                    return Err("a name, without a newline or a double quote".to_owned());
                }
                let principal = principal.trim().to_owned();
                if principal.is_empty() || principal.contains(char::is_whitespace) {
                    return Err("the principal has no spaces (OpenSSH's rule)".to_owned());
                }
                let key = key.trim().to_owned();
                let fields: Vec<&str> = key.split_whitespace().collect();
                if fields.len() < 2
                    || !(fields[0].starts_with("ssh-") || fields[0].starts_with("sk-"))
                {
                    return Err(
                        "a key line as `ssh-add -L` prints it: `<keytype> <base64> [comment]`"
                            .to_owned(),
                    );
                }
                self.pending_signer = Some((name, principal, key));
                self.step = Step::KeyLoaded;
                Ok(vec![])
            }
            (Step::KeyLoaded, Answer::KeyLoaded(loaded)) => {
                let Some((name, principal, key)) = self.pending_signer.take() else {
                    return Err("no signer answered yet".to_owned());
                };
                let mut effects = Vec::new();
                if !self.facts.roles_exist {
                    effects.push(Effect::Write {
                        path: "docs/authority/roles.toml".to_owned(),
                        text: render_roles(&name, &principal, &self.now, loaded),
                    });
                }
                if !self.facts.signers_exist {
                    effects.push(Effect::Write {
                        path: "docs/authority/allowed_signers".to_owned(),
                        text: render_allowed_signers(&name, &principal, &key, &self.now, loaded),
                    });
                }
                if !loaded {
                    effects.push(Effect::Say(
                        "Load the key with confirmation on before signing anything:\n  ssh-add -c \
                         ~/.ssh/<your-key>\nWithout -c, any process that can reach the agent \
                         socket can sign as you — including an AI agent's shell."
                            .to_owned(),
                    ));
                }
                Ok(effects)
            }
            (Step::Sas, Answer::Proceed) => Ok(vec![Effect::ProposeSas {
                version: "0.1.0".to_owned(),
            }]),
            (Step::SignSas, Answer::SignNow(yes)) => Ok(if yes {
                vec![Effect::Sign {
                    target: self.latest_sas().unwrap_or("0.1.0").to_owned(),
                }]
            } else {
                vec![Effect::Say(format!(
                    "Later: `war sign {} --ssh-sign`. `war next` will keep saying so.",
                    self.latest_sas().unwrap_or("0.1.0")
                ))]
            }),
            (Step::Authorize, Answer::Proceed) => Ok(vec![Effect::Prepare {
                alias: self.adopt_alias().unwrap_or_default().to_owned(),
            }]),
            (Step::SignAuthorize, Answer::SignNow(yes)) => Ok(if yes {
                vec![Effect::Sign {
                    target: self.adopt_alias().unwrap_or_default().to_owned(),
                }]
            } else {
                vec![Effect::Say(format!(
                    "Later: `war sign {} --ssh-sign`.",
                    self.adopt_alias().unwrap_or("?")
                ))]
            }),
            (Step::Done, _) => Ok(vec![]),
            (step, other) => Err(format!(
                "{} does not take that answer ({other:?})",
                step.title()
            )),
        }
    }

    /// After `Prepare` the next question is the signature, even though the
    /// tree looks the same as before it.
    pub fn prepared(&mut self) {
        if self.step == Step::Authorize {
            self.step = Step::SignAuthorize;
        }
    }
}

fn header(name: &str, now: &str, loaded: bool) -> String {
    format!(
        "# Written by `war init` on {now} from answers typed at a terminal by {name:?}.\n\
         #\n\
         # THE RULE FOR THIS FILE: a tool writes it only from a human's answers at a\n\
         # terminal, once. No command edits it afterwards — every tool in this\n\
         # workspace reads it, and `war init` refuses to touch one that exists.\n\
         # Authority still enters from outside the system it governs: the answers\n\
         # were a human's, the terminal gate is the one `war sign` uses (§27.2), and\n\
         # a pseudo-terminal defeats it exactly as it defeats `war sign` — the\n\
         # residual THREAT_MODEL entry 2 already accepts (OW-ADR-0021, Consequences).\n\
         #\n\
         # The human stated their key was loaded with `ssh-add -c`: {}.\n\
         # `war` cannot check that; it is their statement, recorded as given.\n",
        if loaded {
            "yes"
        } else {
            "NO — signatures will not ask; load it with -c before trusting one"
        }
    )
}

/// `roles.toml`: the human with every human role, the agent as `performer`
/// and nothing else. No answer reaches the agent entry.
#[must_use]
pub fn render_roles(name: &str, principal: &str, now: &str, loaded: bool) -> String {
    format!(
        "# Actor role assignments (SAS §27.4).\n{}\n\
         [[assignment]]\n\
         actor = {name:?}\n\
         actor_kind = \"human\"\n\
         roles = [\"authorizer\", \"resolver\", \"risk_acceptor\", \"judge\"]\n\
         # Who granted this: the repository owner, naming themselves as the source of\n\
         # their own authority — the honest record of a sole-owner project.\n\
         assigned_by = {name:?}\n\
         effective_time = {now:?}\n\
         note = \"Repository owner, from `war init`.\"\n\
         ssh_principal = {principal:?}\n\
         \n\
         # The agent is a performer and nothing else (§27.1). No question in `war\n\
         # init` can widen this; a human edits it, or nobody does.\n\
         [[assignment]]\n\
         actor = \"claude\"\n\
         actor_kind = \"agent\"\n\
         roles = [\"performer\"]\n\
         assigned_by = {name:?}\n\
         effective_time = {now:?}\n\
         note = \"Drafts and executes. Authorizes nothing, resolves nothing (§27.2).\"\n",
        header(name, now, loaded)
    )
}

/// `allowed_signers`: one line, both namespaces, as OpenSSH reads it.
#[must_use]
pub fn render_allowed_signers(
    name: &str,
    principal: &str,
    key: &str,
    now: &str,
    loaded: bool,
) -> String {
    format!(
        "# Who may sign a response with an ssh key (`war sign --ssh-sign`).\n{}\
         #\n\
         # Format: <principal> namespaces=\"oh.war/response,oh.war/dsse\" <keytype> <base64> [comment]\n\
         # Both namespaces: the first signs the response, the second the attestation.\n\
         \n\
         {principal} namespaces=\"oh.war/response,oh.war/dsse\" {key}\n",
        header(name, now, loaded)
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    fn facts(initialized: bool) -> Facts {
        Facts {
            initialized,
            program: initialized.then(|| "Demo".to_owned()),
            namespace: initialized.then(|| "DM".to_owned()),
            ..Facts::default()
        }
    }

    #[test]
    fn the_first_step_follows_the_tree_not_a_state_file() {
        assert_eq!(step_for(&facts(false)), Step::Program);
        let mut f = facts(true);
        assert_eq!(step_for(&f), Step::Signer);
        f.roles_exist = true;
        assert_eq!(
            step_for(&f),
            Step::Signer,
            "one file of two is still unset up"
        );
        f.signers_exist = true;
        assert_eq!(step_for(&f), Step::Sas);
        f.sas = vec![("0.1.0".to_owned(), false)];
        assert_eq!(step_for(&f), Step::SignSas);
        f.sas = vec![("0.1.0".to_owned(), true)];
        f.adopt = Some(("DM-WAR-0001".to_owned(), false));
        assert_eq!(step_for(&f), Step::Authorize);
        f.adopt = Some(("DM-WAR-0001".to_owned(), true));
        assert_eq!(step_for(&f), Step::Done);
    }

    #[test]
    fn canned_answers_walk_to_done_and_every_write_is_from_a_typed_answer() {
        let mut m = Machine::new(facts(false), "2026-09-22T00:00:00Z");
        assert!(
            m.answer(Answer::Program {
                name: "Demo".into(),
                namespace: "dm".into()
            })
            .unwrap_err()
            .contains("uppercase")
        );
        let e = m
            .answer(Answer::Program {
                name: "Demo".into(),
                namespace: "DM".into(),
            })
            .unwrap();
        assert_eq!(
            e,
            vec![Effect::Scaffold {
                program: "Demo".into(),
                namespace: "DM".into()
            }]
        );
        m.observe(facts(true));
        assert_eq!(m.step, Step::Signer);
        assert!(
            m.answer(Answer::Signer {
                name: "Ada".into(),
                principal: "ada lovelace".into(),
                key: "ssh-ed25519 AAAA ada@host".into()
            })
            .is_err()
        );
        assert!(
            m.answer(Answer::Signer {
                name: "Ada".into(),
                principal: "ada".into(),
                key: "ssh-ed25519 AAAA ada@host".into(),
            })
            .unwrap()
            .is_empty()
        );
        assert_eq!(m.step, Step::KeyLoaded);
        let writes = m.answer(Answer::KeyLoaded(true)).unwrap();
        let paths: Vec<&str> = writes
            .iter()
            .filter_map(|e| match e {
                Effect::Write { path, .. } => Some(path.as_str()),
                _ => None,
            })
            .collect();
        assert_eq!(
            paths,
            [
                "docs/authority/roles.toml",
                "docs/authority/allowed_signers"
            ]
        );
        for e in &writes {
            if let Effect::Write { text, .. } = e {
                assert!(text.contains("typed at a terminal by \"Ada\""));
                assert!(text.contains("loaded with `ssh-add -c`: yes"));
            }
        }
        let mut f = facts(true);
        f.roles_exist = true;
        f.signers_exist = true;
        m.observe(f.clone());
        assert_eq!(m.step, Step::Sas);
        assert_eq!(
            m.answer(Answer::Proceed).unwrap(),
            vec![Effect::ProposeSas {
                version: "0.1.0".into()
            }]
        );
        f.sas = vec![("0.1.0".into(), false)];
        m.observe(f.clone());
        assert_eq!(m.step, Step::SignSas);
        assert_eq!(
            m.answer(Answer::SignNow(true)).unwrap(),
            vec![Effect::Sign {
                target: "0.1.0".into()
            }]
        );
        f.sas = vec![("0.1.0".into(), true)];
        f.adopt = Some(("DM-WAR-0001".into(), false));
        m.observe(f.clone());
        assert_eq!(m.step, Step::Authorize);
        assert_eq!(
            m.answer(Answer::Proceed).unwrap(),
            vec![Effect::Prepare {
                alias: "DM-WAR-0001".into()
            }]
        );
        m.prepared();
        assert_eq!(m.step, Step::SignAuthorize);
        assert_eq!(
            m.answer(Answer::SignNow(false)).unwrap().len(),
            1,
            "declining says how to do it later"
        );
        f.adopt = Some(("DM-WAR-0001".into(), true));
        m.observe(f);
        assert_eq!(m.step, Step::Done);
    }

    /// OW-WAR-0124 OBL-006: with history, the step after Program is
    /// Baseline, and confirming it yields exactly one effect — the one that
    /// writes `[adoption]`. Nothing about who signs moves.
    #[test]
    fn with_history_the_step_after_program_is_baseline() {
        let head = "0123456789abcdef0123456789abcdef01234567".to_owned();
        let before = Facts {
            commits: 3,
            head: Some(head.clone()),
            ..facts(false)
        };
        let mut m = Machine::new(before, "2026-09-24T00:00:00Z");
        assert_eq!(m.step, Step::Program);
        let e = m
            .answer(Answer::Program {
                name: "Demo".into(),
                namespace: "DM".into(),
            })
            .unwrap();
        assert!(matches!(e.as_slice(), [Effect::Scaffold { .. }]), "{e:?}");
        let mut after = Facts {
            commits: 3,
            head: Some(head.clone()),
            ..facts(true)
        };
        m.observe(after.clone());
        assert_eq!(m.step, Step::Baseline, "Baseline follows Program");
        assert!(m.question().contains("3 commit(s)"), "{}", m.question());
        assert!(m.question().contains(&head[..12]), "{}", m.question());
        // Refusals: not a commit name, and the step does not move.
        assert!(m.answer(Answer::Baseline("--all".into())).is_err());
        assert!(m.answer(Answer::Baseline("a b".into())).is_err());
        assert!(m.answer(Answer::KeyLoaded(true)).is_err());
        assert_eq!(m.step, Step::Baseline);
        // Confirming the proposed commit: exactly one effect, the adoption.
        let e = m.answer(Answer::Baseline(String::new())).unwrap();
        assert_eq!(
            e,
            vec![Effect::Adopt {
                baseline: head.clone()
            }]
        );
        // Naming another commit carries that name to the front end, which
        // resolves it against the history and refuses one outside it.
        assert_eq!(
            m.answer(Answer::Baseline("v1.0".into())).unwrap(),
            vec![Effect::Adopt {
                baseline: "v1.0".into()
            }]
        );
        // Once recorded, the tree says so and the setup goes on to Signer.
        after.baseline = Some(head);
        m.observe(after);
        assert_eq!(m.step, Step::Signer);
    }

    /// With no history there is nothing to adopt: Baseline is skipped.
    #[test]
    fn without_history_baseline_is_skipped() {
        assert_eq!(step_for(&facts(true)), Step::Signer);
        let mut m = Machine::new(facts(false), "2026-09-24T00:00:00Z");
        m.answer(Answer::Program {
            name: "Demo".into(),
            namespace: "DM".into(),
        })
        .unwrap();
        m.observe(facts(true));
        assert_eq!(m.step, Step::Signer);
        // And a repository past its first SAS revision is not asked again.
        let mut f = Facts {
            commits: 40,
            head: Some("abc".into()),
            roles_exist: true,
            signers_exist: true,
            ..facts(true)
        };
        f.sas = vec![("0.1.0".into(), true)];
        assert_eq!(step_for(&f), Step::Done);
    }

    #[test]
    fn an_existing_authority_file_is_never_written_again() {
        let mut f = facts(true);
        f.roles_exist = true;
        let mut m = Machine::new(f, "2026-09-22T00:00:00Z");
        m.answer(Answer::Signer {
            name: "Ada".into(),
            principal: "ada".into(),
            key: "ssh-ed25519 AAAA".into(),
        })
        .unwrap();
        let writes = m.answer(Answer::KeyLoaded(false)).unwrap();
        assert!(
            writes
                .iter()
                .all(|e| !matches!(e, Effect::Write { path, .. } if path.ends_with("roles.toml"))),
            "roles.toml exists and is left alone: {writes:?}"
        );
        assert!(
            writes.iter().any(
                |e| matches!(e, Effect::Write { path, .. } if path.ends_with("allowed_signers"))
            )
        );
        assert!(
            writes
                .iter()
                .any(|e| matches!(e, Effect::Say(s) if s.contains("ssh-add -c"))),
            "a key not loaded with -c earns the instruction"
        );
    }

    #[test]
    fn the_agent_is_a_performer_and_nothing_else() {
        let roles = render_roles("Ada", "ada", "2026-09-22T00:00:00Z", true);
        let parsed: toml::Value = toml::from_str(&roles).expect("roles.toml parses");
        let assignments = parsed["assignment"].as_array().unwrap();
        let agents: Vec<&toml::Value> = assignments
            .iter()
            .filter(|a| a["actor_kind"].as_str() == Some("agent"))
            .collect();
        assert_eq!(agents.len(), 1);
        assert_eq!(
            agents[0]["roles"].as_array().unwrap(),
            &vec![toml::Value::String("performer".into())]
        );
        let human = assignments
            .iter()
            .find(|a| a["actor_kind"].as_str() == Some("human"))
            .unwrap();
        assert_eq!(human["actor"].as_str(), Some("Ada"));
        assert_eq!(human["ssh_principal"].as_str(), Some("ada"));
        let signers = render_allowed_signers("Ada", "ada", "ssh-ed25519 AAAA ada@host", "t", false);
        let line = signers.lines().last().unwrap();
        assert_eq!(
            line,
            "ada namespaces=\"oh.war/response,oh.war/dsse\" ssh-ed25519 AAAA ada@host"
        );
        assert!(signers.contains("ssh-add -c`: NO"));
    }
}

//! `war` with no arguments: the app (OW-WAR-0112, absorbing OW-WAR-0073).
//!
//! A rendering under SAS §76.6 and OW-ADR-0019/0020: it issues commands and
//! holds no key. Every act it starts shells out to the same `war sign
//! --ssh-sign` a hand would run, in a child that inherits the terminal, so
//! the `ssh-add -c` dialog remains the human act. Nothing under `tui/` names
//! `ssh-keygen` or `SSH_AUTH_SOCK`; the battery greps for both.
//!
//! # One answer per question
//!
//! Every pane reads the functions the CLI already answers with —
//! `console::board`, `next::run`, `status::build`, `frontier::run`,
//! `check::run`, `doctor::run`, `journal_cmd::load` — and renders. A pane
//! that computed a fact itself would be a second answer to a question the
//! records already answer, and the one nobody re-checks.
//!
//! # One file
//!
//! OW-WAR-0112's signed declaration names `tui/mod.rs` and nothing else under
//! `tui/`, so the app lives here in inner modules rather than in files the
//! authorization never saw. A later Warrant that declares `tui/*.rs` may
//! split it; this one may not widen its own set (OW-ADR-0021).
//!
//! # The terminal comes back
//!
//! Raw mode and the alternate screen are entered through one guard whose
//! `Drop` leaves them, and a panic hook leaves them before the default hook
//! prints — a library that takes the terminal owes it back on every exit
//! path. `--panic-after-setup` is the fixture the battery uses to prove it.
//!
//! # No executor
//!
//! Input is `crossterm::event::poll` on a 250 ms tick; nothing here is
//! async, so OW-ADR-0014's refusal stands untouched. Live refresh is
//! `watch.rs`'s fingerprint poller, consulted every fourth idle tick and
//! debounced one more, so a signature given in another terminal shows up
//! without a keypress.

use std::collections::BTreeMap;
use std::io::Write as _;
use std::time::Duration;

use camino::{Utf8Path, Utf8PathBuf};
use crossterm::event::{self, Event, KeyCode, KeyEvent, KeyEventKind, KeyModifiers};
use ratatui::Terminal;
use ratatui::backend::CrosstermBackend;
use ratatui::layout::{Constraint, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, Borders, Clear, List, ListItem, ListState, Paragraph, Tabs, Wrap};

use crate::diagnostic::{Diagnostic, Report, Severity};
use crate::repo::{RepoError, Repository};

/// The refusal when there is no terminal: exit 2, by name, and not one
/// escape code on a pipe.
pub const NO_TTY: &str = "tui.no-tty";

/// `war` / `war tui`. Returns the exit code.
pub fn run(root: Option<Utf8PathBuf>, panic_after_setup: bool) -> Result<u8, RepoError> {
    if !crate::sign::at_a_terminal() {
        let mut report = Report::default();
        report.push(Diagnostic::error(
            NO_TTY,
            "-".to_owned(),
            "the app needs a terminal on stdin and stdout; for a script use `war status \
             --json`, `war console --json`, `war next --json` or `war check --json`",
        ));
        crate::check::print(&report);
        return Ok(crate::EXIT_NOT_READY);
    }
    let repo = Repository::discover(root.clone()).ok();
    // OW-WAR-0115: `war` where no repository is found opens the hub. Setup
    // for this directory stays one keypress away (`1`).
    let hub = repo.is_none() && root.is_none();
    let root = match (&repo, root) {
        (Some(r), _) => r.root.clone(),
        (None, Some(r)) => r,
        (None, None) => Utf8PathBuf::from_path_buf(
            std::env::current_dir().map_err(|e| RepoError::Message(e.to_string()))?,
        )
        .map_err(|_| RepoError::Message("the current directory is not UTF-8".to_owned()))?,
    };
    let mut model = Model::load(root, repo);
    if hub {
        model.pane = Pane::Projects;
        model.load_projects();
    }

    let guard = term::Guard::enter()?;
    // The hook runs before the default one prints the panic, so the message
    // lands on a restored screen rather than inside the alternate one.
    let default_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        term::leave_quietly();
        default_hook(info);
    }));
    if panic_after_setup {
        panic!("--panic-after-setup: the fixture that proves the terminal is restored");
    }
    let backend = CrosstermBackend::new(std::io::stdout());
    let mut terminal = Terminal::new(backend).map_err(io("could not open the terminal"))?;
    let result = event_loop(&mut terminal, &mut model);
    drop(guard);
    let _ = std::panic::take_hook();
    result.map(|()| crate::EXIT_OK)
}

fn io(context: &'static str) -> impl Fn(std::io::Error) -> RepoError {
    move |source| RepoError::Io {
        context: context.to_owned(),
        source,
    }
}

// ---------------------------------------------------------------------------
// The terminal guard
// ---------------------------------------------------------------------------

mod term {
    use super::io;
    use crate::repo::RepoError;
    use crossterm::terminal::{
        EnterAlternateScreen, LeaveAlternateScreen, disable_raw_mode, enable_raw_mode,
    };

    /// Raw mode and the alternate screen, both left on drop.
    pub struct Guard(());

    impl Guard {
        pub fn enter() -> Result<Self, RepoError> {
            enable_raw_mode().map_err(io("could not enter raw mode"))?;
            crossterm::execute!(std::io::stdout(), EnterAlternateScreen)
                .map_err(io("could not enter the alternate screen"))?;
            Ok(Self(()))
        }
    }

    impl Drop for Guard {
        fn drop(&mut self) {
            leave_quietly();
        }
    }

    /// Best effort, never failing: called from the panic hook and from drop.
    pub fn leave_quietly() {
        let _ = disable_raw_mode();
        let _ = crossterm::execute!(std::io::stdout(), LeaveAlternateScreen);
    }
}

// ---------------------------------------------------------------------------
// The model: read through the CLI's own functions, rendered and nothing else
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Pane {
    Setup,
    Help,
    Queue,
    Questions,
    Frontier,
    Corpus,
    Obligations,
    Evidence,
    Journal,
    Roadmap,
    Projects,
    Tickets,
}

impl Pane {
    const ALL: [Pane; 12] = [
        Pane::Setup,
        Pane::Help,
        Pane::Queue,
        Pane::Questions,
        Pane::Frontier,
        Pane::Corpus,
        Pane::Obligations,
        Pane::Evidence,
        Pane::Journal,
        Pane::Roadmap,
        Pane::Projects,
        Pane::Tickets,
    ];

    const fn title(self) -> &'static str {
        match self {
            Self::Setup => "1 Setup",
            Self::Help => "2 Help",
            Self::Queue => "3 Queue",
            Self::Questions => "4 Questions",
            Self::Frontier => "5 Frontier",
            Self::Corpus => "6 Corpus",
            Self::Obligations => "7 Obligations",
            Self::Evidence => "8 Evidence",
            Self::Journal => "9 Journal",
            Self::Roadmap => "0 Roadmap",
            Self::Projects => "p Projects",
            Self::Tickets => "t Tickets",
        }
    }
}

/// One row of any list pane: what is shown, the command behind it, and what
/// `Enter` or `v` does with it.
#[derive(Debug, Clone)]
struct Row {
    text: String,
    /// The exact command behind the row, for the bottom line.
    command: String,
    /// `war sign <target>`: the act `s`/`Enter` runs in a child.
    sign_target: Option<String>,
    /// A remedy `x` may run unasked.
    auto: Option<Vec<String>>,
    /// Detail `Enter` opens, when the row has more to say.
    detail: Option<String>,
}

/// One document the Help pane can show.
struct Doc {
    name: String,
    text: String,
}

struct Model {
    root: Utf8PathBuf,
    repo: Option<Repository>,
    program: String,
    sas_in_force: String,
    pane: Pane,
    /// Per pane: rows and the highlighted index.
    rows: BTreeMap<u8, Vec<Row>>,
    selected: BTreeMap<u8, usize>,
    /// Queue rows checked for a batch.
    checked: std::collections::BTreeSet<usize>,
    filter: String,
    filtering: bool,
    show_keys: bool,
    /// A popup with scrollable text (a request, a detail, a command's output).
    popup: Option<(String, String, u16)>,
    docs: Vec<Doc>,
    doc_index: usize,
    /// The Help pane's mode: what-next (false) or a document (true).
    reading: bool,
    status: String,
    setup: crate::init::guided::Machine,
    pending_count: usize,
    fingerprint: u64,
    fingerprint_pending: Option<u64>,
    idle_ticks: u32,
    /// The Projects pane's projects, index-aligned with its first rows;
    /// facts are read one project per idle tick (`tick_projects`).
    projects: Vec<crate::projects::Row>,
    /// Which project the next idle tick looks at.
    project_cursor: usize,
    /// `n` on Projects: the directory being typed for a new project.
    new_dir: Option<String>,
    /// The Help pane's first row: this binary, and PATH's `war` if it differs.
    binary: Row,
}

impl Model {
    fn load(root: Utf8PathBuf, repo: Option<Repository>) -> Self {
        let now = crate::gate_cmd::receipt::rfc3339_from_secs(
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map_or(0, |d| d.as_secs()),
        );
        let setup = crate::init::guided::Machine::new(crate::init::guided::Facts::read(&root), now);
        let mut m = Self {
            program: repo.as_ref().map_or_else(
                || root.file_name().unwrap_or("?").to_owned(),
                |r| r.config.project.name.clone(),
            ),
            sas_in_force: "none".to_owned(),
            pane: if setup.step == crate::init::guided::Step::Done {
                Pane::Queue
            } else {
                Pane::Setup
            },
            rows: BTreeMap::new(),
            selected: BTreeMap::new(),
            checked: std::collections::BTreeSet::new(),
            filter: String::new(),
            filtering: false,
            show_keys: false,
            popup: None,
            docs: Vec::new(),
            doc_index: 0,
            reading: false,
            status: String::new(),
            setup,
            pending_count: 0,
            fingerprint: 0,
            fingerprint_pending: None,
            idle_ticks: 0,
            projects: Vec::new(),
            project_cursor: 0,
            new_dir: None,
            binary: binary_row(),
            root,
            repo,
        };
        m.docs = m.load_docs();
        m.refresh();
        // t-67ed: the ticket loop is the default work path. A repository
        // with tickets opens on them; Setup and the Queue stay one key away.
        if m.rows
            .get(&(Pane::Tickets as u8))
            .is_some_and(|r| !r.is_empty())
        {
            m.pane = Pane::Tickets;
        }
        m
    }

    /// Everything the panes show, re-read. Never computes a fact of its own.
    fn refresh(&mut self) {
        self.setup
            .observe(crate::init::guided::Facts::read(&self.root));
        let Some(repo) = self.repo.as_ref() else {
            self.status = format!(
                "{} is not a repository — p lists your projects, 1 sets one up here",
                self.root
            );
            for p in Pane::ALL {
                self.rows.insert(p as u8, vec![]);
            }
            self.rows.insert(
                Pane::Setup as u8,
                vec![Row {
                    text: format!("→ {}", self.setup.step.title()),
                    command: "war init".to_owned(),
                    sign_target: None,
                    auto: None,
                    detail: Some(self.setup.question()),
                }],
            );
            self.rows
                .insert(Pane::Help as u8, self.help_rows(None, None, None));
            return;
        };
        let repo = repo.clone();
        self.sas_in_force = repo
            .latest_sas_revision()
            .ok()
            .flatten()
            .map_or_else(|| "none".to_owned(), |r| r.version);
        self.fingerprint = crate::watch::fingerprint(&watched(&repo));

        // The queue: `war sign --list`, through the console's board.
        let board = crate::console::board(&repo).ok();
        let mut queue = Vec::new();
        let mut questions = Vec::new();
        let mut stage_cmd: BTreeMap<(String, String), String> = BTreeMap::new();
        if let Some(b) = &board {
            for a in &b.acts {
                queue.push(Row {
                    text: format!("[{}] {}", a.n, a.line),
                    command: a.command.clone(),
                    sign_target: Some(a.target.clone()),
                    auto: None,
                    detail: None,
                });
            }
            for q in &b.questions {
                questions.push(Row {
                    text: format!(
                        "{} {}/{}: {}{}",
                        if q.blocking { "BLOCKING" } else { "        " },
                        q.warrant,
                        q.id,
                        q.question,
                        if q.recommended.is_empty() {
                            String::new()
                        } else {
                            format!("  → {}", q.recommended)
                        }
                    ),
                    command: q.command.clone(),
                    sign_target: None,
                    auto: None,
                    detail: Some(format!(
                        "{}\n\nrecommended: {}\n\n{}",
                        q.question, q.recommended, q.command
                    )),
                });
            }
            for s in &b.stages {
                stage_cmd.insert((s.warrant.clone(), s.stage.clone()), s.command.clone());
            }
        }
        self.pending_count = queue.len();
        self.checked.retain(|n| *n < queue.len());
        self.rows.insert(Pane::Queue as u8, queue);
        self.rows.insert(Pane::Questions as u8, questions);

        // The frontier.
        let mut frontier = Vec::new();
        if let Ok((_, f)) = crate::frontier::run(&repo, None) {
            for r in &f.rows {
                let cmd = stage_cmd
                    .get(&(r.warrant.clone(), r.stage.clone()))
                    .cloned()
                    .unwrap_or_else(|| format!("war frontier {}", r.warrant));
                frontier.push(Row {
                    text: format!(
                        "{:<8} {} {} — {} [{}]{}",
                        format!("{:?}", r.state).to_lowercase(),
                        r.warrant,
                        r.stage,
                        r.title,
                        r.executor_kind,
                        if r.waiting_on.is_empty() {
                            String::new()
                        } else {
                            format!("  waits on {}", r.waiting_on.join(", "))
                        }
                    ),
                    command: cmd,
                    sign_target: None,
                    auto: None,
                    detail: None,
                });
            }
        }
        self.rows.insert(Pane::Frontier as u8, frontier);

        // The corpus, obligations and evidence: one `status::build`.
        let status = crate::status::build(&repo).ok();
        let mut corpus = Vec::new();
        let mut obligations = Vec::new();
        let mut evidence = Vec::new();
        if let Some(s) = &status {
            for w in &s.warrants {
                let thirteen = w.checks.map_or_else(
                    || {
                        "the thirteen: not established (the Warrant could not be evaluated)"
                            .to_owned()
                    },
                    |c| {
                        c.as_pairs()
                            .iter()
                            .map(|(name, met)| format!("{} {name}", if *met { "✓" } else { "✗" }))
                            .collect::<Vec<_>>()
                            .join("\n")
                    },
                );
                corpus.push(Row {
                    text: format!(
                        "{:<16} {:<12} {}{}",
                        w.alias,
                        format!("{:?}", w.rung).to_lowercase(),
                        w.title.as_deref().unwrap_or(""),
                        if w.unmet.is_empty() {
                            String::new()
                        } else {
                            format!("  ({} unmet)", w.unmet.len())
                        }
                    ),
                    command: format!("war resolve {} --dry-run", w.alias),
                    sign_target: None,
                    auto: None,
                    detail: Some(format!(
                        "{} — {}\nrung: {:?}\n\n{thirteen}\n\nunestablished: {}\nblocking unknowns: {}",
                        w.alias,
                        w.title.as_deref().unwrap_or(""),
                        w.rung,
                        if w.unestablished.is_empty() { "none".to_owned() } else { w.unestablished.join(", ") },
                        if w.blocking_unknowns.is_empty() { "none".to_owned() } else { w.blocking_unknowns.join(", ") },
                    )),
                });
                for o in &w.obligations {
                    obligations.push(Row {
                        text: format!(
                            "{} {:<8} {:<14} {}{}",
                            w.alias,
                            o.id,
                            o.disposition,
                            o.verifier.as_deref().unwrap_or("no verifier"),
                            o.inadmissible_because
                                .as_deref()
                                .map_or(String::new(), |why| format!("  inadmissible: {why}")),
                        ),
                        command: format!("war resolve {} --dry-run", w.alias),
                        sign_target: None,
                        auto: None,
                        detail: Some(format!(
                            "{} {}\n\n{}\n\nscope: {}\ngate: {}\ndisposition: {}\nverifier: {} ({})\n{}",
                            w.alias,
                            o.id,
                            o.statement,
                            o.scope,
                            o.gate.as_deref().unwrap_or("none"),
                            o.disposition,
                            o.verifier.as_deref().unwrap_or("none"),
                            o.verifier_kind.as_deref().unwrap_or("-"),
                            o.inadmissible_because
                                .as_deref()
                                .map_or(String::new(), |w| format!("inadmissible because: {w}")),
                        )),
                    });
                }
                for g in &w.gate_runs {
                    evidence.push(Row {
                        text: format!(
                            "{:<12} {} {} {} {}{}",
                            g.class,
                            w.alias,
                            g.gate,
                            g.run_id,
                            g.verdict,
                            g.why.as_deref().map_or(String::new(), |y| format!("  {y}")),
                        ),
                        command: format!("war evidence record {} --gate {}", w.alias, g.gate),
                        sign_target: None,
                        auto: Some(vec![
                            "war".to_owned(),
                            "evidence".to_owned(),
                            "record".to_owned(),
                            w.alias.clone(),
                            "--gate".to_owned(),
                            g.gate.clone(),
                        ]),
                        detail: g.receipt_ref.as_ref().map(|r| format!("receipt: {r}")),
                    });
                }
            }
        }
        evidence.sort_by(|a, b| a.text.cmp(&b.text));
        self.rows.insert(Pane::Corpus as u8, corpus);
        self.rows.insert(Pane::Obligations as u8, obligations);
        self.rows.insert(Pane::Evidence as u8, evidence);

        // The journal: every Warrant's events, newest first.
        let mut journal = Vec::new();
        if let Ok(dirs) = repo.warrant_dirs() {
            for dir in dirs {
                let alias = dir.file_name().unwrap_or("?").to_owned();
                match crate::journal_cmd::load(&dir) {
                    Ok(j) => {
                        for e in &j.events {
                            journal.push(Row {
                                text: format!(
                                    "{} {:<14} {:<28} {}",
                                    e.occurred_at, alias, e.event_type, e.actor_ref
                                ),
                                command: format!("war journal {alias}"),
                                sign_target: None,
                                auto: None,
                                detail: Some(format!(
                                    "{}\n{}\n\n{}",
                                    e.occurred_at, e.event_type, e.payload
                                )),
                            });
                        }
                    }
                    Err(e) => journal.push(Row {
                        text: format!("UNREADABLE {alias}: {e}"),
                        command: format!("war journal {alias}"),
                        sign_target: None,
                        auto: None,
                        detail: None,
                    }),
                }
            }
        }
        journal.sort_by(|a, b| b.text.cmp(&a.text));
        self.rows.insert(Pane::Journal as u8, journal);

        // The roadmap: phases in dependency order, from `war roadmap`'s view.
        let mut roadmap = Vec::new();
        match crate::roadmap_cmd::view(&repo) {
            Ok((_, v)) => {
                for p in &v.phases {
                    roadmap.push(Row {
                        text: format!(
                            "{:<12} {:<34} {:>3} Warrant(s)  {}{}",
                            p.id,
                            p.title,
                            p.members.len(),
                            p.achieved,
                            if p.open.is_empty() {
                                String::new()
                            } else {
                                format!("  · no Warrant yet: {}", p.open.join(", "))
                            }
                        ),
                        command: "war roadmap edit".to_owned(),
                        sign_target: None,
                        auto: None,
                        detail: Some(format!(
                            "{} — {}\n\nexit: {}\nafter: {}\ntier: {}\nmembers: {}",
                            p.id,
                            p.title,
                            p.exit,
                            if p.depends_on.is_empty() {
                                "nothing".to_owned()
                            } else {
                                p.depends_on.join(", ")
                            },
                            p.tier.as_deref().unwrap_or("-"),
                            p.members.join(", ")
                        )),
                    });
                }
                if !v.accepted {
                    roadmap.insert(
                        0,
                        Row {
                            text: match v.pending_revision {
                                Some(n) => {
                                    format!("HUMAN  roadmap revision {n} awaits one signature")
                                }
                                None => "WARN   the roadmap atoms are not an accepted revision"
                                    .to_owned(),
                            },
                            command: "war sign roadmap --ssh-sign".to_owned(),
                            sign_target: v.pending_revision.map(|_| "roadmap".to_owned()),
                            auto: None,
                            detail: None,
                        },
                    );
                }
            }
            Err(e) => roadmap.push(Row {
                text: format!("no roadmap record: {e}"),
                command: "war roadmap".to_owned(),
                sign_target: None,
                auto: None,
                detail: None,
            }),
        }
        self.rows.insert(Pane::Roadmap as u8, roadmap);

        // Tickets (t-67ed): `ticket::board`, the same answer `war tickets`,
        // `war show` and `war ready` give. Read-only: no row signs or runs.
        let tickets = crate::ticket::Store::open(&repo, None)
            .and_then(|store| crate::ticket::board(&store))
            .map_or_else(
                |e| {
                    vec![Row {
                        text: format!("UNKNOWN: the tickets could not be read: {e}"),
                        command: "war tickets".to_owned(),
                        sign_target: None,
                        auto: None,
                        detail: None,
                    }]
                },
                |b| ticket_rows(&b),
            );
        self.rows.insert(Pane::Tickets as u8, tickets);

        // Setup and Help.
        self.rows.insert(
            Pane::Setup as u8,
            vec![Row {
                text: format!("→ {}", self.setup.step.title()),
                command: "war init".to_owned(),
                sign_target: None,
                auto: None,
                detail: Some(self.setup.question()),
            }],
        );
        let next = crate::next::run(&repo).ok();
        let (doctor, _) = crate::doctor::run(Some(self.root.clone()), None, false);
        let check = crate::check::run(&repo, None, false).ok();
        self.rows.insert(
            Pane::Help as u8,
            self.help_rows(next.as_ref(), Some(&doctor), check.as_ref()),
        );

        for p in Pane::ALL {
            let n = self.rows.get(&(p as u8)).map_or(0, Vec::len);
            let sel = self.selected.entry(p as u8).or_insert(0);
            if *sel >= n {
                *sel = n.saturating_sub(1);
            }
        }
        self.status = format!(
            "{} · {} · SAS {} · {} act(s) awaiting a signature · p projects",
            self.program, self.root, self.sas_in_force, self.pending_count
        );
    }

    /// What next: the Setup step if incomplete, then `war next`'s actions
    /// (human first), then doctor's non-passes, then `war check`'s errors
    /// deduped by rule with counts — each with its remedy.
    fn help_rows(
        &self,
        next: Option<&crate::next::Next>,
        doctor: Option<&Report>,
        check: Option<&Report>,
    ) -> Vec<Row> {
        let mut rows = vec![self.binary.clone()];
        if self.setup.step != crate::init::guided::Step::Done {
            rows.push(Row {
                text: format!(
                    "setup: {} — press Enter on the Setup tab",
                    self.setup.step.title()
                ),
                command: "war init".to_owned(),
                sign_target: None,
                auto: None,
                detail: Some(self.setup.question()),
            });
        }
        if let Some(n) = next {
            // t-67ed: ready ticket items first, as `war next` lists them.
            // Shown, never run from here: no auto, no signature.
            for r in &n.ready {
                rows.push(Row {
                    text: format!("ready claim      {} — {}", r.ticket, r.text),
                    command: r.command.clone(),
                    sign_target: None,
                    auto: None,
                    detail: None,
                });
            }
            for a in &n.actions {
                rows.push(Row {
                    // A signing command arrives judged by its dry run
                    // (OW-ADR-0022); the verdict sits beside it, so a human
                    // reads `would refuse: <rule>` before pressing Enter.
                    text: format!(
                        "{:<5} {:<10} {} — {}{}",
                        match a.actor {
                            crate::next::Actor::Human => "HUMAN",
                            crate::next::Actor::Agent => "agent",
                        },
                        a.action,
                        a.warrant,
                        a.why,
                        a.judged
                            .as_ref()
                            .map(|j| format!(" [{}]", j.word()))
                            .unwrap_or_default()
                    ),
                    sign_target: a
                        .command
                        .strip_prefix("war sign ")
                        .map(|t| t.split_whitespace().next().unwrap_or(t).to_owned()),
                    auto: (a.actor == crate::next::Actor::Agent
                        && !a.command.starts_with("war sign"))
                    .then(|| a.command.split_whitespace().map(str::to_owned).collect()),
                    command: a.command.clone(),
                    detail: None,
                });
            }
            if let Some(why) = &n.nothing {
                rows.push(Row {
                    text: if n.ready.is_empty() {
                        format!("nothing to do: {why}")
                    } else {
                        format!("no Warrant act waits: {why}")
                    },
                    command: "war next".to_owned(),
                    sign_target: None,
                    auto: None,
                    detail: None,
                });
            }
        }
        if let Some(d) = doctor {
            for diag in d
                .diagnostics
                .iter()
                .filter(|d| d.severity != Severity::Pass)
            {
                rows.push(remedy_row(diag, 1));
            }
        }
        if let Some(c) = check {
            let mut by_rule: BTreeMap<&str, (usize, &Diagnostic)> = BTreeMap::new();
            for diag in c
                .diagnostics
                .iter()
                .filter(|d| d.severity == Severity::Error)
            {
                by_rule
                    .entry(&diag.rule)
                    .and_modify(|e| e.0 += 1)
                    .or_insert((1, diag));
            }
            for (_, (n, diag)) in by_rule {
                rows.push(remedy_row(diag, n));
            }
        }
        if rows.len() == 1 {
            rows.push(Row {
                text: "nothing pending, nothing red — `war next` agrees".to_owned(),
                command: "war next".to_owned(),
                sign_target: None,
                auto: None,
                detail: None,
            });
        }
        rows
    }

    /// The documents Help can show: shipped ones embedded at build time (so
    /// help never drifts from what `war init` ships), this repository's own
    /// first when present.
    fn load_docs(&self) -> Vec<Doc> {
        let mut docs = Vec::new();
        // The master document first (OW-ADR-0022): what is authoritative
        // here now, generated by `war compile`. Read from disk, because it is
        // this repository's; a program that has not compiled has none.
        if let Ok(text) =
            std::fs::read_to_string(self.root.join(openwarrant_compiler::current::CURRENT_PATH))
        {
            docs.push(Doc {
                name: format!(
                    "this repository: {}",
                    openwarrant_compiler::current::CURRENT_PATH
                ),
                text,
            });
        }
        for name in ["AGENTS.md", "CONTEXT.md", "CONTRIBUTING.md"] {
            if let Ok(text) = std::fs::read_to_string(self.root.join(name)) {
                docs.push(Doc {
                    name: format!("this repository: {name}"),
                    text,
                });
            }
        }
        let ns = self
            .repo
            .as_ref()
            .map_or("OW", |r| r.config.project.namespace.as_str())
            .to_owned();
        for (name, text) in [
            (
                "docs/TUI.md",
                include_str!("../../../../docs/TUI.md").to_owned(),
            ),
            (
                "QUICKSTART.md",
                include_str!("../../../../QUICKSTART.md").to_owned(),
            ),
            (
                "README.md",
                include_str!("../../../../README.md").to_owned(),
            ),
            (
                "docs/DEFINITIONS.md",
                include_str!("../../../../docs/DEFINITIONS.md").to_owned(),
            ),
            (
                "docs/SKILLS.md",
                include_str!("../../../../docs/SKILLS.md").to_owned(),
            ),
            (
                "AGENTS.md (as `war init` ships it)",
                crate::init::render_agents_md(&ns),
            ),
        ] {
            docs.push(Doc {
                name: name.to_owned(),
                text,
            });
        }
        docs
    }

    fn rows(&self) -> &[Row] {
        self.rows.get(&(self.pane as u8)).map_or(&[], Vec::as_slice)
    }

    /// The rows the filter keeps, with their original indices.
    fn visible(&self) -> Vec<(usize, &Row)> {
        let f = self.filter.to_lowercase();
        self.rows()
            .iter()
            .enumerate()
            .filter(|(_, r)| f.is_empty() || r.text.to_lowercase().contains(&f))
            .collect()
    }

    fn selected(&self) -> usize {
        self.selected.get(&(self.pane as u8)).copied().unwrap_or(0)
    }

    fn select(&mut self, i: usize) {
        self.selected.insert(self.pane as u8, i);
    }

    fn current(&self) -> Option<&Row> {
        let v = self.visible();
        v.get(self.selected()).map(|(_, r)| *r)
    }

    fn current_index(&self) -> Option<usize> {
        let v = self.visible();
        v.get(self.selected()).map(|(i, _)| *i)
    }

    /// The Projects pane: every project named at once, from the list alone;
    /// each one's facts arrive on later idle ticks (OW-WAR-0115's basis: at
    /// most one project read per tick, re-read only when its fingerprint
    /// moves), so a long list never stalls the app.
    fn load_projects(&mut self) {
        self.projects = crate::projects::listed();
        self.project_cursor = 0;
        if self.projects.is_empty() {
            self.status =
                "no projects yet: run any `war` command inside a repository and it is remembered"
                    .to_owned();
        }
        self.render_projects();
        self.selected.insert(Pane::Projects as u8, 0);
    }

    /// One idle tick's worth: the first project not yet read, or else the
    /// next one round-robin, re-read only if its fingerprint moved.
    fn tick_projects(&mut self) {
        let n = self.projects.len();
        if n == 0 {
            return;
        }
        let i = self
            .projects
            .iter()
            .position(|r| !r.missing && r.fingerprint.is_none() && r.unreadable.is_none())
            .unwrap_or_else(|| {
                self.project_cursor = (self.project_cursor + 1) % n;
                self.project_cursor
            });
        let row = &mut self.projects[i];
        if row.missing {
            return;
        }
        if row.fingerprint.is_some() && crate::projects::fingerprint(&row.root) == row.fingerprint {
            return;
        }
        crate::projects::read_facts(row);
        if row.fingerprint.is_none() {
            // Unreadable: keep the reason and stop retrying it every tick.
            row.fingerprint = Some(0);
        }
        self.render_projects();
    }

    fn render_projects(&mut self) {
        let mut rows = Vec::new();
        for r in &self.projects {
            let facts = if r.missing {
                "(missing)".to_owned()
            } else if r.fingerprint.is_none() {
                "reading…".to_owned()
            } else {
                crate::projects::summary(r)
            };
            rows.push(Row {
                text: format!(
                    "{:<26} {}  {facts}",
                    r.program.as_deref().unwrap_or("?"),
                    r.root
                ),
                command: format!("war --root {}", r.root),
                sign_target: None,
                auto: None,
                detail: Some(if r.missing {
                    format!(
                        "{} holds no openwarrant.toml any more.\n\n`war projects --forget {}` removes it from the list.",
                        r.root, r.root
                    )
                } else {
                    format!("{}\n\n{facts}", r.root)
                }),
            });
        }
        for (text, command, detail) in [
            (
                "+ a new project in another directory (n)".to_owned(),
                "war init --root <directory>".to_owned(),
                "`n` asks for a directory, creates it if needed, and runs `war init` there.",
            ),
            (
                format!("+ set up {} (1)", self.root),
                "war init".to_owned(),
                "The Setup pane runs `war init` in this directory.",
            ),
        ] {
            rows.push(Row {
                text,
                command,
                sign_target: None,
                auto: None,
                detail: Some(detail.to_owned()),
            });
        }
        self.rows.insert(Pane::Projects as u8, rows);
    }

    /// Switch the whole app to another project: a fresh model, as if `war`
    /// had been started there — nothing of this one carries over.
    fn open_project(&mut self, root: Utf8PathBuf) {
        let repo = Repository::discover(Some(root.clone())).ok();
        if let Some(r) = &repo {
            crate::projects::touch(&r.root);
        }
        let opened = repo.is_some();
        *self = Model::load(root, repo);
        if !opened {
            self.pane = Pane::Setup;
        }
    }
}

/// This binary's identity and path, and a warning when `war` on PATH is a
/// different build — the 2026-09-23 failure, where a command handed over
/// ran an older `war` than the one that drafted it.
///
/// OW-WAR-0143: the comparison is the whole `--version` line, not its last
/// word. Two builds of one version (a release and a checkout 62 commits past
/// it) share the version and differ in the line; only the line tells them
/// apart. The remedy is `install::remedy`, the command for this install.
fn binary_row() -> Row {
    let here = crate::build_identity::version_line();
    let exe = std::env::current_exe()
        .ok()
        .and_then(|p| p.canonicalize().ok())
        .map_or_else(|| "?".to_owned(), |p| p.display().to_string());
    let on_path = std::env::var_os("PATH").and_then(|paths| {
        std::env::split_paths(&paths)
            .map(|d| d.join("war"))
            .find(|p| p.is_file())
    });
    let install = crate::install::remedy(env!("CARGO_PKG_VERSION"));
    let (text, detail) = match on_path {
        None => (
            format!("INFO    this is {here} at {exe}; no `war` on PATH"),
            format!("Commands this app hands over say `war`. To put one on PATH: `{install}`."),
        ),
        Some(p) => {
            let canonical = p
                .canonicalize()
                .map_or_else(|_| p.display().to_string(), |c| c.display().to_string());
            let version = std::process::Command::new(&p)
                .arg("--version")
                .output()
                .ok()
                .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_owned())
                .unwrap_or_default();
            if canonical == exe || version == here {
                (
                    format!("INFO    {here} at {exe} — the `war` on PATH"),
                    format!("`war` on PATH is {canonical}, the same build."),
                )
            } else {
                (
                    format!(
                        "WARN    this is {here} at {exe}; `war` on PATH is {} at {canonical}",
                        if version.is_empty() {
                            "unknown".to_owned()
                        } else {
                            version.clone()
                        }
                    ),
                    format!(
                        "A command you copy from here and run as `war` runs {canonical} ({version}), not this {here}. \
                         Update it: `{install}`, or run this one by path: {exe}."
                    ),
                )
            }
        }
    };
    Row {
        text,
        command: install,
        sign_target: None,
        auto: None,
        detail: Some(detail),
    }
}

fn remedy_row(diag: &Diagnostic, n: usize) -> Row {
    let remedy = crate::remedy::remedy_for(diag);
    let command = remedy.as_ref().map_or_else(
        || format!("war check  # {}", diag.rule),
        crate::remedy::Remedy::command,
    );
    Row {
        text: format!(
            "{:<7} {:<34} ×{n}  {}",
            diag.severity.label(),
            diag.rule,
            remedy
                .as_ref()
                .map_or("no remedy on record", |r| r.purpose.as_str())
        ),
        sign_target: remedy
            .as_ref()
            .filter(|r| {
                r.kind == crate::remedy::Kind::Human
                    && r.argv.first().is_some_and(|a| a == "war")
                    && r.argv.get(1).is_some_and(|a| a == "sign")
            })
            .and_then(|r| r.argv.get(2).cloned()),
        auto: remedy
            .as_ref()
            .filter(|r| r.kind == crate::remedy::Kind::Auto)
            .map(|r| r.argv.clone()),
        detail: Some(format!("{}\n\n{}\n\n{}", diag.rule, diag.message, command)),
        command,
    }
}

// ---------------------------------------------------------------------------
// The event loop
// ---------------------------------------------------------------------------

fn event_loop(
    terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
    m: &mut Model,
) -> Result<(), RepoError> {
    loop {
        terminal
            .draw(|f| draw(f, m))
            .map_err(io("could not draw"))?;
        if event::poll(Duration::from_millis(250)).map_err(io("could not poll the terminal"))? {
            match event::read().map_err(io("could not read the terminal"))? {
                Event::Key(k) if k.kind == KeyEventKind::Press => {
                    if handle_key(terminal, m, k)? == Flow::Quit {
                        return Ok(());
                    }
                }
                Event::Resize(..) => {}
                _ => {}
            }
            m.idle_ticks = 0;
            continue;
        }
        // Idle: every fourth tick look at the tree; a change is applied on
        // the tick after it settles (debounced one more).
        m.idle_ticks = m.idle_ticks.wrapping_add(1);
        if m.pane == Pane::Projects {
            m.tick_projects();
        }
        if m.idle_ticks.is_multiple_of(4)
            && let Some(repo) = m.repo.as_ref()
        {
            let fp = crate::watch::fingerprint(&watched(repo));
            match m.fingerprint_pending {
                Some(p) if p == fp && fp != m.fingerprint => {
                    m.fingerprint_pending = None;
                    m.refresh();
                }
                _ if fp != m.fingerprint => m.fingerprint_pending = Some(fp),
                _ => m.fingerprint_pending = None,
            }
        }
    }
}

#[derive(PartialEq, Eq)]
enum Flow {
    Continue,
    Quit,
}

fn handle_key(
    terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
    m: &mut Model,
    k: KeyEvent,
) -> Result<Flow, RepoError> {
    // A popup takes every key until it is closed.
    if let Some((_, _, scroll)) = m.popup.as_mut() {
        match k.code {
            KeyCode::Esc | KeyCode::Char('q') | KeyCode::Enter => m.popup = None,
            KeyCode::Char('j') | KeyCode::Down => *scroll = scroll.saturating_add(1),
            KeyCode::Char('k') | KeyCode::Up => *scroll = scroll.saturating_sub(1),
            KeyCode::PageDown => *scroll = scroll.saturating_add(20),
            KeyCode::PageUp => *scroll = scroll.saturating_sub(20),
            _ => {}
        }
        return Ok(Flow::Continue);
    }
    if m.filtering {
        match k.code {
            KeyCode::Esc => {
                m.filter.clear();
                m.filtering = false;
            }
            KeyCode::Enter => m.filtering = false,
            KeyCode::Backspace => {
                m.filter.pop();
            }
            KeyCode::Char(c) => m.filter.push(c),
            _ => {}
        }
        m.select(0);
        return Ok(Flow::Continue);
    }
    if m.show_keys {
        m.show_keys = false;
        return Ok(Flow::Continue);
    }
    // `n` on Projects: a directory is being typed.
    if let Some(buf) = m.new_dir.as_mut() {
        match k.code {
            KeyCode::Esc => m.new_dir = None,
            KeyCode::Backspace => {
                buf.pop();
            }
            KeyCode::Char(c) => buf.push(c),
            KeyCode::Enter => {
                let dir = Utf8PathBuf::from(expand_home(buf.trim()));
                m.new_dir = None;
                if dir.as_str().is_empty() {
                    return Ok(Flow::Continue);
                }
                if let Err(e) = std::fs::create_dir_all(&dir) {
                    m.status = format!("could not create {dir}: {e}");
                    return Ok(Flow::Continue);
                }
                run_child_inherit(terminal, &dir, &["init"])?;
                m.open_project(dir);
            }
            _ => {}
        }
        return Ok(Flow::Continue);
    }
    let n = m.visible().len();
    match (k.code, k.modifiers) {
        (KeyCode::Char('q'), _) | (KeyCode::Char('c'), KeyModifiers::CONTROL) => {
            return Ok(Flow::Quit);
        }
        (KeyCode::Char('?'), _) => m.show_keys = true,
        (KeyCode::Char(d @ '1'..='9'), _) => {
            m.pane = Pane::ALL[(d as u8 - b'1') as usize];
            m.reading = false;
        }
        (KeyCode::Char('0'), _) => {
            m.pane = Pane::Roadmap;
            m.reading = false;
        }
        (KeyCode::Char('t'), _) => {
            m.pane = Pane::Tickets;
            m.reading = false;
        }
        (KeyCode::Char('p'), _) => {
            m.pane = Pane::Projects;
            m.reading = false;
            m.load_projects();
        }
        (KeyCode::Char('n'), _) if m.pane == Pane::Projects => m.new_dir = Some(String::new()),
        (KeyCode::Char('r'), _) if m.pane == Pane::Projects => m.load_projects(),
        (KeyCode::Tab, _) => {
            let i = Pane::ALL.iter().position(|p| *p == m.pane).unwrap_or(0);
            m.pane = Pane::ALL[(i + 1) % Pane::ALL.len()];
            m.reading = false;
            if m.pane == Pane::Projects {
                m.load_projects();
            }
        }
        (KeyCode::BackTab, _) => {
            let i = Pane::ALL.iter().position(|p| *p == m.pane).unwrap_or(0);
            m.pane = Pane::ALL[(i + Pane::ALL.len() - 1) % Pane::ALL.len()];
            m.reading = false;
            if m.pane == Pane::Projects {
                m.load_projects();
            }
        }
        (KeyCode::Char('j'), _) | (KeyCode::Down, _) => {
            if m.reading {
                m.doc_index = (m.doc_index + 1) % m.docs.len().max(1);
            } else if n > 0 {
                m.select((m.selected() + 1).min(n - 1));
            }
        }
        (KeyCode::Char('k'), _) | (KeyCode::Up, _) => {
            if m.reading {
                m.doc_index = (m.doc_index + m.docs.len().max(1) - 1) % m.docs.len().max(1);
            } else {
                m.select(m.selected().saturating_sub(1));
            }
        }
        (KeyCode::Char('/'), _) => {
            m.filtering = true;
            m.filter.clear();
        }
        (KeyCode::Char('r'), _) => m.refresh(),
        (KeyCode::Char('['), _) | (KeyCode::Char(']'), _) if m.pane == Pane::Help => {
            m.reading = true;
            if k.code == KeyCode::Char(']') {
                m.doc_index = (m.doc_index + 1) % m.docs.len().max(1);
            } else {
                m.doc_index = (m.doc_index + m.docs.len().max(1) - 1) % m.docs.len().max(1);
            }
        }
        (KeyCode::Char('d'), _) if m.pane == Pane::Help => m.reading = !m.reading,
        (KeyCode::Char('c'), _) => {
            if let Some(repo) = m.repo.as_ref() {
                let text = crate::commit::message(repo)
                    .unwrap_or_else(|e| format!("could not compose: {e}"));
                m.popup = Some(("commit message (`war commit --write`)".to_owned(), text, 0));
            }
        }
        (KeyCode::Char(' '), _) if m.pane == Pane::Queue => {
            if let Some(i) = m.current_index()
                && !m.checked.remove(&i)
            {
                m.checked.insert(i);
            }
        }
        (KeyCode::Char('a'), _) if m.pane == Pane::Queue => {
            m.checked = (0..m.rows().len()).collect();
        }
        (KeyCode::Char('n'), _) if m.pane == Pane::Queue => m.checked.clear(),
        (KeyCode::Char('s'), _) if m.pane == Pane::Queue => {
            let targets: Vec<String> = m
                .rows()
                .iter()
                .enumerate()
                .filter(|(i, _)| m.checked.contains(i))
                .filter_map(|(_, r)| r.sign_target.clone())
                .collect();
            if targets.is_empty() {
                m.status = "nothing checked — space checks a row, a checks all".to_owned();
            } else if let [t] = targets.as_slice() {
                sign_in_child(terminal, m, t)?;
                m.checked.clear();
                m.refresh();
            } else {
                // More than one: one batch, one dialog (OW-WAR-0072).
                let list = format!("--batch={}", targets.join(","));
                run_child_inherit(terminal, &m.root, &["sign", &list, "--ssh-sign"])?;
                m.status = format!("returned from war sign {list}");
                m.checked.clear();
                m.refresh();
            }
        }
        (KeyCode::Char('v'), _) => {
            if let Some(t) = m.current().and_then(|r| r.sign_target.clone()) {
                let out = run_child_captured(&m.root, &["sign", &t, "--show"]);
                m.popup = Some((format!("war sign {t} --show"), out, 0));
            } else if let Some(r) = m.current() {
                m.popup = Some((
                    r.command.clone(),
                    r.detail.clone().unwrap_or_else(|| r.text.clone()),
                    0,
                ));
            }
        }
        (KeyCode::Char('x'), _) => {
            if let Some(argv) = m.current().and_then(|r| r.auto.clone()) {
                if argv.first().is_some_and(|a| a == "war") {
                    let args: Vec<&str> = argv.iter().skip(1).map(String::as_str).collect();
                    let out = run_child_captured(&m.root, &args);
                    m.popup = Some((argv.join(" "), out, 0));
                    m.refresh();
                } else {
                    m.popup = Some((
                        "not run from here".to_owned(),
                        format!(
                            "{}\n\nThis remedy is not a `war` command; run it in a shell.",
                            argv.join(" ")
                        ),
                        0,
                    ));
                }
            } else {
                m.status = "no auto remedy on this row".to_owned();
            }
        }
        (KeyCode::Enter, _) => match m.pane {
            Pane::Setup => {
                run_child_inherit(terminal, &m.root, &["init"])?;
                // The conversation may have created the repository.
                if m.repo.is_none() {
                    m.repo = Repository::discover(Some(m.root.clone())).ok();
                    if m.repo.is_some() {
                        m.docs = m.load_docs();
                    }
                }
                m.refresh();
            }
            Pane::Queue => {
                if let Some(t) = m.current().and_then(|r| r.sign_target.clone()) {
                    sign_in_child(terminal, m, &t)?;
                    m.refresh();
                }
            }
            Pane::Projects => match m.current_index() {
                Some(i) if m.projects.get(i).is_some_and(|r| !r.missing) => {
                    let root = Utf8PathBuf::from(&m.projects[i].root);
                    m.open_project(root);
                }
                Some(i) if i + 2 == m.rows().len() => m.new_dir = Some(String::new()),
                Some(i) if i + 1 == m.rows().len() => m.pane = Pane::Setup,
                _ => {
                    if let Some(r) = m.current() {
                        m.popup =
                            Some((r.command.clone(), r.detail.clone().unwrap_or_default(), 0));
                    }
                }
            },
            // One editor, two doors: the pane hands the terminal to
            // `war roadmap edit`, which ends in one signature.
            Pane::Roadmap => {
                run_child_inherit(terminal, &m.root, &["roadmap", "edit"])?;
                m.refresh();
            }
            _ => {
                if let Some(t) = m.current().and_then(|r| r.sign_target.clone()) {
                    sign_in_child(terminal, m, &t)?;
                    m.refresh();
                } else if let Some(r) = m.current() {
                    m.popup = Some((
                        r.command.clone(),
                        r.detail.clone().unwrap_or_else(|| r.command.clone()),
                        0,
                    ));
                }
            }
        },
        _ => {}
    }
    Ok(Flow::Continue)
}

/// `war sign <target> --ssh-sign` in a child that owns the terminal: the
/// app steps out of the alternate screen and raw mode, waits, steps back.
fn sign_in_child(
    terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
    m: &mut Model,
    target: &str,
) -> Result<(), RepoError> {
    run_child_inherit(terminal, &m.root, &["sign", target, "--ssh-sign"])?;
    m.status = format!("returned from war sign {target}");
    Ok(())
}

fn run_child_inherit(
    terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
    root: &Utf8Path,
    args: &[&str],
) -> Result<(), RepoError> {
    term::leave_quietly();
    let exe = std::env::current_exe().map_err(io("could not find this executable"))?;
    let mut stdout = std::io::stdout();
    let _ = writeln!(stdout, "$ war {}", args.join(" "));
    let status = std::process::Command::new(exe)
        .arg("--root")
        .arg(root.as_str())
        .args(args)
        .current_dir(root)
        .status();
    let _ = writeln!(
        stdout,
        "\n[war {} exited {}] — press Enter to return",
        args.join(" "),
        status.as_ref().map_or(-1, |s| s.code().unwrap_or(-1))
    );
    let mut line = String::new();
    let _ = std::io::stdin().read_line(&mut line);
    let _ = term::Guard::enter().map(std::mem::forget);
    terminal
        .clear()
        .map_err(io("could not clear the terminal"))?;
    Ok(())
}

/// `~/x` → `$HOME/x`: a directory typed at the prompt reads as a shell would.
fn expand_home(s: &str) -> String {
    match (s.strip_prefix("~/"), std::env::var("HOME")) {
        (Some(rest), Ok(home)) => format!("{home}/{rest}"),
        _ if s == "~" => std::env::var("HOME").unwrap_or_else(|_| s.to_owned()),
        _ => s.to_owned(),
    }
}

/// A child whose output the app shows in a popup: `--show`, an auto remedy.
fn run_child_captured(root: &Utf8Path, args: &[&str]) -> String {
    let Ok(exe) = std::env::current_exe() else {
        return "could not find this executable".to_owned();
    };
    match std::process::Command::new(exe)
        .arg("--root")
        .arg(root.as_str())
        .args(args)
        .current_dir(root)
        .output()
    {
        Ok(out) => {
            let mut s = String::from_utf8_lossy(&out.stdout).into_owned();
            let err = String::from_utf8_lossy(&out.stderr);
            if !err.trim().is_empty() {
                s.push_str("\n--- stderr ---\n");
                s.push_str(&err);
            }
            s.push_str(&format!("\n[exit {}]", out.status.code().unwrap_or(-1)));
            s
        }
        Err(e) => format!("could not run war {}: {e}", args.join(" ")),
    }
}

