//! The `war` binary.
//!
//! Every command lives in the `openwarrant_cli` library; this target is the
//! argv adapter, so the CLI, an integration test and an embedding caller all
//! run the same code instead of the first one reaching it through a process.
//!
//! The two tests below stay HERE rather than moving to the library with
//! everything else. `async_lives_only_in_the_mcp_module` excludes itself from
//! its own walk by `file!()`, and `file!()` in a library is `lib.rs` — which
//! every crate in this workspace also has, so the exclusion would silently
//! spread to `openwarrant-core`, `openwarrant-compiler` and
//! `openwarrant-agent`. The test would keep passing while policing three
//! fewer crates. It also contains the needle literals it searches for, which
//! is the other reason it must live inside the file it skips.

#![forbid(unsafe_code)]

fn main() -> std::process::ExitCode {
    openwarrant_cli::entrypoint()
}

#[cfg(test)]
mod tests {
    use clap::CommandFactory;

    /// §76.4 says EVERY command should support `--json`. This is the ratchet:
    /// the subcommands that still print only for humans are listed here, by
    /// name, and a new subcommand cannot ship without either supporting the
    /// envelope or being added to this list on purpose. The list shrinks; it
    /// does not grow silently.
    /// OW-ADR-0014: async is admitted for the MCP transport only. Every source
    /// file of the workspace outside `openwarrant-cli/src/mcp/` is read here;
    /// the first `tokio`, `rmcp` or `async fn` outside that directory fails.
    #[test]
    fn async_lives_only_in_the_mcp_module() {
        fn walk(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
            for entry in std::fs::read_dir(dir).expect("readable dir").flatten() {
                let path = entry.path();
                if path.is_dir() {
                    walk(&path, out);
                } else if path.extension().is_some_and(|e| e == "rs") {
                    out.push(path);
                }
            }
        }
        let crates = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("..");
        let mut files = Vec::new();
        walk(&crates, &mut files);
        assert!(files.len() > 40, "walked too few files: {}", files.len());
        let this = std::path::Path::new(file!())
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("main.rs");
        let mut offenders = Vec::new();
        for path in files {
            let rel = path
                .strip_prefix(&crates)
                .unwrap_or(&path)
                .to_string_lossy()
                .replace('\\', "/");
            if rel.starts_with("openwarrant-cli/src/mcp/")
                || rel.ends_with(this)
                || rel.contains("/target/")
            {
                continue;
            }
            let text = std::fs::read_to_string(&path).expect("readable source");
            for needle in ["tokio", "rmcp", "async fn"] {
                if text
                    .lines()
                    .any(|l| !l.trim_start().starts_with("//") && l.contains(needle))
                {
                    offenders.push(format!("{rel}: {needle}"));
                }
            }
        }
        assert!(
            offenders.is_empty(),
            "async or the MCP SDK outside openwarrant-cli/src/mcp/ (OW-ADR-0014): {offenders:?}"
        );
    }

    /// OW-ADR-0020: ratatui and crossterm are admitted under `src/tui/` only —
    /// the same shape as the async confinement above, so a pane cannot grow
    /// in a file the app's declaration never named.
    #[test]
    fn the_terminal_library_lives_only_in_the_tui_module() {
        fn walk(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
            for entry in std::fs::read_dir(dir).expect("readable dir").flatten() {
                let path = entry.path();
                if path.is_dir() {
                    walk(&path, out);
                } else if path.extension().is_some_and(|e| e == "rs") {
                    out.push(path);
                }
            }
        }
        let crates = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("..");
        let mut files = Vec::new();
        walk(&crates, &mut files);
        assert!(files.len() > 40, "walked too few files: {}", files.len());
        let this = std::path::Path::new(file!())
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("main.rs");
        let mut offenders = Vec::new();
        for path in files {
            let rel = path
                .strip_prefix(&crates)
                .unwrap_or(&path)
                .to_string_lossy()
                .replace('\\', "/");
            if rel.starts_with("openwarrant-cli/src/tui/")
                || rel.ends_with(this)
                || rel.contains("/target/")
            {
                continue;
            }
            let text = std::fs::read_to_string(&path).expect("readable source");
            for needle in ["ratatui", "crossterm"] {
                if text
                    .lines()
                    .any(|l| !l.trim_start().starts_with("//") && l.contains(needle))
                {
                    offenders.push(format!("{rel}: {needle}"));
                }
            }
        }
        assert!(
            offenders.is_empty(),
            "ratatui or crossterm outside openwarrant-cli/src/tui/ (OW-ADR-0020): {offenders:?}"
        );
    }

    #[test]
    fn every_subcommand_supports_json_or_is_listed_as_not_yet() {
        // `mcp` speaks JSON-RPC on stdout; an envelope there would corrupt
        // the transport, so it is listed as not-yet on purpose, not by gap.
        // `tui` is a terminal application: no envelope on purpose, and
        // `war tui --json` says so (OW-WAR-0073 deliverable 6).
        const NOT_YET: &[&str] = &["init", "kf", "telemetry", "migrate", "export", "mcp", "tui"];
        // Built on a thread with the main thread's 8 MiB stack, which is where
        // the binary builds it. libtest's 2 MiB worker is smaller than any
        // `war` process has, and the unoptimized clap tree for every
        // subcommand outgrew it when `war amend` was added (t-dc28): a stack
        // overflow here measured the test harness, not the command.
        let cmd = std::thread::Builder::new()
            .stack_size(8 << 20)
            .spawn(openwarrant_cli::Cli::command)
            .expect("spawn")
            .join()
            .expect("the command tree builds");
        let all: Vec<String> = cmd
            .get_subcommands()
            .map(|c| c.get_name().to_owned())
            .collect();
        assert!(all.len() >= 20, "{all:?}");
        // Every NOT_YET entry must be a real subcommand — a stale name here
        // would make the list look longer than the gap is.
        for n in NOT_YET {
            assert!(
                all.iter().any(|a| a == n),
                "{n} is not a subcommand any more; drop it"
            );
        }
        // The global flag exists and is global.
        let json = cmd
            .get_arguments()
            .find(|a| a.get_id() == "json")
            .expect("--json is a top-level argument");
        assert!(
            json.is_global_set(),
            "--json must be global so it works after the subcommand"
        );
    }
}

// SPDX-License-Identifier: Apache-2.0
//! `war watch` — tell the human when an act is waiting for them.
//!
//! The pending set is `sign::pending` (§27.2's human acts: authorize,
//! resolve, accept, correct). This command polls the record trees every
//! `--interval` milliseconds (default 500), recomputes the set when a file's
//! size or modification time changed, and prints the difference: what
//! appeared, what was signed away. `--notify-send` also raises a desktop
//! notification through `notify-send` when it exists. `--once` prints the set
//! and exits, for scripts and tests.
//!
//! A poller, not an inotify client, on purpose: the three trees are small,
//! a 500 ms scan of a few hundred files is nothing, and it adds no crate.
//! It never reads outside the record trees and never writes.

use std::collections::BTreeSet;
use std::time::{Duration, SystemTime};

use camino::Utf8Path;
use serde::Serialize;

use crate::repo::{RepoError, Repository};
use crate::sign;

pub const SCHEMA: &str = "oh.war/watch/v1";

#[derive(Debug, Clone, Serialize)]
pub struct Snapshot {
    pub schema: String,
    /// One line per pending act, as `war sign --list` prints them.
    pub pending: Vec<String>,
    pub count: usize,
    /// Open questions, blocking first (OW-WAR-0069): the other thing a human
    /// is the only one who can clear.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub questions: Vec<String>,
}

/// The trees whose change can change the pending set. `pub(crate)`: the app
/// polls the same fingerprint (OW-WAR-0112), one poller and not two.
pub(crate) fn watched_dirs(repo: &Repository) -> Vec<camino::Utf8PathBuf> {
    vec![
        repo.root.join(&repo.config.paths.warrants),
        repo.root.join("docs/authority"),
        repo.root.join(&repo.config.paths.sas).join("revisions"),
    ]
}

/// A cheap fingerprint of the trees: every file's path, length and mtime,
/// skipping `generated/` (projections change without the pending set).
pub(crate) fn fingerprint(dirs: &[camino::Utf8PathBuf]) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut h = std::collections::hash_map::DefaultHasher::new();
    fn walk(dir: &Utf8Path, h: &mut std::collections::hash_map::DefaultHasher) {
        let Ok(rd) = std::fs::read_dir(dir) else {
            return;
        };
        let mut entries: Vec<_> = rd.filter_map(Result::ok).collect();
        entries.sort_by_key(std::fs::DirEntry::file_name);
        for e in entries {
            let path = e.path();
            let name = e.file_name();
            if name == "generated" {
                continue;
            }
            if path.is_dir() {
                if let Ok(p) = camino::Utf8PathBuf::from_path_buf(path) {
                    walk(&p, h);
                }
                continue;
            }
            if let Ok(meta) = e.metadata() {
                path.hash(h);
                meta.len().hash(h);
                meta.modified()
                    .ok()
                    .and_then(|t| t.duration_since(SystemTime::UNIX_EPOCH).ok())
                    .map(|d| d.as_nanos())
                    .hash(h);
            }
        }
    }
    for d in dirs {
        walk(d, &mut h);
    }
    h.finish()
}

pub fn snapshot(repo: &Repository) -> Result<Snapshot, RepoError> {
    let pending: Vec<String> = sign::pending(repo)?.iter().map(sign::line).collect();
    // An open question costs the owner a sentence and an agent its whole
    // stage, so it waits in the same place a signature does (OW-WAR-0069).
    // An incomplete store cannot become an apparently complete signing queue.
    // `war questions` retains the individual diagnostics and readable records.
    let questions: Vec<String> = crate::questions::complete_list(repo, true).map(|l| {
        l.questions
            .iter()
            .map(|q| {
                format!(
                    "{} {}  {}{}",
                    q.warrant,
                    q.id,
                    if q.blocking { "BLOCKING  " } else { "" },
                    q.question
                )
            })
            .collect()
    })?;
    Ok(Snapshot {
        schema: SCHEMA.to_owned(),
        count: pending.len() + questions.len(),
        pending,
        questions,
    })
}

pub fn render(s: &Snapshot) -> String {
    if s.pending.is_empty() && s.questions.is_empty() {
        return "nothing awaits a human\n".to_owned();
    }
    let mut out = format!("{} thing(s) await a human:\n", s.count);
    for l in &s.pending {
        out.push_str("  ");
        out.push_str(l);
        out.push('\n');
    }
    for q in &s.questions {
        out.push_str("  question  ");
        out.push_str(q);
        out.push('\n');
    }
    out
}

/// A pipe is block-buffered; a watcher whose lines arrive at exit is useless.
/// A stdout nobody reads any more (a closed pipe) ends the watch rather than
/// leaving a loop that hashes for nobody.
fn flush() -> Result<(), RepoError> {
    use std::io::Write;
    std::io::stdout().flush().map_err(|source| RepoError::Io {
        context: "stdout is gone; stopping the watch".to_owned(),
        source,
    })
}

fn notify_send(title: &str, body: &str) {
    let _ = std::process::Command::new("notify-send")
        .arg(title)
        .arg(body)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status();
}

/// Watch until interrupted. `max_ticks` bounds the loop for tests.
pub fn run(
    repo: &Repository,
    interval_ms: u64,
    desktop: bool,
    max_ticks: Option<u64>,
) -> Result<(), RepoError> {
    let dirs = watched_dirs(repo);
    // Fingerprint BEFORE the snapshot: computing the pending set builds every
    // request and takes a moment, and a change that lands meanwhile must be
    // seen on the next tick, not folded silently into the first set.
    let mut fp = fingerprint(&dirs);
    let mut last = snapshot(repo)?;
    print!("{}", render(&last));
    flush()?;
    if desktop && !last.pending.is_empty() {
        notify_send("OpenWarrant", &render(&last));
    }
    let interval = Duration::from_millis(interval_ms.max(50));
    let mut ticks = 0u64;
    loop {
        std::thread::sleep(interval);
        ticks = ticks.saturating_add(1);
        if max_ticks.is_some_and(|m| ticks >= m) {
            return Ok(());
        }
        let now_fp = fingerprint(&dirs);
        if now_fp == fp {
            continue;
        }
        fp = now_fp;
        // A register that cannot be read is said loudly, once per change,
        // and the loop goes on: the operator is exactly who should see it.
        let now = match snapshot(repo) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("watch: {e}");
                continue;
            }
        };
        let before: BTreeSet<&String> = last.pending.iter().collect();
        let after: BTreeSet<&String> = now.pending.iter().collect();
        let appeared: Vec<&&String> = after.difference(&before).collect();
        let gone: Vec<&&String> = before.difference(&after).collect();
        if appeared.is_empty() && gone.is_empty() {
            last = now;
            continue;
        }
        let mut msg = String::new();
        for a in &appeared {
            msg.push_str(&format!("+ {a}\n"));
        }
        for g in &gone {
            msg.push_str(&format!("- {g}\n"));
        }
        print!("{msg}");
        flush()?;
        if desktop && !appeared.is_empty() {
            notify_send(
                &format!("OpenWarrant: {} act(s) await you", now.count),
                &appeared
                    .iter()
                    .map(|a| a.as_str())
                    .collect::<Vec<_>>()
                    .join("\n"),
            );
        }
        last = now;
    }
}

//! `war sas repin` — the sixty-five warnings become one act (OW-WAR-0112 M5).
//!
//! A Warrant authorized against SAS 1.0.0 keeps that Basis after 1.1.0 is
//! accepted (OW-ADR-0016): the contract is what was signed. `war check`
//! says so, once per Warrant, as `sas.pin-superseded`, and until now the
//! only way to clear one was to write an amendment by hand. This command
//! writes it — `amendments/AM-<next>-<hash>.yaml` (`crate::amendment_id`:
//! two branches re-pinning the same Warrant write two files, not one) carrying `sas_revision` and
//! `predecessor_sas_revision`, in the exact shape `88-sas-repin.sh` already
//! exercises — for one Warrant or for every authorized, unresolved one whose
//! pin is behind the latest revision. The re-pin moves the contract digest,
//! so each Warrant then shows `authorize rev N+1 [AM-nnn]` in the queue and
//! a human re-authorizes it. That signature is the act; this is paperwork.
//!
//! Refused by name: a Warrant whose manifest implements a §106 row the
//! latest revision lacks (`sas.repin-unknown-requirement`), and — when
//! named — a resolved Warrant (`sas.repin-resolved`: the resolution binds
//! the contract as it was, §56.3). Under `--all`, resolved Warrants are
//! skipped, and after OW-WAR-0112 phase B they no longer warn at all.
//! All-or-nothing: one refusal in the set and nothing is written.
//!
//! Stated in the output rather than discovered later: a receipt bound to
//! the old contract digest reads `evidence.stale-binding` after the re-pin;
//! `war evidence record <alias>` mints new ones.

use camino::Utf8PathBuf;

use crate::diagnostic::{Diagnostic, Report};
use crate::repo::{RepoError, Repository};

#[derive(Debug, Clone, Default)]
pub struct Options {
    pub alias: Option<String>,
    pub all: bool,
    pub reason: Option<String>,
    pub dry_run: bool,
}

/// One re-pin the command would write.
#[derive(Debug, Clone)]
struct Plan {
    alias: String,
    dir: Utf8PathBuf,
    id: String,
    from: String,
    to: String,
    authorizer: String,
}

pub fn run(repo: &Repository, opts: &Options) -> Result<Report, RepoError> {
    let mut report = Report::default();
    let Some(latest) = repo.latest_sas_revision()? else {
        report.push(Diagnostic::error(
            "sas.unrecorded",
            repo.relative(&repo.root.join(&repo.config.paths.sas)),
            "no SAS revision is recorded; `war sas propose <version>` first",
        ));
        return Ok(report);
    };
    let dirs: Vec<Utf8PathBuf> = match (&opts.alias, opts.all) {
        (Some(alias), _) => vec![repo.warrant_dir(alias)?],
        (None, true) => repo.warrant_dirs()?,
        (None, false) => {
            report.push(Diagnostic::error(
                "sas.repin-target",
                "-".to_owned(),
                "name a Warrant (`war sas repin <alias>`) or pass `--all`",
            ));
            return Ok(report);
        }
    };
    let named = opts.alias.is_some();

    let mut plans = Vec::new();
    let mut refused = 0usize;
    for dir in dirs {
        let alias = dir.file_name().unwrap_or("?").to_owned();
        let Some(auth) = repo.load_authorization(&dir)? else {
            if named {
                report.push(Diagnostic::error(
                    "sas.repin-unauthorized",
                    repo.relative(&dir.join("manifest.toml")),
                    format!("{alias}: not authorized; there is no pin to move — a draft compiles against the latest revision on its own"),
                ));
                refused += 1;
            }
            continue;
        };
        if repo.load_resolution(&dir)?.is_some() {
            if named {
                report.push(Diagnostic::error(
                    "sas.repin-resolved",
                    repo.relative(&dir.join("resolution.toml")),
                    format!("{alias}: resolved; the resolution binds the contract as it was and a re-pin would only read stale (§56.3). Nothing to re-pin"),
                ));
                refused += 1;
            }
            continue;
        }
        let amended = crate::repo::amendment_sas_revision(&dir).map(|(v, _)| v);
        let Some(pin) = amended.or_else(|| auth.sas_revision.clone()) else {
            if named {
                report.push(Diagnostic::warn(
                    "sas.repin-unpinned",
                    repo.relative(&dir.join("authorization.toml")),
                    format!("{alias}: authorized with no SAS pin at all (before OW-ADR-0016); nothing to move from"),
                ));
            }
            continue;
        };
        if pin == latest.version {
            if named {
                report.push(Diagnostic::pass(
                    "sas.repin-current",
                    format!("{alias}: already pinned to SAS {}", latest.version),
                ));
            }
            continue;
        }
        // Every row the manifest implements must exist in the target
        // revision; a requirement that vanished under it is a broken trace.
        let one = repo.load_warrant(&dir)?;
        let mut missing = Vec::new();
        if let Some(basis) = &one.basis {
            for i in &basis.manifest.implements {
                if let Ok(rq) = openwarrant_core::traceability::RequirementRef::parse(&i.r#ref)
                    && !latest.requirements.contains_key(&rq.canonical())
                {
                    missing.push(i.r#ref.clone());
                }
            }
        }
        if !missing.is_empty() {
            report.push(Diagnostic::error(
                "sas.repin-unknown-requirement",
                repo.relative(&dir.join("manifest.toml")),
                format!(
                    "{alias}: implements {} and SAS {}'s §106 has no such row — re-pinning would \
                     leave the Warrant implementing nothing; amend the manifest first",
                    missing.join(", "),
                    latest.version
                ),
            ));
            refused += 1;
            continue;
        }
        let authorizer = auth
            .revision
            .authorization
            .as_ref()
            .map(|a| a.authorizer.clone())
            .unwrap_or_default();
        plans.push(Plan {
            id: crate::amendment_id::mint(&dir),
            alias,
            dir,
            from: pin,
            to: latest.version.clone(),
            authorizer,
        });
    }

    if plans.is_empty() && refused == 0 {
        report.push(Diagnostic::pass(
            "sas.repin-nothing",
            format!(
                "every authorized, unresolved Warrant is pinned to SAS {} already",
                latest.version
            ),
        ));
        return Ok(report);
    }
    if refused > 0 {
        report.push(Diagnostic::error(
            "sas.repin-refused",
            "-".to_owned(),
            format!("{refused} refusal(s) above; nothing written (all-or-nothing)"),
        ));
        return Ok(report);
    }

    let today = crate::gate_cmd::receipt::rfc3339_from_secs(
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |d| d.as_secs()),
    );
    let today = today.get(..10).unwrap_or(&today).to_owned();
    for p in &plans {
        let path = p.dir.join("amendments").join(format!("{}.yaml", p.id));
        let rel = repo.relative(&path);
        if opts.dry_run {
            report.push(Diagnostic::pass(
                "sas.repin-would-write",
                format!(
                    "{}: {rel} would re-pin SAS {} → {}; `war sign {} --ssh-sign` would then be revision N+1",
                    p.alias, p.from, p.to, p.alias
                ),
            ));
            continue;
        }
        std::fs::create_dir_all(p.dir.join("amendments")).map_err(|source| RepoError::Io {
            context: format!("could not create {}/amendments", p.dir),
            source,
        })?;
        std::fs::write(&path, render(p, opts.reason.as_deref(), &today)).map_err(|source| {
            RepoError::Io {
                context: format!("could not write {path}"),
                source,
            }
        })?;
        report.push(Diagnostic::pass(
            "sas.repin-written",
            format!(
                "{}: {rel} re-pins SAS {} → {}; a human re-authorizes: `war sign {} --ssh-sign` (revision N+1, [{}])",
                p.alias, p.from, p.to, p.alias, p.id
            ),
        ));
    }
    report.note(format!(
        "A re-pin moves the contract digest. Receipts bound to the old digest read \
         `evidence.stale-binding` until `war evidence record <alias>` mints new ones; the \
         amendment is a draft until the signature — `war sign --all --dry-run` shows what \
         each would meet. {} Warrant(s){}",
        plans.len(),
        if opts.dry_run {
            ", nothing written"
        } else {
            ""
        }
    ));
    Ok(report)
}

/// The amendment, in the shape `88-sas-repin.sh` plants and `check` reads
/// (`sas_revision:` line-wise). `basis_requirements` is the §28.5 element
/// that moved.
fn render(p: &Plan, reason: Option<&str>, today: &str) -> String {
    let reason = reason.map_or_else(
        || {
            format!(
                "Re-pin to SAS {} (from {}), written by `war sas repin` on {today}. The Basis \
                 names the revision in force; the contract's own text is unchanged. The \
                 authorizer adopts this record by signing revision N+1.",
                p.to, p.from
            )
        },
        str::to_owned,
    );
    format!(
        "schema: \"oh.war/amendment/v1\"\n\
         \n\
         id: {id:?}\n\
         band: \"manual_revision\"\n\
         reason: {reason:?}\n\
         governing_adr_or_policy: \"adr://OW-ADR-0016\"\n\
         artifact_admissibility: \"remain_admissible\"\n\
         restart_or_repair_instruction: \"Continue; the Basis names a newer SAS revision. Receipts bound to the old contract digest are re-minted with `war evidence record {alias}`.\"\n\
         re_preflight_required: \"false\"\n\
         authorizer: {authorizer:?}\n\
         effective_time: {today:?}\n\
         sas_revision: {to:?}\n\
         predecessor_sas_revision: {from:?}\n\
         \n\
         semantic_diff:\n  \
           - element: \"basis_requirements\"\n    \
             before: \"pinned to SAS {from}\"\n    \
             after: \"pinned to SAS {to}\"\n\
         \n\
         affected_stages: []\n\
         affected_milestones: []\n",
        id = p.id,
        alias = p.alias,
        authorizer = p.authorizer,
        to = p.to,
        from = p.from,
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_rendered_amendment_carries_the_pin_check_reads() {
        let p = Plan {
            alias: "OW-WAR-0047".into(),
            dir: Utf8PathBuf::from("x"),
            id: "AM-002".into(),
            from: "1.0.0".into(),
            to: "1.1.0".into(),
            authorizer: "Brian Lam".into(),
        };
        let text = render(&p, None, "2026-09-22");
        assert!(text.contains("sas_revision: \"1.1.0\"\n"));
        assert!(text.contains("predecessor_sas_revision: \"1.0.0\"\n"));
        assert!(text.contains("id: \"AM-002\"\n"));
        assert!(text.contains("authorizer: \"Brian Lam\"\n"));
        assert!(text.contains("element: \"basis_requirements\""));
        // The exact line-wise reader `check` uses finds the pin.
        let found = text
            .lines()
            .find_map(|l| l.strip_prefix("sas_revision:"))
            .map(|v| v.trim().trim_matches('"').to_owned());
        assert_eq!(found.as_deref(), Some("1.1.0"));
    }

    #[test]
    fn the_next_id_counts_past_the_highest_existing_one() {
        let dir = Utf8PathBuf::from_path_buf(std::env::temp_dir())
            .unwrap()
            .join(format!("war-repin-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        assert!(crate::amendment_id::mint(&dir).starts_with("AM-001-"));
        std::fs::create_dir_all(dir.join("amendments")).unwrap();
        std::fs::write(dir.join("amendments/AM-003.yaml"), "x").unwrap();
        std::fs::write(dir.join("amendments/AM-001.yaml"), "x").unwrap();
        let id = crate::amendment_id::mint(&dir);
        assert!(id.starts_with("AM-004-"), "{id}");
        assert!(crate::amendment_id::AmendmentId::parse(&id).is_ok(), "{id}");
        let _ = std::fs::remove_dir_all(&dir);
    }
}

